# ============================= UTILIDADES =============================
MONTHS_ES = {
    1: "Enero",
    2: "Febrero",
    3: "Marzo",
    4: "Abril",
    5: "Mayo",
    6: "Junio",
    7: "Julio",
    8: "Agosto",
    9: "Septiembre",
    10: "Octubre",
    11: "Noviembre",
    12: "Diciembre",
}


def normalize_text(value: Any) -> str:
    if value is None:
        return ""
    text = str(value).replace("\xa0", " ").strip()
    text = " ".join(text.split())
    normalized = unicodedata.normalize("NFKD", text)
    return "".join(ch for ch in normalized if not unicodedata.combining(ch)).upper()


def slug_code(value: Any, prefix: str = "") -> str:
    text = normalize_text(value)
    text = re.sub(r"[^A-Z0-9]+", "-", text).strip("-")
    if prefix:
        return f"{prefix}-{text}"[:50]
    return text[:50]


def parse_number(value: Any) -> float | None:
    if value is None or (isinstance(value, float) and math.isnan(value)):
        return None
    if isinstance(value, (int, float, Decimal)):
        return float(value)
    text = str(value).strip()
    if not text or normalize_text(text) in {"NAN", "NONE", "NULL", "-"}:
        return None
    text = text.replace("$", "").replace("%", "").replace(" ", "")
    # Handle Venezuelan/Spanish formatting: 44.966,82 -> 44966.82.
    if "," in text and "." in text:
        if text.rfind(",") > text.rfind("."):
            text = text.replace(".", "").replace(",", ".")
        else:
            text = text.replace(",", "")
    elif "," in text:
        parts = text.split(",")
        if len(parts[-1]) in {1, 2, 3}:
            text = "".join(parts[:-1]) + "." + parts[-1]
        else:
            text = text.replace(",", "")
    else:
        # A single dot with exactly three trailing digits is likely a thousands separator.
        if text.count(".") == 1 and len(text.split(".")[-1]) == 3:
            text = text.replace(".", "")
    text = re.sub(r"[^0-9.\-]", "", text)
    try:
        return float(Decimal(text))
    except (InvalidOperation, ValueError):
        return None


def safe_int(value: Any, default: int = 0) -> int:
    num = parse_number(value)
    return int(round(num)) if num is not None else default


def safe_float(value: Any, default: float = 0.0) -> float:
    num = parse_number(value)
    return float(num) if num is not None else default


def clean_cell(value: Any) -> Any:
    if isinstance(value, pd.Timestamp):
        return value.isoformat()
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if pd.isna(value) if not isinstance(value, (list, dict, tuple, set)) else False:
        return None
    if isinstance(value, (int, float, str)) or value is None:
        return value
    return str(value)


def dataframe_records(df: pd.DataFrame) -> list[dict[str, Any]]:
    return [
        {str(k): clean_cell(v) for k, v in row.items()}
        for row in df.to_dict(orient="records")
    ]


def money(value: Any, decimals: int = 2) -> str:
    num = safe_float(value)
    return f"${num:,.{decimals}f}"


def integer(value: Any) -> str:
    return f"{safe_int(value):,}"


def percent(value: Any, decimals: int = 1) -> str:
    num = safe_float(value)
    return f"{num * 100:.{decimals}f}%"


def period_label(period: str) -> str:
    try:
        year, month = period.split("-")[:2]
        return f"{MONTHS_ES[int(month)]} {year}"
    except Exception:
        return period


def period_start_end(period: str) -> tuple[date, date]:
    year, month = [int(v) for v in period.split("-")[:2]]
    return date(year, month, 1), date(year, month, monthrange(year, month)[1])


def business_days(period: str, as_of: date | None = None, include_saturday: bool = False) -> tuple[int, int]:
    start, end = period_start_end(period)
    cutoff = min(as_of or date.today(), end)
    total = 0
    elapsed = 0
    day = start
    while day <= end:
        is_business = day.weekday() < 5 or (include_saturday and day.weekday() == 5)
        if is_business:
            total += 1
            if day <= cutoff:
                elapsed += 1
        day += timedelta(days=1)
    return elapsed, total


def run_rate(sales_to_date: float, period: str, as_of: date | None = None, include_saturday: bool = False) -> float:
    elapsed, total = business_days(period, as_of=as_of, include_saturday=include_saturday)
    if elapsed <= 0:
        return 0.0
    return sales_to_date / elapsed * total


def classify_performance(
    activation_pct: float,
    sales_pct: float,
    activation_green: float = 0.60,
    activation_yellow: float = 0.45,
    sales_green: float = 1.00,
    sales_yellow: float = 0.85,
) -> tuple[str, str]:
    if sales_pct >= sales_green and activation_pct >= activation_green:
        return "ALTO DESEMPEÑO", "green"
    if sales_pct >= sales_green and activation_pct < activation_yellow:
        return "SEGUIMIENTO", "yellow"
    if sales_pct >= sales_yellow or activation_pct >= activation_green:
        return "SEGUIMIENTO", "yellow"
    if sales_pct >= 0.50 or activation_pct >= activation_yellow:
        return "RECUPERACIÓN", "orange"
    return "CRÍTICO", "red"


def priority_message(activation_pct: float, sales_pct: float) -> str:
    if sales_pct >= 1 and activation_pct < 0.45:
        return "Venta alta concentrada en pocos clientes: ampliar cobertura de cartera."
    if sales_pct < 0.85 and activation_pct >= 0.60:
        return "Buena cobertura, pero falta volumen o ticket promedio."
    if sales_pct < 0.50 and activation_pct < 0.45:
        return "Intervención inmediata: revisar CXC, ruta, inventario y conversión."
    if sales_pct >= 1 and activation_pct >= 0.60:
        return "Desempeño saludable: sostener ritmo y ampliar venta cruzada."
    return "Seguimiento semanal de activación, volumen y clientes nuevos."


def canonical_column(value: Any) -> str:
    text = normalize_text(value).lower()
    text = re.sub(r"[^a-z0-9]+", "_", text).strip("_")
    return text


def first_existing(columns: Iterable[str], aliases: Iterable[str]) -> str | None:
    normalized = {canonical_column(c): c for c in columns}
    for alias in aliases:
        key = canonical_column(alias)
        if key in normalized:
            return normalized[key]
    return None


def safe_filename(text: str) -> str:
    clean = re.sub(r"[^A-Za-z0-9_\-]+", "_", normalize_text(text).title().replace(" ", "_"))
    return clean.strip("_") or "reporte"


# ============================= BASE DE DATOS =============================
SCHEMA_SQL = """
PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;

CREATE TABLE IF NOT EXISTS meta (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS supervisors (
    supervisor_code TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    manager_name TEXT,
    region TEXT,
    active INTEGER NOT NULL DEFAULT 1,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS advisors (
    advisor_code TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    supervisor_code TEXT NOT NULL,
    state TEXT,
    zone TEXT,
    active INTEGER NOT NULL DEFAULT 1,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (supervisor_code) REFERENCES supervisors(supervisor_code)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS monthly_summary (
    period TEXT NOT NULL,
    supervisor_code TEXT NOT NULL,
    portfolio INTEGER NOT NULL DEFAULT 0,
    activated INTEGER NOT NULL DEFAULT 0,
    quota REAL NOT NULL DEFAULT 0,
    sales REAL NOT NULL DEFAULT 0,
    source TEXT NOT NULL,
    is_official INTEGER NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (period, supervisor_code, is_official),
    FOREIGN KEY (supervisor_code) REFERENCES supervisors(supervisor_code)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS advisor_performance (
    period TEXT NOT NULL,
    advisor_code TEXT NOT NULL,
    portfolio INTEGER NOT NULL DEFAULT 0,
    activated INTEGER NOT NULL DEFAULT 0,
    new_goal INTEGER NOT NULL DEFAULT 0,
    new_achieved INTEGER NOT NULL DEFAULT 0,
    sales_goal REAL NOT NULL DEFAULT 0,
    sales_actual REAL NOT NULL DEFAULT 0,
    brand_goal_count INTEGER NOT NULL DEFAULT 0,
    brand_achieved_count INTEGER NOT NULL DEFAULT 0,
    observations TEXT,
    source TEXT NOT NULL DEFAULT 'MANUAL',
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (period, advisor_code),
    FOREIGN KEY (advisor_code) REFERENCES advisors(advisor_code)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS brand_performance (
    period TEXT NOT NULL,
    advisor_code TEXT NOT NULL,
    dimension TEXT NOT NULL DEFAULT 'LINEA / MARCA',
    brand TEXT NOT NULL,
    goal REAL,
    actual REAL,
    units REAL,
    source TEXT NOT NULL DEFAULT 'MANUAL',
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (period, advisor_code, dimension, brand),
    FOREIGN KEY (advisor_code) REFERENCES advisors(advisor_code)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS channels (
    channel TEXT PRIMARY KEY,
    short_code TEXT,
    source TEXT,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS products (
    product_code TEXT PRIMARY KEY,
    description TEXT NOT NULL,
    brand TEXT,
    category TEXT,
    department TEXT,
    product_line TEXT,
    uom TEXT,
    active INTEGER NOT NULL DEFAULT 1,
    source TEXT,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS clients (
    client_code TEXT PRIMARY KEY,
    rif TEXT,
    name TEXT NOT NULL,
    channel TEXT,
    state TEXT,
    city TEXT,
    zone TEXT,
    advisor_code TEXT,
    status TEXT NOT NULL DEFAULT 'ACTIVO',
    is_new INTEGER NOT NULL DEFAULT 0,
    route_week INTEGER,
    route_day TEXT,
    source TEXT,
    notes TEXT,
    phone TEXT,
    email TEXT,
    address TEXT,
    latitude REAL,
    longitude REAL,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (advisor_code) REFERENCES advisors(advisor_code)
        ON UPDATE CASCADE ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS visits (
    visit_id INTEGER PRIMARY KEY AUTOINCREMENT,
    visit_date TEXT NOT NULL,
    advisor_code TEXT NOT NULL,
    client_code TEXT NOT NULL,
    result TEXT NOT NULL,
    reason TEXT,
    amount_reported REAL NOT NULL DEFAULT 0,
    amount_collected REAL NOT NULL DEFAULT 0,
    next_action TEXT,
    next_visit_date TEXT,
    notes TEXT,
    latitude REAL,
    longitude REAL,
    source TEXT NOT NULL DEFAULT 'FORMULARIO',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (advisor_code) REFERENCES advisors(advisor_code)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY (client_code) REFERENCES clients(client_code)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS sales (
    sale_id INTEGER PRIMARY KEY AUTOINCREMENT,
    sale_date TEXT NOT NULL,
    document_no TEXT NOT NULL,
    line_no TEXT NOT NULL DEFAULT '1',
    advisor_code TEXT,
    client_code TEXT,
    product_code TEXT,
    product_description TEXT,
    brand TEXT,
    category TEXT,
    units REAL NOT NULL DEFAULT 0,
    net_amount REAL NOT NULL DEFAULT 0,
    cost REAL,
    currency TEXT NOT NULL DEFAULT 'USD',
    exchange_rate REAL,
    source_hash TEXT,
    source TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (document_no, line_no, source_hash),
    FOREIGN KEY (advisor_code) REFERENCES advisors(advisor_code)
        ON UPDATE CASCADE ON DELETE SET NULL,
    FOREIGN KEY (client_code) REFERENCES clients(client_code)
        ON UPDATE CASCADE ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS cxc (
    cxc_id INTEGER PRIMARY KEY AUTOINCREMENT,
    cutoff_date TEXT NOT NULL,
    client_code TEXT,
    document_no TEXT,
    issue_date TEXT,
    due_date TEXT,
    balance REAL NOT NULL DEFAULT 0,
    currency TEXT NOT NULL DEFAULT 'USD',
    advisor_code TEXT,
    source_hash TEXT,
    source TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (cutoff_date, client_code, document_no, source_hash)
);

CREATE TABLE IF NOT EXISTS inventory (
    inventory_id INTEGER PRIMARY KEY AUTOINCREMENT,
    cutoff_date TEXT NOT NULL,
    branch TEXT,
    warehouse TEXT,
    product_code TEXT NOT NULL,
    product_description TEXT,
    brand TEXT,
    stock REAL NOT NULL DEFAULT 0,
    committed REAL NOT NULL DEFAULT 0,
    available REAL NOT NULL DEFAULT 0,
    cost REAL,
    source_hash TEXT,
    source TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (cutoff_date, branch, warehouse, product_code, source_hash)
);

CREATE TABLE IF NOT EXISTS data_quality (
    issue_id INTEGER PRIMARY KEY AUTOINCREMENT,
    period TEXT,
    scope TEXT,
    severity TEXT NOT NULL DEFAULT 'MEDIA',
    title TEXT NOT NULL,
    detail TEXT,
    expected TEXT,
    observed TEXT,
    source_a TEXT,
    source_b TEXT,
    status TEXT NOT NULL DEFAULT 'PENDIENTE',
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (period, scope, title)
);

CREATE TABLE IF NOT EXISTS import_log (
    import_id INTEGER PRIMARY KEY AUTOINCREMENT,
    filename TEXT NOT NULL,
    file_hash TEXT NOT NULL UNIQUE,
    detected_type TEXT,
    imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    user_name TEXT,
    rows_received INTEGER NOT NULL DEFAULT 0,
    rows_imported INTEGER NOT NULL DEFAULT 0,
    rows_rejected INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL,
    notes TEXT
);

CREATE TABLE IF NOT EXISTS settings (
    key TEXT PRIMARY KEY,
    value TEXT,
    description TEXT,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_perf_period ON advisor_performance(period);
CREATE INDEX IF NOT EXISTS idx_perf_advisor ON advisor_performance(advisor_code);
CREATE INDEX IF NOT EXISTS idx_brand_period ON brand_performance(period);
CREATE INDEX IF NOT EXISTS idx_brand_advisor ON brand_performance(advisor_code);
CREATE INDEX IF NOT EXISTS idx_product_brand ON products(brand);
CREATE INDEX IF NOT EXISTS idx_client_advisor ON clients(advisor_code);
CREATE INDEX IF NOT EXISTS idx_client_status ON clients(status);
CREATE INDEX IF NOT EXISTS idx_visit_date ON visits(visit_date);
CREATE INDEX IF NOT EXISTS idx_visit_advisor ON visits(advisor_code);
CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(sale_date);
CREATE INDEX IF NOT EXISTS idx_sales_advisor ON sales(advisor_code);
CREATE INDEX IF NOT EXISTS idx_sales_client ON sales(client_code);
"""

