def connect(db_path: Path | str = DB_PATH) -> sqlite3.Connection:
    path = Path(db_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(path, timeout=30, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute("PRAGMA journal_mode = WAL")
    conn.execute("PRAGMA synchronous = NORMAL")
    return conn


def init_database(db_path: Path | str = DB_PATH, seed: bool = True) -> None:
    with connect(db_path) as conn:
        conn.executescript(SCHEMA_SQL)
    if seed:
        seed_database(db_path=db_path, force=False)


def _load_seed(filename: str) -> list[dict[str, Any]]:
    # Copia profunda para que una carga no altere el dato embebido en memoria.
    return json.loads(json.dumps(EMBEDDED_SEEDS.get(filename, []), ensure_ascii=False))


def seed_database(db_path: Path | str = DB_PATH, force: bool = False) -> None:
    init_needed = False
    with connect(db_path) as conn:
        conn.executescript(SCHEMA_SQL)
        row = conn.execute("SELECT value FROM meta WHERE key='seed_version'").fetchone()
        if row is None or force:
            init_needed = True
    if not init_needed:
        return

    with connect(db_path) as conn:
        if force:
            # Delete child tables before parents.
            for table in [
                "visits", "sales", "cxc", "inventory", "brand_performance", "advisor_performance",
                "monthly_summary", "clients", "advisors", "supervisors", "products", "channels", "data_quality",
                "import_log", "settings",
            ]:
                conn.execute(f"DELETE FROM {table}")
        for table, filename in SEED_FILES:
            upsert_records(table, _load_seed(filename), conn=conn)

        source_registry = EMBEDDED_SOURCE_REGISTRY
        if source_registry:
            conn.executemany(
                """
                INSERT INTO import_log(
                    filename, file_hash, detected_type, user_name, rows_received,
                    rows_imported, rows_rejected, status, notes
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(file_hash) DO UPDATE SET
                    filename=excluded.filename,
                    detected_type=excluded.detected_type,
                    user_name=excluded.user_name,
                    rows_received=excluded.rows_received,
                    rows_imported=excluded.rows_imported,
                    rows_rejected=excluded.rows_rejected,
                    status=excluded.status,
                    notes=excluded.notes
                """,
                [
                    (
                        row.get("filename", "Fuente inicial"),
                        row["file_hash"],
                        row.get("detected_type", "Fuente inicial"),
                        row.get("user_name", "Construcción inicial"),
                        int(row.get("rows_received", 0)),
                        int(row.get("rows_imported", 0)),
                        int(row.get("rows_rejected", 0)),
                        row.get("status", "INTEGRADO_EN_PILOTO"),
                        row.get("notes", "Fuente original integrada en los datos semilla."),
                    )
                    for row in source_registry
                ],
            )
        conn.execute(
            "INSERT INTO meta(key, value, updated_at) VALUES('seed_version', ?, CURRENT_TIMESTAMP) "
            "ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=CURRENT_TIMESTAMP",
            ("1.0.0",),
        )
        conn.commit()


def query_df(sql: str, params: Sequence[Any] | Mapping[str, Any] | None = None, db_path: Path | str = DB_PATH) -> pd.DataFrame:
    with connect(db_path) as conn:
        return pd.read_sql_query(sql, conn, params=params or ())


def execute(sql: str, params: Sequence[Any] | Mapping[str, Any] | None = None, db_path: Path | str = DB_PATH) -> int:
    with connect(db_path) as conn:
        cur = conn.execute(sql, params or ())
        conn.commit()
        return cur.rowcount


def upsert_records(
    table: str,
    records: Iterable[Mapping[str, Any]],
    *,
    conn: sqlite3.Connection | None = None,
    db_path: Path | str = DB_PATH,
) -> int:
    if table not in IMPORT_TABLES or table not in TABLE_COLUMNS:
        raise ValueError(f"Tabla de importación no permitida: {table}")
    rows = list(records)
    if not rows:
        return 0
    columns = TABLE_COLUMNS[table]
    placeholders = ", ".join(["?"] * len(columns))
    quoted_cols = ", ".join(columns)
    conflict_cols = CONFLICT_COLUMNS.get(table)
    if conflict_cols:
        updates = [c for c in columns if c not in conflict_cols]
        update_sql = ", ".join([f"{c}=excluded.{c}" for c in updates])
        sql = (
            f"INSERT INTO {table} ({quoted_cols}) VALUES ({placeholders}) "
            f"ON CONFLICT ({', '.join(conflict_cols)}) DO UPDATE SET {update_sql}, updated_at=CURRENT_TIMESTAMP"
        )
    else:
        sql = f"INSERT OR IGNORE INTO {table} ({quoted_cols}) VALUES ({placeholders})"

    values = []
    for row in rows:
        values.append(tuple(clean_cell(row.get(col)) for col in columns))

    owns_connection = conn is None
    connection = conn or connect(db_path)
    try:
        connection.executemany(sql, values)
        if owns_connection:
            connection.commit()
    finally:
        if owns_connection:
            connection.close()
    return len(rows)


def insert_visit(record: Mapping[str, Any], db_path: Path | str = DB_PATH) -> int:
    columns = TABLE_COLUMNS["visits"]
    values = tuple(clean_cell(record.get(c)) for c in columns)
    placeholders = ", ".join(["?"] * len(columns))
    with connect(db_path) as conn:
        cur = conn.execute(
            f"INSERT INTO visits ({', '.join(columns)}) VALUES ({placeholders})",
            values,
        )
        conn.commit()
        return int(cur.lastrowid)


def import_exists(file_hash: str, db_path: Path | str = DB_PATH) -> bool:
    with connect(db_path) as conn:
        return conn.execute("SELECT 1 FROM import_log WHERE file_hash=?", (file_hash,)).fetchone() is not None


def log_import(
    *,
    filename: str,
    file_hash: str,
    detected_type: str,
    rows_received: int,
    rows_imported: int,
    rows_rejected: int,
    status: str,
    notes: str = "",
    user_name: str = "Gerencia",
    db_path: Path | str = DB_PATH,
) -> None:
    with connect(db_path) as conn:
        conn.execute(
            """
            INSERT INTO import_log(
                filename, file_hash, detected_type, user_name, rows_received,
                rows_imported, rows_rejected, status, notes
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(file_hash) DO UPDATE SET
                detected_type=excluded.detected_type,
                imported_at=CURRENT_TIMESTAMP,
                user_name=excluded.user_name,
                rows_received=excluded.rows_received,
                rows_imported=excluded.rows_imported,
                rows_rejected=excluded.rows_rejected,
                status=excluded.status,
                notes=excluded.notes
            """,
            (
                filename, file_hash, detected_type, user_name, rows_received,
                rows_imported, rows_rejected, status, notes,
            ),
        )
        conn.commit()


def get_settings(db_path: Path | str = DB_PATH) -> dict[str, str]:
    df = query_df("SELECT key, value FROM settings", db_path=db_path)
    return dict(zip(df["key"], df["value"])) if not df.empty else {}


def set_setting(key: str, value: Any, description: str = "", db_path: Path | str = DB_PATH) -> None:
    upsert_records(
        "settings",
        [{"key": key, "value": str(value), "description": description}],
        db_path=db_path,
    )


def backup_database(db_path: Path | str = DB_PATH) -> bytes:
    path = Path(db_path)
    if not path.exists():
        init_database(path)
    # Force a checkpoint so the main file contains committed WAL data.
    with connect(path) as conn:
        conn.execute("PRAGMA wal_checkpoint(FULL)")
    return path.read_bytes()


def backup_to_file(destination: Path | str, db_path: Path | str = DB_PATH) -> Path:
    source = Path(db_path)
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    with connect(source) as src, sqlite3.connect(destination) as dst:
        src.backup(dst)
    return destination


def reset_demo_database(db_path: Path | str = DB_PATH) -> None:
    path = Path(db_path)
    if path.exists():
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_to_file(path.with_name(f"nexus_comercial_backup_{timestamp}.db"), db_path=path)
    seed_database(db_path=path, force=True)


# Namespace compatible con la versión modular
database = types.SimpleNamespace(
    connect=connect, init_database=init_database, seed_database=seed_database,
    query_df=query_df, execute=execute, upsert_records=upsert_records,
    insert_visit=insert_visit, import_exists=import_exists, log_import=log_import,
    get_settings=get_settings, set_setting=set_setting, backup_database=backup_database,
    backup_to_file=backup_to_file, reset_demo_database=reset_demo_database,
)


