def available_periods(db_path: Path | str = DB_PATH) -> list[str]:
    df = query_df(
        """
        SELECT period FROM monthly_summary
        UNION SELECT period FROM advisor_performance
        UNION SELECT substr(sale_date, 1, 7) AS period FROM sales
        WHERE sale_date IS NOT NULL AND length(sale_date) >= 7
        ORDER BY period DESC
        """,
        db_path=db_path,
    )
    return [str(v) for v in df["period"].dropna().tolist()] if not df.empty else []


def supervisors(db_path: Path | str = DB_PATH, active_only: bool = True) -> pd.DataFrame:
    sql = "SELECT supervisor_code, name, manager_name, region, active FROM supervisors"
    if active_only:
        sql += " WHERE active=1"
    sql += " ORDER BY name"
    return query_df(sql, db_path=db_path)


def advisor_catalog(db_path: Path | str = DB_PATH, supervisor_code: str | None = None, active_only: bool = True) -> pd.DataFrame:
    conditions = []
    params: list[Any] = []
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("a.supervisor_code=?")
        params.append(supervisor_code)
    if active_only:
        conditions.append("a.active=1")
    where = f"WHERE {' AND '.join(conditions)}" if conditions else ""
    return query_df(
        f"""
        SELECT a.advisor_code, a.name, a.supervisor_code, s.name AS supervisor,
               a.state, a.zone, a.active
        FROM advisors a
        JOIN supervisors s ON s.supervisor_code=a.supervisor_code
        {where}
        ORDER BY a.name
        """,
        params,
        db_path=db_path,
    )


def monthly_summary(
    period: str,
    supervisor_code: str | None = None,
    official_only: bool = True,
    db_path: Path | str = DB_PATH,
) -> pd.DataFrame:
    conditions = ["m.period=?"]
    params: list[Any] = [period]
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("m.supervisor_code=?")
        params.append(supervisor_code)
    if official_only:
        conditions.append("m.is_official=1")
    return query_df(
        f"""
        SELECT m.period, m.supervisor_code, s.name AS supervisor,
               m.portfolio, m.activated, m.quota, m.sales,
               m.source, m.is_official
        FROM monthly_summary m
        JOIN supervisors s ON s.supervisor_code=m.supervisor_code
        WHERE {' AND '.join(conditions)}
        ORDER BY m.is_official DESC, s.name, m.source
        """,
        params,
        db_path=db_path,
    )


def monthly_history(supervisor_code: str | None = None, db_path: Path | str = DB_PATH) -> pd.DataFrame:
    conditions = ["m.is_official=1"]
    params: list[Any] = []
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("m.supervisor_code=?")
        params.append(supervisor_code)
    df = query_df(
        f"""
        SELECT m.period,
               SUM(m.portfolio) AS portfolio,
               SUM(m.activated) AS activated,
               SUM(m.quota) AS quota,
               SUM(m.sales) AS sales
        FROM monthly_summary m
        WHERE {' AND '.join(conditions)}
        GROUP BY m.period
        ORDER BY m.period
        """,
        params,
        db_path=db_path,
    )
    if not df.empty:
        df["activation_pct"] = df["activated"].div(df["portfolio"].replace(0, pd.NA)).fillna(0.0)
        df["sales_pct"] = df["sales"].div(df["quota"].replace(0, pd.NA)).fillna(0.0)
    return df


def advisor_performance(
    period: str,
    supervisor_code: str | None = None,
    advisor_codes: Sequence[str] | None = None,
    states: Sequence[str] | None = None,
    zones: Sequence[str] | None = None,
    db_path: Path | str = DB_PATH,
) -> pd.DataFrame:
    conditions = ["p.period=?", "a.advisor_code <> 'SIN-ASIGNAR'"]
    params: list[Any] = [period]
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("a.supervisor_code=?")
        params.append(supervisor_code)
    if advisor_codes:
        placeholders = ",".join(["?"] * len(advisor_codes))
        conditions.append(f"a.advisor_code IN ({placeholders})")
        params.extend(advisor_codes)
    if states:
        placeholders = ",".join(["?"] * len(states))
        conditions.append(f"a.state IN ({placeholders})")
        params.extend(states)
    if zones:
        placeholders = ",".join(["?"] * len(zones))
        conditions.append(f"a.zone IN ({placeholders})")
        params.extend(zones)

    df = query_df(
        f"""
        SELECT p.period, p.advisor_code, a.name AS advisor,
               a.supervisor_code, s.name AS supervisor, a.state, a.zone,
               p.portfolio, p.activated, p.new_goal, p.new_achieved,
               p.sales_goal, p.sales_actual, p.brand_goal_count,
               p.brand_achieved_count, p.observations, p.source
        FROM advisor_performance p
        JOIN advisors a ON a.advisor_code=p.advisor_code
        JOIN supervisors s ON s.supervisor_code=a.supervisor_code
        WHERE {' AND '.join(conditions)}
        ORDER BY p.sales_actual DESC, a.name
        """,
        params,
        db_path=db_path,
    )
    if df.empty:
        return df

    df["activation_pct"] = df["activated"].div(df["portfolio"].replace(0, pd.NA)).fillna(0.0)
    df["sales_pct"] = df["sales_actual"].div(df["sales_goal"].replace(0, pd.NA)).fillna(0.0)
    df["new_pct"] = df["new_achieved"].div(df["new_goal"].replace(0, pd.NA)).fillna(0.0)
    df["brand_pct"] = df["brand_achieved_count"].div(df["brand_goal_count"].replace(0, pd.NA)).fillna(0.0)
    df["sales_gap"] = df["sales_actual"] - df["sales_goal"]

    raw_settings = get_settings(db_path)
    settings = DEFAULT_SETTINGS.copy()
    for key in ["activation_green", "activation_yellow", "sales_green", "sales_yellow"]:
        try:
            settings[key] = float(raw_settings.get(key, settings[key]))
        except (TypeError, ValueError):
            pass
    statuses = df.apply(
        lambda r: classify_performance(
            float(r["activation_pct"]),
            float(r["sales_pct"]),
            activation_green=float(settings["activation_green"]),
            activation_yellow=float(settings["activation_yellow"]),
            sales_green=float(settings["sales_green"]),
            sales_yellow=float(settings["sales_yellow"]),
        ),
        axis=1,
    )
    df["status"] = [s[0] for s in statuses]
    df["status_color"] = [s[1] for s in statuses]
    return df


def brand_performance(
    period: str,
    supervisor_code: str | None = None,
    advisor_codes: Sequence[str] | None = None,
    dimension: str | None = None,
    db_path: Path | str = DB_PATH,
) -> pd.DataFrame:
    conditions = ["b.period=?"]
    params: list[Any] = [period]
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("a.supervisor_code=?")
        params.append(supervisor_code)
    if advisor_codes:
        placeholders = ",".join(["?"] * len(advisor_codes))
        conditions.append(f"b.advisor_code IN ({placeholders})")
        params.extend(advisor_codes)
    if dimension and dimension != "TODAS":
        conditions.append("b.dimension=?")
        params.append(dimension)
    df = query_df(
        f"""
        SELECT b.period, b.advisor_code, a.name AS advisor,
               a.supervisor_code, s.name AS supervisor, a.state, a.zone,
               b.dimension, b.brand, b.goal, b.actual, b.units, b.source
        FROM brand_performance b
        JOIN advisors a ON a.advisor_code=b.advisor_code
        JOIN supervisors s ON s.supervisor_code=a.supervisor_code
        WHERE {' AND '.join(conditions)}
        ORDER BY COALESCE(b.actual, 0) DESC, b.brand
        """,
        params,
        db_path=db_path,
    )
    if not df.empty:
        df["goal"] = pd.to_numeric(df["goal"], errors="coerce")
        df["actual"] = pd.to_numeric(df["actual"], errors="coerce")
        df["units"] = pd.to_numeric(df["units"], errors="coerce")
        df["achievement_pct"] = df["actual"].div(df["goal"].replace(0, pd.NA))
        df["gap"] = df["actual"].fillna(0) - df["goal"].fillna(0)
    return df


def clients(
    supervisor_code: str | None = None,
    advisor_codes: Sequence[str] | None = None,
    statuses: Sequence[str] | None = None,
    channels: Sequence[str] | None = None,
    zones: Sequence[str] | None = None,
    search: str | None = None,
    db_path: Path | str = DB_PATH,
) -> pd.DataFrame:
    conditions = ["1=1"]
    params: list[Any] = []
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("a.supervisor_code=?")
        params.append(supervisor_code)
    if advisor_codes:
        placeholders = ",".join(["?"] * len(advisor_codes))
        conditions.append(f"c.advisor_code IN ({placeholders})")
        params.extend(advisor_codes)
    if statuses:
        placeholders = ",".join(["?"] * len(statuses))
        conditions.append(f"c.status IN ({placeholders})")
        params.extend(statuses)
    if channels:
        placeholders = ",".join(["?"] * len(channels))
        conditions.append(f"c.channel IN ({placeholders})")
        params.extend(channels)
    if zones:
        placeholders = ",".join(["?"] * len(zones))
        conditions.append(f"c.zone IN ({placeholders})")
        params.extend(zones)
    if search:
        conditions.append("(UPPER(c.name) LIKE UPPER(?) OR UPPER(c.rif) LIKE UPPER(?) OR UPPER(c.client_code) LIKE UPPER(?))")
        token = f"%{search}%"
        params.extend([token, token, token])

    return query_df(
        f"""
        SELECT c.client_code, c.rif, c.name AS client, c.channel,
               c.state, c.city, c.zone, c.advisor_code,
               COALESCE(a.name, 'Sin asignar') AS advisor,
               COALESCE(s.name, 'Sin asignar') AS supervisor,
               c.status, c.is_new, c.route_week, c.route_day,
               c.phone, c.email, c.address, c.source, c.notes,
               c.latitude, c.longitude
        FROM clients c
        LEFT JOIN advisors a ON a.advisor_code=c.advisor_code
        LEFT JOIN supervisors s ON s.supervisor_code=a.supervisor_code
        WHERE {' AND '.join(conditions)}
        ORDER BY c.name
        """,
        params,
        db_path=db_path,
    )


def visits(
    start_date: str | None = None,
    end_date: str | None = None,
    supervisor_code: str | None = None,
    advisor_codes: Sequence[str] | None = None,
    db_path: Path | str = DB_PATH,
) -> pd.DataFrame:
    conditions = ["1=1"]
    params: list[Any] = []
    if start_date:
        conditions.append("v.visit_date>=?")
        params.append(start_date)
    if end_date:
        conditions.append("v.visit_date<=?")
        params.append(end_date)
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("a.supervisor_code=?")
        params.append(supervisor_code)
    if advisor_codes:
        placeholders = ",".join(["?"] * len(advisor_codes))
        conditions.append(f"v.advisor_code IN ({placeholders})")
        params.extend(advisor_codes)
    return query_df(
        f"""
        SELECT v.visit_id, v.visit_date, v.advisor_code, a.name AS advisor,
               s.name AS supervisor, v.client_code, c.name AS client,
               c.channel, c.zone, v.result, v.reason, v.amount_reported,
               v.amount_collected, v.next_action, v.next_visit_date,
               v.notes, v.source, v.created_at
        FROM visits v
        JOIN advisors a ON a.advisor_code=v.advisor_code
        JOIN supervisors s ON s.supervisor_code=a.supervisor_code
        JOIN clients c ON c.client_code=v.client_code
        WHERE {' AND '.join(conditions)}
        ORDER BY v.visit_date DESC, v.created_at DESC
        """,
        params,
        db_path=db_path,
    )


def sales(
    start_date: str | None = None,
    end_date: str | None = None,
    supervisor_code: str | None = None,
    advisor_codes: Sequence[str] | None = None,
    client_codes: Sequence[str] | None = None,
    db_path: Path | str = DB_PATH,
) -> pd.DataFrame:
    conditions = ["1=1"]
    params: list[Any] = []
    if start_date:
        conditions.append("sa.sale_date>=?")
        params.append(start_date)
    if end_date:
        conditions.append("sa.sale_date<=?")
        params.append(end_date)
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("a.supervisor_code=?")
        params.append(supervisor_code)
    if advisor_codes:
        placeholders = ",".join(["?"] * len(advisor_codes))
        conditions.append(f"sa.advisor_code IN ({placeholders})")
        params.extend(advisor_codes)
    if client_codes:
        placeholders = ",".join(["?"] * len(client_codes))
        conditions.append(f"sa.client_code IN ({placeholders})")
        params.extend(client_codes)
    return query_df(
        f"""
        SELECT sa.sale_id, sa.sale_date, sa.document_no, sa.line_no,
               sa.advisor_code, COALESCE(a.name, 'Sin asignar') AS advisor,
               sa.client_code, COALESCE(c.name, 'Sin identificar') AS client,
               sa.product_code, sa.product_description, sa.brand, sa.category,
               sa.units, sa.net_amount, sa.cost, sa.currency, sa.source
        FROM sales sa
        LEFT JOIN advisors a ON a.advisor_code=sa.advisor_code
        LEFT JOIN clients c ON c.client_code=sa.client_code
        WHERE {' AND '.join(conditions)}
        ORDER BY sa.sale_date DESC, sa.document_no, sa.line_no
        """,
        params,
        db_path=db_path,
    )


def daily_sales(period: str, supervisor_code: str | None = None,
    advisor_codes: Sequence[str] | None = None, db_path: Path | str = DB_PATH) -> pd.DataFrame:
    year, month = map(int, period.split("-"))
    start, end = f"{period}-01", f"{period}-{monthrange(year, month)[1]:02d}"
    detail = sales(start_date=start, end_date=end, supervisor_code=supervisor_code,
                   advisor_codes=advisor_codes, db_path=db_path)
    columns = ["date", "sales", "units", "transactions", "clients", "currency"]
    if detail.empty:
        return pd.DataFrame(columns=columns)
    usd = detail["currency"].fillna("").astype(str).str.strip().str.upper().eq("USD")
    omitted = detail.loc[~usd, "currency"].fillna("Sin moneda").astype(str).value_counts().to_dict()
    frame = detail.loc[usd].groupby("sale_date", as_index=False).agg(sales=("net_amount", "sum"),
        units=("units", "sum"), transactions=("document_no", "nunique"), clients=("client_code", "nunique"))
    frame = frame.rename(columns={"sale_date": "date"})
    frame["currency"] = "USD"
    frame.attrs["excluded_currency_rows"] = omitted
    return frame


def client_brand_history(client_code: str, db_path: Path | str = DB_PATH) -> pd.DataFrame:
    return query_df(
        """
        SELECT brand, category, SUM(units) AS units, SUM(net_amount) AS sales,
               MAX(sale_date) AS last_purchase
        FROM sales
        WHERE client_code=?
        GROUP BY brand, category
        ORDER BY sales DESC
        """,
        (client_code,),
        db_path=db_path,
    )


def cxc_summary(
    period: str | None = None,
    supervisor_code: str | None = None,
    advisor_codes: Sequence[str] | None = None,
    db_path: Path | str = DB_PATH,
) -> pd.DataFrame:
    conditions = ["1=1"]
    params: list[Any] = []
    if period:
        conditions.append("substr(x.cutoff_date,1,7)=?")
        params.append(period)
    if supervisor_code and supervisor_code != "TODOS":
        conditions.append("a.supervisor_code=?")
        params.append(supervisor_code)
    if advisor_codes:
        placeholders = ",".join(["?"] * len(advisor_codes))
        conditions.append(f"x.advisor_code IN ({placeholders})")
        params.extend(advisor_codes)
    cutoff_condition = "AND substr(y.cutoff_date,1,7)=substr(x.cutoff_date,1,7)" if period else ""
    conditions.append(f"x.cutoff_date=(SELECT MAX(y.cutoff_date) FROM cxc y WHERE COALESCE(y.advisor_code,'')=COALESCE(x.advisor_code,'') AND COALESCE(y.currency,'')=COALESCE(x.currency,'') {cutoff_condition})")
    return query_df(
        f"""
        SELECT x.cutoff_date, x.client_code, COALESCE(c.name, 'Sin identificar') AS client,
               x.document_no, x.issue_date, x.due_date, x.balance, x.currency,
               x.advisor_code, COALESCE(a.name, 'Sin asignar') AS advisor,
               CASE
                   WHEN x.due_date IS NULL THEN 'SIN VENCIMIENTO'
                   WHEN julianday(x.cutoff_date)-julianday(x.due_date) <= 0 THEN 'AL DÍA'
                   WHEN julianday(x.cutoff_date)-julianday(x.due_date) <= 30 THEN '1-30 DÍAS'
                   WHEN julianday(x.cutoff_date)-julianday(x.due_date) <= 60 THEN '31-60 DÍAS'
                   WHEN julianday(x.cutoff_date)-julianday(x.due_date) <= 90 THEN '61-90 DÍAS'
                   ELSE 'MÁS DE 90 DÍAS'
               END AS aging
        FROM cxc x
        LEFT JOIN clients c ON c.client_code=x.client_code
        LEFT JOIN advisors a ON a.advisor_code=x.advisor_code
        WHERE {' AND '.join(conditions)}
        ORDER BY x.balance DESC
        """,
        params,
        db_path=db_path,
    )


def inventory_summary(period: str | None = None, db_path: Path | str = DB_PATH) -> pd.DataFrame:
    conditions = ["1=1"]
    params: list[Any] = []
    if period:
        conditions.append("substr(i.cutoff_date,1,7)=?")
        params.append(period)
    cutoff_condition = "AND substr(j.cutoff_date,1,7)=substr(i.cutoff_date,1,7)" if period else ""
    conditions.append(f"i.cutoff_date=(SELECT MAX(j.cutoff_date) FROM inventory j WHERE COALESCE(j.branch,'')=COALESCE(i.branch,'') AND COALESCE(j.warehouse,'')=COALESCE(i.warehouse,'') {cutoff_condition})")
    return query_df(
        f"""
        SELECT cutoff_date, branch, warehouse, product_code, product_description,
               brand, stock, committed, available, cost
        FROM inventory i
        WHERE {' AND '.join(conditions)}
        ORDER BY available ASC, brand, product_description
        """,
        params,
        db_path=db_path,
    )


def data_quality(period: str | None = None, status: str | None = None, db_path: Path | str = DB_PATH) -> pd.DataFrame:
    conditions = ["1=1"]
    params: list[Any] = []
    if period:
        conditions.append("period=?")
        params.append(period)
    if status:
        conditions.append("status=?")
        params.append(status)
    return query_df(
        f"""
        SELECT issue_id, period, scope, severity, title, detail,
               expected, observed, source_a, source_b, status, created_at
        FROM data_quality
        WHERE {' AND '.join(conditions)}
        ORDER BY CASE severity WHEN 'ALTA' THEN 1 WHEN 'MEDIA' THEN 2 ELSE 3 END,
                 created_at DESC
        """,
        params,
        db_path=db_path,
    )


def import_log(limit: int = 50, db_path: Path | str = DB_PATH) -> pd.DataFrame:
    return query_df(
        """
        SELECT import_id, filename, detected_type, imported_at, user_name,
               rows_received, rows_imported, rows_rejected, status, notes
        FROM import_log
        ORDER BY imported_at DESC
        LIMIT ?
        """,
        (limit,),
        db_path=db_path,
    )


