def visits_results(df: pd.DataFrame) -> go.Figure:
    if df.empty:
        return empty_figure("Aún no se han registrado visitas.", "Resultado de visitas")
    counts = df["result"].fillna("Sin resultado").value_counts()
    fig = go.Figure(go.Bar(x=counts.index, y=counts.values, marker_color=PALETTE[: len(counts)]))
    fig.update_xaxes(tickangle=-25)
    fig.update_yaxes(title="Visitas")
    return _base_layout(fig, height=400, title="Resultado de gestiones de campo")


def daily_sales_line(df: pd.DataFrame, quota: float = 0) -> go.Figure:
    if df.empty:
        return empty_figure("Carga el reporte de ventas diarias para ver la curva del mes.", "Ritmo diario de ventas")
    data = df.copy()
    data["date"] = pd.to_datetime(data["date"])
    data["cumulative"] = data["sales"].cumsum()
    fig = go.Figure()
    fig.add_bar(x=data["date"], y=data["sales"], name="Venta diaria USD", marker_color="rgba(56,189,248,0.55)")
    fig.add_trace(go.Scatter(x=data["date"], y=data["cumulative"], name="Acumulado", mode="lines+markers", line=dict(color=COLORS["amber"], width=3), yaxis="y2"))
    if quota > 0:
        fig.add_hline(y=quota, yref="y2", line_dash="dash", line_color=COLORS["green"], annotation_text="Cuota")
    fig.update_layout(
        yaxis=dict(title="Venta diaria USD", tickprefix="$"),
        yaxis2=dict(title="Acumulado", overlaying="y", side="right", tickprefix="$", showgrid=False),
    )
    return _base_layout(fig, height=430, title="Ventas diarias USD y acumulado USD")


