def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _canonical_brand(value: Any) -> str:
    text = normalize_text(value)
    return BRAND_ALIASES.get(text, text)


def _supervisor_code(value: Any) -> str:
    """Return a stable hierarchy key for names found in legacy workbooks."""
    text = normalize_text(value)
    # The pilot sources alternate between Johana/Johanna, while the seeded
    # hierarchy uses SUP-JOHANA. Keep one key so re-importing a legacy file
    # cannot create a duplicate supervisor.
    if ("JOHANA" in text or "JOHANNA" in text) and "MARCANO" in text:
        return "SUP-JOHANA"
    return slug_code(str(value or "Supervisor"), "SUP")


def _excel(data: bytes) -> pd.ExcelFile:
    return pd.ExcelFile(io.BytesIO(data), engine="openpyxl")


def detect_import_type(filename: str, data: bytes) -> str:
    name = normalize_text(filename)
    if "REPORTE_ACTUALIZADO" in name or "REPORTE ACTUALIZADO" in name:
        return "Reporte gerencial histórico"
    if "SEGUIMIENTO DE METAS" in name:
        return "Seguimiento de metas / asesores"
    if "TIPOS DE CLIENTES" in name:
        return "Canales comerciales"
    if "CLIENTES SEGUROS" in name:
        return "Ruta / maestro de clientes"
    if filename.lower().endswith(".csv"):
        # Resolve CSV type by headers below.
        try:
            sample = pd.read_csv(io.BytesIO(data), nrows=5)
            cols = {canonical_column(c) for c in sample.columns}
            if {"fecha", "documento", "codigo_asesor"}.issubset(cols):
                return "Ventas diarias"
            if {"fecha", "codigo_asesor", "codigo_cliente", "resultado"}.issubset(cols):
                return "Visitas"
            if "fecha_corte" in cols and "saldo" in cols:
                return "Cuentas por cobrar"
            if "fecha_corte" in cols and ("existencia" in cols or "disponible" in cols):
                return "Inventario"
        except Exception:
            pass
        return "Plantilla NEXUS"
    try:
        xls = _excel(data)
        names = {normalize_text(s) for s in xls.sheet_names}
        if "RENDIMIENTO" in names:
            return "Reporte gerencial histórico"
        if "TOTAL GESTION" in names and "CUOTAS GENERAL" in names:
            return "Seguimiento de metas / asesores"
        if "VENTAS_DIARIAS" in names or "VENTAS DIARIAS" in names:
            return "Plantilla NEXUS"
        if "RUTA" in names and "ANALISIS" in names:
            return "Ruta / maestro de clientes"
        if "CANALES" in names:
            return "Canales comerciales"
    except Exception:
        pass
    return "Plantilla NEXUS"


def parse_file(data: bytes, filename: str, selected_type: str = "Automático") -> ImportBundle:
    detected = detect_import_type(filename, data) if selected_type == "Automático" else selected_type
    bundle = ImportBundle(filename=filename, file_hash=sha256_bytes(data), detected_type=detected)
    try:
        parser: dict[str, Callable[[bytes, ImportBundle], None]] = {
            "Reporte gerencial histórico": _parse_historical_report,
            "Seguimiento de metas / asesores": _parse_goals_followup,
            "Canales comerciales": _parse_channels,
            "Ruta / maestro de clientes": _parse_route_clients,
            "Plantilla NEXUS": _parse_nexus_template,
            "Ventas diarias": lambda d, b: _parse_generic_single(d, b, "sales"),
            "Visitas": lambda d, b: _parse_generic_single(d, b, "visits"),
            "Cuentas por cobrar": lambda d, b: _parse_generic_single(d, b, "cxc"),
            "Inventario": lambda d, b: _parse_generic_single(d, b, "inventory"),
        }
        parser[detected](data, bundle)
    except Exception as exc:  # noqa: BLE001 - displayed to the operator with context.
        bundle.errors.append(f"No se pudo procesar el archivo: {exc}")
    if not bundle.frames and not bundle.errors:
        bundle.errors.append("El archivo fue reconocido, pero no se encontraron filas importables.")
    return bundle


def _parse_historical_report(data: bytes, bundle: ImportBundle) -> None:
    xls = _excel(data)
    sheet = next((s for s in xls.sheet_names if normalize_text(s) == "RENDIMIENTO"), xls.sheet_names[0])
    raw = pd.read_excel(io.BytesIO(data), sheet_name=sheet, header=None, engine="openpyxl")
    rows: list[dict[str, Any]] = []
    for _, row in raw.iterrows():
        month_name = normalize_text(row.iloc[0] if len(row) else "")
        if month_name not in MONTH_NAME_TO_NUMBER:
            continue
        year = datetime.now().year
        # Uploaded pilot files correspond to 2026. If the workbook title contains another year,
        # the user can correct it from the quick-edit module after import.
        period = f"{year}-{MONTH_NAME_TO_NUMBER[month_name]:02d}"
        rows.append(
            {
                "period": period,
                "supervisor_code": "SUP-JOHANA",
                "portfolio": safe_int(row.iloc[1]),
                "activated": safe_int(row.iloc[2]),
                "quota": safe_float(row.iloc[4]),
                "sales": safe_float(row.iloc[5]),
                "source": Path(bundle.filename).stem[:120],
                "is_official": 1,
            }
        )
    if rows:
        bundle.frames["monthly_summary"] = pd.DataFrame(rows)
    else:
        bundle.warnings.append("No se encontraron meses en la hoja Rendimiento.")


def _parse_goals_followup(data: bytes, bundle: ImportBundle) -> None:
    xls = _excel(data)
    normalized_sheets = {normalize_text(s): s for s in xls.sheet_names}
    if "TOTAL GESTION" not in normalized_sheets:
        raise ValueError("Falta la hoja TOTAL GESTION.")

    total_raw = pd.read_excel(io.BytesIO(data), sheet_name=normalized_sheets["TOTAL GESTION"], header=None, engine="openpyxl")
    quota_map: dict[str, dict[str, Any]] = {}
    supervisor_records: dict[str, dict[str, Any]] = {}
    advisor_records: dict[str, dict[str, Any]] = {}

    if "CUOTAS GENERAL" in normalized_sheets:
        quota_raw = pd.read_excel(io.BytesIO(data), sheet_name=normalized_sheets["CUOTAS GENERAL"], header=None, engine="openpyxl")
        for _, row in quota_raw.iterrows():
            code_num = parse_number(row.iloc[1] if len(row) > 1 else None)
            if code_num is None:
                continue
            code = str(int(code_num))
            supervisor_name = str(row.iloc[4] or "Johana Marcano").strip()
            supervisor_code = _supervisor_code(supervisor_name)
            supervisor_records[supervisor_code] = {
                "supervisor_code": supervisor_code,
                "name": supervisor_name.title(),
                "manager_name": "Gerencia Nacional",
                "region": "Por definir",
                "active": 1,
            }
            quota_map[code] = {
                "state": str(row.iloc[2] or "Por definir").strip().title(),
                "zone": str(row.iloc[3] or "Por definir").strip().title(),
                "supervisor_code": supervisor_code,
                "name": str(row.iloc[5] or f"Asesor {code}").strip().title(),
            }

    performance: list[dict[str, Any]] = []
    period = None
    for _, row in total_raw.iterrows():
        code_num = parse_number(row.iloc[0] if len(row) > 0 else None)
        if code_num is None:
            continue
        code = str(int(code_num))
        # Rows with a numeric advisor code have the same fixed layout in the pilot file.
        if len(row) < 14:
            continue
        info = quota_map.get(code, {})
        supervisor_code = info.get("supervisor_code", "SUP-JOHANA")
        if supervisor_code not in supervisor_records:
            supervisor_records[supervisor_code] = {
                "supervisor_code": supervisor_code,
                "name": "Johana Marcano" if supervisor_code == "SUP-JOHANA" else supervisor_code,
                "manager_name": "Gerencia Nacional",
                "region": "Por definir",
                "active": 1,
            }
        advisor_records[code] = {
            "advisor_code": code,
            "name": info.get("name") or str(row.iloc[1] or f"Asesor {code}").strip().title(),
            "supervisor_code": supervisor_code,
            "state": info.get("state", "Por definir"),
            "zone": info.get("zone", "Por definir"),
            "active": 1,
        }
        period = period or "2026-08"
        performance.append(
            {
                "period": period,
                "advisor_code": code,
                "portfolio": safe_int(row.iloc[2]),
                "activated": safe_int(row.iloc[3]),
                "new_goal": safe_int(row.iloc[5]),
                "new_achieved": safe_int(row.iloc[6]),
                "sales_goal": safe_float(row.iloc[8]),
                "sales_actual": safe_float(row.iloc[9]),
                "brand_goal_count": safe_int(row.iloc[11]),
                "brand_achieved_count": safe_int(row.iloc[12]),
                "observations": str(row.iloc[14] or "").strip() if len(row) > 14 and pd.notna(row.iloc[14]) else "",
                "source": Path(bundle.filename).stem[:120],
            }
        )

    if not supervisor_records:
        supervisor_records["SUP-JOHANA"] = {
            "supervisor_code": "SUP-JOHANA",
            "name": "Johana Marcano",
            "manager_name": "Gerencia Nacional",
            "region": "Por definir",
            "active": 1,
        }
    bundle.frames["supervisors"] = pd.DataFrame(supervisor_records.values())
    bundle.frames["advisors"] = pd.DataFrame(advisor_records.values())
    bundle.frames["advisor_performance"] = pd.DataFrame(performance)

    brand_rows: list[dict[str, Any]] = []
    excluded = {"TOTAL GESTION", "CUOTAS GENERAL"}
    for normalized, sheet in normalized_sheets.items():
        if normalized in excluded:
            continue
        raw = pd.read_excel(io.BytesIO(data), sheet_name=sheet, header=None, engine="openpyxl")
        if raw.shape[1] < 3:
            continue
        code = None
        sheet_period = "2026-08"
        for _, row in raw.iterrows():
            key = normalize_text(row.iloc[0] if len(row) else "")
            if key == "RUTA":
                code_num = parse_number(row.iloc[1] if len(row) > 1 else None)
                if code_num is not None:
                    code = str(int(code_num))
            if key == "MES":
                month_name = normalize_text(row.iloc[1] if len(row) > 1 else "")
                if month_name in MONTH_NAME_TO_NUMBER:
                    sheet_period = f"2026-{MONTH_NAME_TO_NUMBER[month_name]:02d}"
        if code is None:
            continue
        start_index = None
        for idx, row in raw.iterrows():
            if normalize_text(row.iloc[0] if len(row) else "") == "MARCAS":
                start_index = idx + 1
                break
        if start_index is None:
            continue
        for idx in range(start_index, len(raw)):
            label = str(raw.iloc[idx, 0] or "").strip()
            if not label or normalize_text(label).startswith("TOTAL CUOTA"):
                if normalize_text(label).startswith("TOTAL CUOTA"):
                    break
                continue
            brand_rows.append(
                {
                    "period": sheet_period,
                    "advisor_code": code,
                    "dimension": "LINEA / MARCA",
                    "brand": _canonical_brand(label),
                    "goal": parse_number(raw.iloc[idx, 1]),
                    "actual": parse_number(raw.iloc[idx, 2]),
                    "units": None,
                    "source": f"{Path(bundle.filename).stem[:80]}:{sheet}",
                }
            )
    if brand_rows:
        bundle.frames["brand_performance"] = pd.DataFrame(brand_rows)
    if performance:
        perf_df = pd.DataFrame(performance)
        matrix_summary = pd.DataFrame(
            [
                {
                    "period": period or "2026-08",
                    "supervisor_code": "SUP-JOHANA",
                    "portfolio": int(perf_df["portfolio"].sum()),
                    "activated": int(perf_df["activated"].sum()),
                    "quota": float(perf_df["sales_goal"].sum()),
                    "sales": float(perf_df["sales_actual"].sum()),
                    "source": f"MATRIZ:{Path(bundle.filename).stem[:100]}",
                    "is_official": 0,
                }
            ]
        )
        bundle.frames["monthly_summary"] = matrix_summary


def _parse_channels(data: bytes, bundle: ImportBundle) -> None:
    xls = _excel(data)
    sheet = next((s for s in xls.sheet_names if normalize_text(s) == "CANALES"), xls.sheet_names[0])
    raw = pd.read_excel(io.BytesIO(data), sheet_name=sheet, header=None, engine="openpyxl")
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for _, row in raw.iterrows():
        values = [v for v in row.tolist() if pd.notna(v) and str(v).strip()]
        if not values:
            continue
        if len(values) >= 2 and normalize_text(values[0]) not in {"CANALES COMERCIALES", "CANALES"}:
            name = " ".join(str(values[0]).replace("\xa0", " ").split())
            code = str(values[1]).strip() if len(values) > 1 else ""
        elif len(values) == 1 and normalize_text(values[0]) not in {"CANALES COMERCIALES", "CANALES"}:
            name, code = " ".join(str(values[0]).replace("\xa0", " ").split()), ""
        else:
            continue
        key = normalize_text(name)
        if key in seen:
            continue
        seen.add(key)
        rows.append({"channel": name.title(), "short_code": code.upper(), "source": Path(bundle.filename).stem[:120]})
    bundle.frames["channels"] = pd.DataFrame(rows)


def _parse_route_clients(data: bytes, bundle: ImportBundle) -> None:
    xls = _excel(data)
    sheet = next((s for s in xls.sheet_names if normalize_text(s) == "RUTA"), xls.sheet_names[0])
    raw = pd.read_excel(io.BytesIO(data), sheet_name=sheet, header=None, engine="openpyxl")
    current_zone = "Por definir"
    current_day = ""
    current_week: int | None = None
    rows: list[dict[str, Any]] = []
    for idx, row in raw.iterrows():
        c = row.iloc[2] if len(row) > 2 else None
        e = row.iloc[4] if len(row) > 4 else None
        if normalize_text(c) == "SEMANA" and idx + 1 < len(raw):
            current_week = safe_int(raw.iloc[idx + 1, 2], 0) or None
        if normalize_text(e) in {"LUNES", "MARTES", "MIERCOLES", "JUEVES", "VIERNES", "SABADO", "DOMINGO"}:
            current_day = str(e).strip().title()
            continue
        number = parse_number(row.iloc[1] if len(row) > 1 else None)
        zone = row.iloc[2] if len(row) > 2 else None
        client = row.iloc[4] if len(row) > 4 else None
        channel = row.iloc[5] if len(row) > 5 else None
        if pd.notna(zone) and normalize_text(zone) not in {"", "SEMANA", "TOTAL CLIENTES", "#", "-"}:
            if parse_number(zone) is None:
                current_zone = str(zone).strip().title()
        if number is None or pd.isna(client) or str(client).strip() in {"", "-"}:
            continue
        rows.append(
            {
                "client_code": f"RUTA-{bundle.file_hash[:6].upper()}-{len(rows)+1:04d}",
                "rif": str(row.iloc[3]).strip() if len(row) > 3 and pd.notna(row.iloc[3]) else "",
                "name": str(client).strip().title(),
                "channel": str(channel).strip().title() if pd.notna(channel) else "Por clasificar",
                "state": "Por definir",
                "city": current_zone,
                "zone": current_zone,
                "advisor_code": "SIN-ASIGNAR",
                "status": "EN RUTA",
                "is_new": 0,
                "route_week": current_week,
                "route_day": current_day,
                "source": Path(bundle.filename).stem[:120],
                "notes": str(row.iloc[7]).strip() if len(row) > 7 and pd.notna(row.iloc[7]) else "",
                "phone": str(row.iloc[10]).strip() if len(row) > 10 and pd.notna(row.iloc[10]) else "",
                "email": str(row.iloc[11]).strip() if len(row) > 11 and pd.notna(row.iloc[11]) else "",
                "address": "",
                "latitude": None,
                "longitude": None,
            }
        )
    bundle.frames["clients"] = pd.DataFrame(rows)
    if "SIN-ASIGNAR" not in database.query_df("SELECT advisor_code FROM advisors WHERE advisor_code='SIN-ASIGNAR'")["advisor_code"].tolist():
        bundle.warnings.append("Los clientes de ruta se asignarán temporalmente al código SIN-ASIGNAR.")


def _read_sheet_table(data: bytes, sheet_name: str) -> pd.DataFrame:
    raw = pd.read_excel(io.BytesIO(data), sheet_name=sheet_name, header=None, engine="openpyxl")
    # Find the row with the highest number of non-empty canonical headers.
    best_idx = 0
    best_score = -1
    for idx in range(min(15, len(raw))):
        values = [canonical_column(v) for v in raw.iloc[idx].tolist() if pd.notna(v) and str(v).strip()]
        score = sum(bool(v) for v in values)
        if score > best_score:
            best_idx, best_score = idx, score
    df = pd.read_excel(io.BytesIO(data), sheet_name=sheet_name, header=best_idx, engine="openpyxl")
    df = df.dropna(how="all")
    df.columns = [canonical_column(c) for c in df.columns]
    df = df.loc[:, [c for c in df.columns if c and not c.startswith("unnamed")]]
    return df


def _parse_nexus_template(data: bytes, bundle: ImportBundle) -> None:
    if bundle.filename.lower().endswith(".csv"):
        df = pd.read_csv(io.BytesIO(data))
        df.columns = [canonical_column(c) for c in df.columns]
        table = _guess_generic_table(df)
        bundle.frames[table] = _standardize_generic(df, table, bundle)
        return

    xls = _excel(data)
    sheet_map = {normalize_text(s).replace(" ", "_"): s for s in xls.sheet_names}
    recognized = 0
    mapping = {
        "JERARQUIA": "supervisors",
        "SUPERVISORES": "supervisors",
        "ASESORES": "advisors",
        "CLIENTES": "clients",
        "METAS": "advisor_performance",
        "VENTAS_DIARIAS": "sales",
        "VENTAS": "sales",
        "VISITAS": "visits",
        "CXC": "cxc",
        "INVENTARIO": "inventory",
        "CANALES": "channels",
        "PRODUCTOS": "products",
    }
    for key, table in mapping.items():
        sheet = sheet_map.get(key)
        if not sheet:
            continue
        df = _read_sheet_table(data, sheet)
        if df.empty:
            continue
        bundle.frames[table] = _standardize_generic(df, table, bundle)
        recognized += 1
    if not recognized:
        # Try the first sheet as a generic table.
        df = _read_sheet_table(data, xls.sheet_names[0])
        table = _guess_generic_table(df)
        bundle.frames[table] = _standardize_generic(df, table, bundle)


def _parse_generic_single(data: bytes, bundle: ImportBundle, table: str) -> None:
    if bundle.filename.lower().endswith(".csv"):
        df = pd.read_csv(io.BytesIO(data))
    else:
        xls = _excel(data)
        df = _read_sheet_table(data, xls.sheet_names[0])
    df.columns = [canonical_column(c) for c in df.columns]
    bundle.frames[table] = _standardize_generic(df, table, bundle)


def _guess_generic_table(df: pd.DataFrame) -> str:
    cols = set(df.columns)
    if {"fecha", "documento", "codigo_asesor"}.issubset(cols) or {"sale_date", "document_no"}.issubset(cols):
        return "sales"
    if {"fecha", "codigo_asesor", "codigo_cliente", "resultado"}.issubset(cols):
        return "visits"
    if ("saldo" in cols or "balance" in cols) and ("fecha_corte" in cols or "cutoff_date" in cols):
        return "cxc"
    if ("existencia" in cols or "stock" in cols) and ("codigo_producto" in cols or "product_code" in cols):
        return "inventory"
    if "meta_ventas" in cols or "sales_goal" in cols:
        return "advisor_performance"
    if ("codigo_producto" in cols or "product_code" in cols) and ("descripcion" in cols or "producto" in cols or "description" in cols):
        return "products"
    if "codigo_cliente" in cols or "client_code" in cols:
        return "clients"
    if "codigo_asesor" in cols or "advisor_code" in cols:
        return "advisors"
    raise ValueError("No fue posible identificar la estructura del archivo genérico.")


def _coalesce(df: pd.DataFrame, aliases: list[str], default: Any = None) -> pd.Series:
    for alias in aliases:
        key = canonical_column(alias)
        if key in df.columns:
            return df[key]
    return pd.Series([default] * len(df), index=df.index)


def _standardize_generic(df: pd.DataFrame, table: str, bundle: ImportBundle) -> pd.DataFrame:
    df = df.copy()
    df.columns = [canonical_column(c) for c in df.columns]
    source = Path(bundle.filename).stem[:120]

    if table == "supervisors":
        out = pd.DataFrame(
            {
                "supervisor_code": _coalesce(df, ["codigo_supervisor", "supervisor_code", "codigo"]),
                "name": _coalesce(df, ["supervisor", "nombre", "name"]),
                "manager_name": _coalesce(df, ["gerente", "manager_name"], "Gerencia Nacional"),
                "region": _coalesce(df, ["region", "zona"], "Por definir"),
                "active": _coalesce(df, ["activo", "active"], 1),
            }
        )
        out["supervisor_code"] = out.apply(
            lambda r: str(r["supervisor_code"]).strip() if pd.notna(r["supervisor_code"]) and str(r["supervisor_code"]).strip() else slug_code(r["name"], "SUP"), axis=1
        )
        return out.dropna(subset=["name"])

    if table == "advisors":
        out = pd.DataFrame(
            {
                "advisor_code": _coalesce(df, ["codigo_asesor", "advisor_code", "codigo"]),
                "name": _coalesce(df, ["asesor", "nombre", "name"]),
                "supervisor_code": _coalesce(df, ["codigo_supervisor", "supervisor_code"], "SUP-JOHANA"),
                "state": _coalesce(df, ["estado", "state"], "Por definir"),
                "zone": _coalesce(df, ["zona", "zone"], "Por definir"),
                "active": _coalesce(df, ["activo", "active"], 1),
            }
        )
        out["advisor_code"] = out["advisor_code"].map(lambda v: str(int(v)) if parse_number(v) is not None else str(v).strip())
        return out.dropna(subset=["advisor_code", "name"])

    if table == "clients":
        out = pd.DataFrame(
            {
                "client_code": _coalesce(df, ["codigo_cliente", "client_code", "codigo"]),
                "rif": _coalesce(df, ["rif", "rif_cliente"], ""),
                "name": _coalesce(df, ["cliente", "nombre", "razon_social", "name"]),
                "channel": _coalesce(df, ["canal", "channel"], "Por clasificar"),
                "state": _coalesce(df, ["estado", "state"], "Por definir"),
                "city": _coalesce(df, ["ciudad", "city"], "Por definir"),
                "zone": _coalesce(df, ["zona", "zone"], "Por definir"),
                "advisor_code": _coalesce(df, ["codigo_asesor", "advisor_code"], "SIN-ASIGNAR"),
                "status": _coalesce(df, ["estatus", "estado_cliente", "status"], "ACTIVO"),
                "is_new": _coalesce(df, ["es_nuevo", "is_new"], 0),
                "route_week": _coalesce(df, ["semana_ruta", "route_week"], None),
                "route_day": _coalesce(df, ["dia_ruta", "route_day"], ""),
                "source": source,
                "notes": _coalesce(df, ["observaciones", "notes"], ""),
                "phone": _coalesce(df, ["telefono", "phone"], ""),
                "email": _coalesce(df, ["correo", "email"], ""),
                "address": _coalesce(df, ["direccion", "address"], ""),
                "latitude": _coalesce(df, ["latitud", "latitude"], None),
                "longitude": _coalesce(df, ["longitud", "longitude"], None),
            }
        )
        out["client_code"] = out.apply(
            lambda r: str(r["client_code"]).strip() if pd.notna(r["client_code"]) and str(r["client_code"]).strip() else f"CLI-{bundle.file_hash[:6].upper()}-{r.name+1:05d}", axis=1
        )
        return out.dropna(subset=["name"])

    if table == "advisor_performance":
        out = pd.DataFrame(
            {
                "period": _coalesce(df, ["periodo", "period"]),
                "advisor_code": _coalesce(df, ["codigo_asesor", "advisor_code"]),
                "portfolio": _coalesce(df, ["cartera", "portfolio"], 0),
                "activated": _coalesce(df, ["clientes_activados", "activados", "activated"], 0),
                "new_goal": _coalesce(df, ["meta_clientes_nuevos", "new_goal"], 0),
                "new_achieved": _coalesce(df, ["clientes_nuevos", "new_achieved"], 0),
                "sales_goal": _coalesce(df, ["meta_ventas", "sales_goal"], 0),
                "sales_actual": _coalesce(df, ["ventas", "sales_actual"], 0),
                "brand_goal_count": _coalesce(df, ["meta_marcas", "brand_goal_count"], 0),
                "brand_achieved_count": _coalesce(df, ["marcas_logradas", "brand_achieved_count"], 0),
                "observations": _coalesce(df, ["observaciones", "observations"], ""),
                "source": source,
            }
        )
        return out.dropna(subset=["period", "advisor_code"])

    if table == "channels":
        out = pd.DataFrame(
            {
                "channel": _coalesce(df, ["canal", "channel", "nombre"]),
                "short_code": _coalesce(df, ["codigo", "short_code"], ""),
                "source": source,
            }
        )
        return out.dropna(subset=["channel"]).drop_duplicates(subset=["channel"])

    if table == "products":
        out = pd.DataFrame(
            {
                "product_code": _coalesce(df, ["codigo_producto", "product_code", "codigo"]),
                "description": _coalesce(df, ["producto", "descripcion", "descripcion_producto", "description"]),
                "brand": _coalesce(df, ["marca", "brand"], ""),
                "category": _coalesce(df, ["categoria", "category"], ""),
                "department": _coalesce(df, ["departamento", "department"], ""),
                "product_line": _coalesce(df, ["linea_producto", "linea", "product_line"], ""),
                "uom": _coalesce(df, ["unidad_medida", "uom"], "UND"),
                "active": _coalesce(df, ["activo", "active"], 1),
                "source": source,
            }
        )
        out["product_code"] = out["product_code"].map(lambda v: str(v).strip() if pd.notna(v) else "")
        return out.dropna(subset=["description"]).loc[lambda x: x["product_code"] != ""].drop_duplicates(subset=["product_code"])

    if table == "sales":
        out = pd.DataFrame(
            {
                "sale_date": _coalesce(df, ["fecha", "sale_date"]),
                "document_no": _coalesce(df, ["documento", "numero_documento", "document_no"]),
                "line_no": _coalesce(df, ["linea", "numero_linea", "line_no"], None),
                "advisor_code": _coalesce(df, ["codigo_asesor", "codigo_vendedor", "advisor_code"]),
                "client_code": _coalesce(df, ["codigo_cliente", "client_code"]),
                "product_code": _coalesce(df, ["codigo_producto", "product_code"], ""),
                "product_description": _coalesce(df, ["producto", "descripcion_producto", "product_description"], ""),
                "brand": _coalesce(df, ["marca", "brand"], ""),
                "category": _coalesce(df, ["categoria", "departamento", "category"], ""),
                "units": _coalesce(df, ["unidades", "cantidad", "units"], 0),
                "net_amount": _coalesce(df, ["venta_neta", "monto_neto", "ventas", "net_amount"], 0),
                "cost": _coalesce(df, ["costo", "cost"], None),
                "currency": _coalesce(df, ["moneda", "currency"], "USD"),
                "exchange_rate": _coalesce(df, ["tasa_cambio", "exchange_rate"], None),
                "source_hash": bundle.file_hash,
                "source": source,
            }
        )
        out = _assign_missing_invoice_lines(out.reset_index(drop=True))
        return _convert_numeric_and_dates(out, date_columns=["sale_date"], numeric_columns=["units", "net_amount", "cost", "exchange_rate"]).dropna(subset=["sale_date", "document_no"])

    if table == "visits":
        out = pd.DataFrame(
            {
                "visit_date": _coalesce(df, ["fecha", "visit_date"]),
                "advisor_code": _coalesce(df, ["codigo_asesor", "advisor_code"]),
                "client_code": _coalesce(df, ["codigo_cliente", "client_code"]),
                "result": _coalesce(df, ["resultado", "result"]),
                "reason": _coalesce(df, ["motivo_no_venta", "motivo", "reason"], ""),
                "amount_reported": _coalesce(df, ["monto_reportado", "amount_reported"], 0),
                "amount_collected": _coalesce(df, ["monto_cobrado", "amount_collected"], 0),
                "next_action": _coalesce(df, ["proxima_accion", "next_action"], ""),
                "next_visit_date": _coalesce(df, ["fecha_proxima_visita", "next_visit_date"], None),
                "notes": _coalesce(df, ["observaciones", "notes"], ""),
                "latitude": _coalesce(df, ["latitud", "latitude"], None),
                "longitude": _coalesce(df, ["longitud", "longitude"], None),
                "source": source,
            }
        )
        return _convert_numeric_and_dates(out, date_columns=["visit_date", "next_visit_date"], numeric_columns=["amount_reported", "amount_collected", "latitude", "longitude"]).dropna(subset=["visit_date", "advisor_code", "client_code", "result"])

    if table == "cxc":
        out = pd.DataFrame(
            {
                "cutoff_date": _coalesce(df, ["fecha_corte", "cutoff_date"]),
                "client_code": _coalesce(df, ["codigo_cliente", "client_code"]),
                "document_no": _coalesce(df, ["documento", "document_no"], ""),
                "issue_date": _coalesce(df, ["fecha_emision", "issue_date"], None),
                "due_date": _coalesce(df, ["fecha_vencimiento", "due_date"], None),
                "balance": _coalesce(df, ["saldo", "balance"], 0),
                "currency": _coalesce(df, ["moneda", "currency"], "USD"),
                "advisor_code": _coalesce(df, ["codigo_asesor", "advisor_code"], None),
                "source_hash": bundle.file_hash,
                "source": source,
            }
        )
        return _convert_numeric_and_dates(out, date_columns=["cutoff_date", "issue_date", "due_date"], numeric_columns=["balance"]).dropna(subset=["cutoff_date"])

    if table == "inventory":
        out = pd.DataFrame(
            {
                "cutoff_date": _coalesce(df, ["fecha_corte", "cutoff_date"]),
                "branch": _coalesce(df, ["sucursal", "branch"], ""),
                "warehouse": _coalesce(df, ["deposito", "warehouse"], ""),
                "product_code": _coalesce(df, ["codigo_producto", "product_code"]),
                "product_description": _coalesce(df, ["producto", "descripcion_producto", "product_description"], ""),
                "brand": _coalesce(df, ["marca", "brand"], ""),
                "stock": _coalesce(df, ["existencia", "stock"], 0),
                "committed": _coalesce(df, ["comprometido", "committed"], 0),
                "available": _coalesce(df, ["disponible", "available"], None),
                "cost": _coalesce(df, ["costo", "cost"], None),
                "source_hash": bundle.file_hash,
                "source": source,
            }
        )
        out = _convert_numeric_and_dates(out, date_columns=["cutoff_date"], numeric_columns=["stock", "committed", "available", "cost"])
        missing = out["available"].isna()
        out.loc[missing, "available"] = out.loc[missing, "stock"].fillna(0) - out.loc[missing, "committed"].fillna(0)
        return out.dropna(subset=["cutoff_date", "product_code"])

    raise ValueError(f"No existe normalización para la tabla {table}.")


def _convert_numeric_and_dates(df: pd.DataFrame, date_columns: list[str], numeric_columns: list[str]) -> pd.DataFrame:
    for col in date_columns:
        if col in df.columns:
            parsed = pd.to_datetime(df[col], errors="coerce", format="mixed", dayfirst=True)
            df[col] = parsed.dt.strftime("%Y-%m-%d")
    for col in numeric_columns:
        if col in df.columns:
            df[col] = df[col].map(parse_number)
    return df


def _ensure_catalog_dependencies(bundle: ImportBundle, db_path: Path | str = DB_PATH) -> None:
    # Every advisor requires a supervisor. Every sales/visit row requires valid codes.
    supervisor_df = bundle.frames.get("supervisors")
    advisor_df = bundle.frames.get("advisors")
    if supervisor_df is not None and not supervisor_df.empty:
        database.upsert_records("supervisors", dataframe_records(supervisor_df), db_path=db_path)
    # Ensure default supervisor exists before placeholder advisors.
    existing_sup = database.query_df("SELECT supervisor_code FROM supervisors", db_path=db_path)
    if "SUP-JOHANA" not in set(existing_sup.get("supervisor_code", [])):
        database.upsert_records(
            "supervisors",
            [{"supervisor_code": "SUP-JOHANA", "name": "Johana Marcano", "manager_name": "Gerencia Nacional", "region": "Por definir", "active": 1}],
            db_path=db_path,
        )
    if advisor_df is not None and not advisor_df.empty:
        # Add any supervisor codes missing from the catalog.
        existing = set(database.query_df("SELECT supervisor_code FROM supervisors", db_path=db_path)["supervisor_code"].astype(str))
        missing = sorted(set(advisor_df["supervisor_code"].dropna().astype(str)) - existing)
        if missing:
            database.upsert_records(
                "supervisors",
                [{"supervisor_code": code, "name": code, "manager_name": "Gerencia Nacional", "region": "Por definir", "active": 1} for code in missing],
                db_path=db_path,
            )
        database.upsert_records("advisors", dataframe_records(advisor_df), db_path=db_path)

    referenced_advisors: set[str] = set()
    for table in ["advisor_performance", "brand_performance", "clients", "visits", "sales", "cxc"]:
        frame = bundle.frames.get(table)
        if frame is not None and "advisor_code" in frame.columns:
            referenced_advisors.update(str(v) for v in frame["advisor_code"].dropna().tolist() if str(v).strip())
    existing_advisors = set(database.query_df("SELECT advisor_code FROM advisors", db_path=db_path)["advisor_code"].astype(str))
    missing_advisors = sorted(referenced_advisors - existing_advisors)
    if missing_advisors:
        database.upsert_records(
            "advisors",
            [
                {
                    "advisor_code": code,
                    "name": "Sin asignar" if code == "SIN-ASIGNAR" else f"Asesor {code}",
                    "supervisor_code": "SUP-JOHANA",
                    "state": "Por definir",
                    "zone": "Por definir",
                    "active": 1,
                }
                for code in missing_advisors
            ],
            db_path=db_path,
        )
        bundle.warnings.append(f"Se crearon {len(missing_advisors)} asesores temporales porque sus códigos no existían.")

    clients_df = bundle.frames.get("clients")
    if clients_df is not None and not clients_df.empty:
        database.upsert_records("clients", dataframe_records(clients_df), db_path=db_path)

    referenced_clients: set[str] = set()
    for table in ["visits", "sales", "cxc"]:
        frame = bundle.frames.get(table)
        if frame is not None and "client_code" in frame.columns:
            referenced_clients.update(str(v) for v in frame["client_code"].dropna().tolist() if str(v).strip())
    existing_clients = set(database.query_df("SELECT client_code FROM clients", db_path=db_path)["client_code"].astype(str))
    missing_clients = sorted(referenced_clients - existing_clients)
    if missing_clients:
        database.upsert_records(
            "clients",
            [
                {
                    "client_code": code,
                    "rif": "",
                    "name": f"Cliente {code}",
                    "channel": "Por clasificar",
                    "state": "Por definir",
                    "city": "Por definir",
                    "zone": "Por definir",
                    "advisor_code": "SIN-ASIGNAR",
                    "status": "ACTIVO",
                    "is_new": 0,
                    "route_week": None,
                    "route_day": "",
                    "source": "CREADO_POR_IMPORTACION",
                    "notes": "Completar maestro de clientes",
                    "phone": "",
                    "email": "",
                    "address": "",
                    "latitude": None,
                    "longitude": None,
                }
                for code in missing_clients
            ],
            db_path=db_path,
        )
        bundle.warnings.append(f"Se crearon {len(missing_clients)} clientes temporales para no perder líneas de venta/visita.")


def commit_bundle(bundle: ImportBundle, db_path: Path | str = DB_PATH, user_name: str = "Gerencia") -> dict[str, int]:
    if bundle.errors:
        raise ValueError("El archivo contiene errores y no puede importarse.")
    if database.import_exists(bundle.file_hash, db_path=db_path):
        raise ValueError("Este archivo ya fue importado anteriormente. El hash coincide con el registro de auditoría.")

    _ensure_catalog_dependencies(bundle, db_path=db_path)
    order = [
        "supervisors", "advisors", "channels", "products", "clients", "monthly_summary",
        "advisor_performance", "brand_performance", "visits", "sales", "cxc",
        "inventory", "data_quality", "settings",
    ]
    results: dict[str, int] = {}
    received = bundle.rows_received
    imported = 0
    try:
        for table in order:
            frame = bundle.frames.get(table)
            if frame is None or frame.empty:
                continue
            # Dependencies were already inserted; running upsert again is harmless and keeps audit simple.
            count = database.upsert_records(table, dataframe_records(frame), db_path=db_path)
            results[table] = count
            imported += count
        database.log_import(
            filename=bundle.filename,
            file_hash=bundle.file_hash,
            detected_type=bundle.detected_type,
            rows_received=received,
            rows_imported=imported,
            rows_rejected=max(0, received - imported),
            status="IMPORTADO",
            notes=" | ".join(bundle.warnings),
            user_name=user_name,
            db_path=db_path,
        )
    except Exception as exc:  # noqa: BLE001
        database.log_import(
            filename=bundle.filename,
            file_hash=bundle.file_hash,
            detected_type=bundle.detected_type,
            rows_received=received,
            rows_imported=imported,
            rows_rejected=max(0, received - imported),
            status="ERROR",
            notes=str(exc),
            user_name=user_name,
            db_path=db_path,
        )
        raise
    return results


importers = types.SimpleNamespace(
    IMPORT_LABELS=IMPORT_LABELS, ImportBundle=ImportBundle, sha256_bytes=sha256_bytes,
    detect_import_type=detect_import_type, parse_file=parse_file, commit_bundle=commit_bundle,
)


# ============================= REPORTES =============================
@dataclass
class ReportData:
    period: str
    supervisor_code: str | None
    advisor_codes: list[str]
    states: list[str]
    zones: list[str]
    summary: dict[str, float]
    performance: pd.DataFrame
    brands: pd.DataFrame
    clients: pd.DataFrame
    quality: pd.DataFrame
    monthly: pd.DataFrame
    daily_sales: pd.DataFrame
    cxc: pd.DataFrame
    inventory: pd.DataFrame
    filters_label: str


def _clean_df(df: pd.DataFrame) -> pd.DataFrame:
    out = df.copy()
    for col in out.columns:
        if pd.api.types.is_float_dtype(out[col]) or pd.api.types.is_integer_dtype(out[col]):
            out[col] = pd.to_numeric(out[col], errors="coerce")
        else:
            out[col] = out[col].where(out[col].notna(), "")
    return out.replace({np.nan: None, pd.NA: None})



def _report_db_revision(db_path: Path | str) -> tuple:
    """Lightweight change token covering SQLite DB and uncheckpointed WAL writes."""
    root = Path(db_path)
    result = [str(root.resolve())]
    for candidate in (root, Path(str(root) + "-wal")):
        try:
            info = candidate.stat()
            result.append((info.st_mtime_ns, info.st_size, info.st_ino))
        except FileNotFoundError:
            result.append(None)
    return tuple(result)


def _report_signature(period, supervisor, advisor_codes, states, zones, include_clients,
                      include_brands, include_cxc, include_inventory, db_path=DB_PATH):
    return (period, supervisor or "TODOS", tuple(sorted(map(str, advisor_codes))),
            tuple(sorted(map(str, states))), tuple(sorted(map(str, zones))),
            bool(include_clients), bool(include_brands), bool(include_cxc),
            bool(include_inventory), _report_db_revision(db_path))


def _report_filtered_history(advisor_codes, db_path=DB_PATH):
    if not advisor_codes:
        return pd.DataFrame(columns=["period", "portfolio", "activated", "quota", "sales", "activation_pct", "sales_pct"])
    placeholders = ",".join("?" for _ in advisor_codes)
    frame = query_df(f"""SELECT period, SUM(portfolio) AS portfolio, SUM(activated) AS activated,
        SUM(sales_goal) AS quota, SUM(sales_actual) AS sales FROM advisor_performance
        WHERE advisor_code IN ({placeholders}) GROUP BY period ORDER BY period""", list(advisor_codes), db_path=db_path)
    if not frame.empty:
        frame["activation_pct"] = frame["activated"].div(frame["portfolio"].replace(0, np.nan)).fillna(0.0)
        frame["sales_pct"] = frame["sales"].div(frame["quota"].replace(0, np.nan)).fillna(0.0)
    return frame


def _percent_display(frame, columns):
    """Convert only a UI copy; underlying ratios/formulas remain unchanged."""
    out = frame.copy()
    for column in columns:
        if column in out:
            out[column] = pd.to_numeric(out[column], errors="coerce") * 100.0
    return out


def _percent_limit(series, baseline=100.0):
    values = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
    return max(float(baseline), float(values.max()) if not values.empty else float(baseline))


def _assign_missing_invoice_lines(frame):
    """Preserve all source rows; distinct missing line IDs within each invoice."""
    out = frame.copy()
    for _, indexes in out.groupby("document_no", dropna=False, sort=False).groups.items():
        used = {str(value).strip() for value in out.loc[indexes, "line_no"] if pd.notna(value) and str(value).strip()}
        next_line = 1
        for index in indexes:
            value = out.at[index, "line_no"]
            if pd.isna(value) or not str(value).strip():
                while str(next_line) in used:
                    next_line += 1
                out.at[index, "line_no"] = str(next_line)
                used.add(str(next_line))
                next_line += 1
    return out


def collect_report_data(
    period: str, supervisor_code: str | None = None,
    advisor_codes: Sequence[str] | None = None, states: Sequence[str] | None = None,
    zones: Sequence[str] | None = None, *, include_clients: bool = True,
    include_brands: bool = True, include_cxc: bool = True, include_inventory: bool = True,
    db_path: Path | str = DB_PATH,
) -> ReportData:
    advisor_codes, states, zones = list(advisor_codes or []), list(states or []), list(zones or [])
    granular_filter = bool(advisor_codes or states or zones)
    perf = queries.advisor_performance(period, supervisor_code=supervisor_code,
        advisor_codes=advisor_codes or None, states=states or None, zones=zones or None, db_path=db_path)
    official = queries.monthly_summary(period, supervisor_code=supervisor_code, official_only=True, db_path=db_path)
    if not official.empty and not granular_filter:
        total_sales, total_quota = float(official["sales"].sum()), float(official["quota"].sum())
        portfolio, activated = int(official["portfolio"].sum()), int(official["activated"].sum())
        summary_source = "Consolidado oficial"
    else:
        total_sales = float(perf["sales_actual"].sum()) if not perf.empty else 0.0
        total_quota = float(perf["sales_goal"].sum()) if not perf.empty else 0.0
        portfolio = int(perf["portfolio"].sum()) if not perf.empty else 0
        activated = int(perf["activated"].sum()) if not perf.empty else 0
        summary_source = "Suma de asesores filtrados"
    effective = perf["advisor_code"].dropna().astype(str).unique().tolist() if not perf.empty else []
    no_matches = granular_filter and not effective
    summary = {"sales": total_sales, "quota": total_quota,
        "sales_pct": total_sales / total_quota if total_quota else 0.0,
        "portfolio": portfolio, "activated": activated,
        "activation_pct": activated / portfolio if portfolio else 0.0,
        "matrix_sales": float(perf["sales_actual"].sum()) if not perf.empty else 0.0,
        "matrix_quota": float(perf["sales_goal"].sum()) if not perf.empty else 0.0,
        "new_clients": int(perf["new_achieved"].sum()) if not perf.empty else 0,
        "advisors": len(effective), "summary_source": summary_source}
    scoped_codes = effective if granular_filter else None
    # An empty intersection is a real empty scope; never pass it as None (= all).
    if no_matches:
        brands = clients_df = daily = cxc = inventory = quality = pd.DataFrame()
        monthly = _report_filtered_history([], db_path)
    else:
        brands = queries.brand_performance(period, supervisor_code=supervisor_code,
            advisor_codes=scoped_codes, db_path=db_path) if include_brands else pd.DataFrame()
        clients_df = queries.clients(supervisor_code=supervisor_code,
            advisor_codes=scoped_codes, db_path=db_path) if include_clients else pd.DataFrame()
        daily = queries.daily_sales(period, supervisor_code=supervisor_code,
            advisor_codes=scoped_codes, db_path=db_path)
        cxc = queries.cxc_summary(period=period, supervisor_code=supervisor_code,
            advisor_codes=scoped_codes, db_path=db_path) if include_cxc else pd.DataFrame()
        # Inventory has no advisor relationship in this schema; retain it only
        # as explicitly labeled company context, never as advisor stock.
        inventory = queries.inventory_summary(period=period, db_path=db_path) if include_inventory else pd.DataFrame()
        quality = queries.data_quality(period=period, db_path=db_path)
        if granular_filter or (supervisor_code and supervisor_code != "TODOS"):
            # Free-text quality scopes cannot be reliably assigned to advisors.
            quality = quality.iloc[0:0].copy()
        monthly = (_report_filtered_history(effective, db_path) if granular_filter
                   else queries.monthly_history(supervisor_code=supervisor_code, db_path=db_path))
    parts = [f"Periodo: {period_label(period)}", f"Supervisor: {supervisor_code or 'Todos'}"]
    if advisor_codes:
        parts.append(f"Asesores: {len(advisor_codes)} seleccionados; {len(effective)} coinciden")
    if states:
        parts.append("Estados del asesor: " + ", ".join(states))
    if zones:
        parts.append("Zonas del asesor: " + ", ".join(zones))
    if include_inventory and not no_matches:
        parts.append("Inventario: contexto de empresa por depósito, último corte del mes; no asignado por asesor")
    if granular_filter:
        parts.append("Histórico: suma de los mismos asesores seleccionados; puede diferir del consolidado oficial")
    if granular_filter or (supervisor_code and supervisor_code != "TODOS"):
        parts.append("Alertas generales: consultar Administración; se omiten del reporte filtrado porque no tienen relación estructurada con asesor")
    if include_cxc:
        parts.append("CxC: último corte disponible del mes por asesor; importe en moneda de origen")
    omitted = daily.attrs.get("excluded_currency_rows", {})
    parts.append("Ventas diarias: solo USD; sin conversiones automáticas")
    if omitted:
        parts.append("Líneas diarias en otras monedas excluidas del gráfico USD: " + ", ".join(f"{key}: {value}" for key, value in omitted.items()) + "; originales conservados en la base de ventas")
    if no_matches:
        parts.append("Sin coincidencias: no se incluye información de otros asesores")
    return ReportData(period=period, supervisor_code=supervisor_code, advisor_codes=advisor_codes,
        states=states, zones=zones, summary=summary, performance=perf, brands=brands,
        clients=clients_df, quality=quality, monthly=monthly, daily_sales=daily,
        cxc=cxc, inventory=inventory, filters_label=" | ".join(parts))


# ------------------------------- Excel ---------------------------------


def _write_dataframe(
    workbook: xlsxwriter.Workbook,
    worksheet: xlsxwriter.worksheet.Worksheet,
    df: pd.DataFrame,
    start_row: int,
    start_col: int,
    table_name: str,
    *,
    column_formats: dict[str, str] | None = None,
    max_text_width: int = 42,
) -> tuple[int, int]:
    if df.empty:
        worksheet.write(start_row, start_col, "Sin registros para los filtros seleccionados.")
        return start_row + 1, start_col + 1

    column_formats = column_formats or {}
    header_fmt = workbook.add_format(
        {
            "bold": True,
            "font_color": "#FFFFFF",
            "bg_color": COLORS["navy_2"],
            "border": 0,
            "align": "center",
            "valign": "vcenter",
            "text_wrap": True,
        }
    )
    text_fmt = workbook.add_format({"font_color": "#0F172A", "valign": "top"})
    wrap_fmt = workbook.add_format({"font_color": "#0F172A", "valign": "top", "text_wrap": True})
    money_fmt = workbook.add_format({"num_format": '$#,##0.00;[Red]-$#,##0.00', "font_color": "#0F172A"})
    pct_fmt = workbook.add_format({"num_format": "0.0%", "font_color": "#0F172A"})
    int_fmt = workbook.add_format({"num_format": "#,##0", "font_color": "#0F172A"})
    num_fmt = workbook.add_format({"num_format": "#,##0.00", "font_color": "#0F172A"})
    date_fmt = workbook.add_format({"num_format": "dd/mm/yyyy", "font_color": "#0F172A"})
    format_map = {
        "money": money_fmt,
        "percent": pct_fmt,
        "integer": int_fmt,
        "number": num_fmt,
        "date": date_fmt,
        "text": text_fmt,
        "wrap": wrap_fmt,
    }

    clean = _clean_df(df)
    for j, col in enumerate(clean.columns):
        worksheet.write(start_row, start_col + j, str(col), header_fmt)
    for i, row in enumerate(clean.itertuples(index=False, name=None), start=start_row + 1):
        for j, value in enumerate(row):
            col = str(clean.columns[j])
            fmt_name = column_formats.get(col)
            fmt = format_map.get(fmt_name or "", wrap_fmt if isinstance(value, str) and len(value) > 35 else text_fmt)
            if isinstance(value, pd.Timestamp):
                value = value.to_pydatetime()
            if value is None:
                worksheet.write_blank(i, start_col + j, None, fmt)
            else:
                worksheet.write(i, start_col + j, value, fmt)

    first_row, first_col = start_row, start_col
    last_row, last_col = start_row + len(clean), start_col + len(clean.columns) - 1
    columns = [{"header": str(c)} for c in clean.columns]
    worksheet.add_table(first_row, first_col, last_row, last_col, {"name": table_name, "columns": columns, "style": "Table Style Medium 2"})

    for j, col in enumerate(clean.columns):
        values = [len(str(col))] + [len(str(v)) for v in clean[col].dropna().head(250).tolist()]
        width = min(max_text_width, max(10, max(values, default=10) + 2))
        fmt_name = column_formats.get(str(col))
        worksheet.set_column(start_col + j, start_col + j, width, format_map.get(fmt_name or ""))
    return last_row, last_col


def build_excel_report(data: ReportData) -> bytes:
    output = io.BytesIO()
    workbook = xlsxwriter.Workbook(output, {"in_memory": True, "nan_inf_to_errors": True})
    workbook.set_properties(
        {
            "title": f"Reporte Comercial - {period_label(data.period)}",
            "subject": "Seguimiento gerencial de ventas, cartera y marcas",
            "author": "MAKROPETROL NEXUS COMERCIAL",
            "company": "MAKROPETROL, C.A.",
            "comments": f"Generado con {APP_NAME} v{APP_VERSION}",
        }
    )

    fmt_title = workbook.add_format(
        {"bold": True, "font_size": 24, "font_color": "#FFFFFF", "bg_color": COLORS["navy"], "align": "left", "valign": "vcenter"}
    )
    fmt_subtitle = workbook.add_format(
        {"font_size": 11, "font_color": "#CBD5E1", "bg_color": COLORS["navy"], "align": "left", "valign": "vcenter"}
    )
    fmt_section = workbook.add_format(
        {"bold": True, "font_size": 14, "font_color": "#FFFFFF", "bg_color": COLORS["panel"], "align": "left", "valign": "vcenter"}
    )
    fmt_kpi_label = workbook.add_format(
        {"bold": True, "font_size": 10, "font_color": "#475569", "bg_color": "#F8FAFC", "align": "center", "valign": "vcenter", "border": 1, "border_color": "#E2E8F0"}
    )
    fmt_kpi_money = workbook.add_format(
        {"bold": True, "font_size": 18, "font_color": COLORS["navy"], "bg_color": "#FFFFFF", "num_format": '$#,##0.00', "align": "center", "valign": "vcenter", "border": 1, "border_color": "#E2E8F0"}
    )
    fmt_kpi_int = workbook.add_format(
        {"bold": True, "font_size": 18, "font_color": COLORS["navy"], "bg_color": "#FFFFFF", "num_format": "#,##0", "align": "center", "valign": "vcenter", "border": 1, "border_color": "#E2E8F0"}
    )
    fmt_kpi_pct = workbook.add_format(
        {"bold": True, "font_size": 18, "font_color": COLORS["navy"], "bg_color": "#FFFFFF", "num_format": "0.0%", "align": "center", "valign": "vcenter", "border": 1, "border_color": "#E2E8F0"}
    )
    fmt_note = workbook.add_format({"font_color": "#475569", "font_size": 9, "italic": True, "text_wrap": True})
    fmt_alert = workbook.add_format({"bg_color": "#FEF3C7", "font_color": "#92400E", "border": 1, "border_color": "#F59E0B", "text_wrap": True})

    # ---------------- Dashboard ----------------
    ws = workbook.add_worksheet("Resumen Ejecutivo")
    ws.hide_gridlines(2)
    ws.set_tab_color(COLORS["amber"])
    ws.set_landscape()
    ws.fit_to_pages(1, 2)
    ws.set_margins(0.25, 0.25, 0.45, 0.45)
    ws.set_header('&L&"Arial,Bold"MAKROPETROL NEXUS&R&D &T')
    ws.set_footer('&CConfidencial - Uso interno&RPage &P of &N')
    ws.merge_range("A1:N2", f"{APP_NAME}  |  REPORTE EJECUTIVO", fmt_title)
    ws.merge_range("A3:N3", f"{period_label(data.period)}  -  {data.filters_label}", fmt_subtitle)
    ws.merge_range("A4:N4", f"Generado: {datetime.now():%d/%m/%Y %H:%M}  |  Fuente del KPI: {data.summary['summary_source']}", fmt_subtitle)
    ws.set_row(0, 26)
    ws.set_row(1, 26)
    ws.set_row(2, 22)
    ws.set_row(3, 20)
    ws.set_column("A:N", 12)

    kpis = [
        ("VENTAS", data.summary["sales"], fmt_kpi_money),
        ("CUOTA", data.summary["quota"], fmt_kpi_money),
        ("CUMPLIMIENTO", data.summary["sales_pct"], fmt_kpi_pct),
        ("CARTERA", data.summary["portfolio"], fmt_kpi_int),
        ("ACTIVADOS", data.summary["activated"], fmt_kpi_int),
        ("ACTIVACIÓN", data.summary["activation_pct"], fmt_kpi_pct),
        ("ASESORES", data.summary["advisors"], fmt_kpi_int),
    ]
    starts = [(5, 0), (5, 2), (5, 4), (5, 6), (5, 8), (5, 10), (5, 12)]
    for (label, value, val_fmt), (r, c) in zip(kpis, starts):
        ws.merge_range(r, c, r, c + 1, label, fmt_kpi_label)
        ws.merge_range(r + 1, c, r + 2, c + 1, value, val_fmt)

    # Reconciliation callout.
    diff = data.summary["sales"] - data.summary["matrix_sales"]
    ws.merge_range("A10:N10", "CONCILIACIÓN Y CONTROL", fmt_section)
    reconciliation = (
        f"Ventas consolidadas mostradas: {money(data.summary['sales'])}. "
        f"Suma de asesores del filtro: {money(data.summary['matrix_sales'])}. "
        f"Diferencia: {money(diff)}. Revise la hoja Calidad de Datos antes de cerrar el reporte oficial."
    )
    ws.merge_range("A11:N12", reconciliation, fmt_alert if abs(diff) > 0.01 else fmt_note)

    # Monthly chart source table at P columns (hidden later).
    monthly = data.monthly.copy()
    if not monthly.empty:
        monthly["Mes"] = monthly["period"].map(period_label)
        headers = ["Mes", "Cuota", "Ventas", "Activación"]
        for j, h in enumerate(headers):
            ws.write(0, 15 + j, h)
        for i, row in monthly.reset_index(drop=True).iterrows():
            ws.write(i + 1, 15, row["Mes"])
            ws.write_number(i + 1, 16, float(row["quota"]))
            ws.write_number(i + 1, 17, float(row["sales"]))
            ws.write_number(i + 1, 18, float(row["activation_pct"]))
        chart = workbook.add_chart({"type": "column"})
        chart.add_series(
            {
                "name": "Cuota",
                "categories": ["Resumen Ejecutivo", 1, 15, len(monthly), 15],
                "values": ["Resumen Ejecutivo", 1, 16, len(monthly), 16],
                "fill": {"color": COLORS["blue"], "transparency": 35},
                "border": {"none": True},
            }
        )
        chart.add_series(
            {
                "name": "Ventas",
                "categories": ["Resumen Ejecutivo", 1, 15, len(monthly), 15],
                "values": ["Resumen Ejecutivo", 1, 17, len(monthly), 17],
                "fill": {"color": COLORS["amber"]},
                "border": {"none": True},
            }
        )
        chart.add_series(
            {
                "name": "Activación",
                "categories": ["Resumen Ejecutivo", 1, 15, len(monthly), 15],
                "values": ["Resumen Ejecutivo", 1, 18, len(monthly), 18],
                "y2_axis": True,
                "type": "line",
                "line": {"color": COLORS["teal"], "width": 2.5},
                "marker": {"type": "circle", "size": 6, "border": {"color": COLORS["teal"]}, "fill": {"color": COLORS["teal"]}},
            }
        )
        chart.set_title({"name": "Evolución mensual"})
        chart.set_y_axis({"name": "USD", "num_format": '$#,##0,"K"', "major_gridlines": {"visible": True, "line": {"color": "#E2E8F0"}}})
        chart.set_y2_axis({"name": "Activación", "num_format": "0%", "min": 0, "max": 1})
        chart.set_legend({"position": "bottom"})
        chart.set_chartarea({"border": {"none": True}, "fill": {"color": "#FFFFFF"}})
        chart.set_plotarea({"border": {"none": True}, "fill": {"color": "#FFFFFF"}})
        chart.set_style(10)
        ws.insert_chart("A14", chart, {"x_scale": 1.22, "y_scale": 1.20})

    perf = data.performance.copy()
    if not perf.empty:
        perf_chart = perf.nlargest(13, "sales_actual").reset_index(drop=True)
        chart_start = 22
        for j, h in enumerate(["Asesor", "Cuota", "Ventas", "Activación"]):
            ws.write(chart_start, 15 + j, h)
        for i, row in perf_chart.iterrows():
            ws.write(chart_start + 1 + i, 15, row["advisor"])
            ws.write_number(chart_start + 1 + i, 16, float(row["sales_goal"]))
            ws.write_number(chart_start + 1 + i, 17, float(row["sales_actual"]))
            ws.write_number(chart_start + 1 + i, 18, float(row["activation_pct"]))
        chart2 = workbook.add_chart({"type": "bar"})
        chart2.add_series(
            {
                "name": "Cuota",
                "categories": ["Resumen Ejecutivo", chart_start + 1, 15, chart_start + len(perf_chart), 15],
                "values": ["Resumen Ejecutivo", chart_start + 1, 16, chart_start + len(perf_chart), 16],
                "fill": {"color": COLORS["blue"], "transparency": 45},
                "border": {"none": True},
            }
        )
        chart2.add_series(
            {
                "name": "Ventas",
                "categories": ["Resumen Ejecutivo", chart_start + 1, 15, chart_start + len(perf_chart), 15],
                "values": ["Resumen Ejecutivo", chart_start + 1, 17, chart_start + len(perf_chart), 17],
                "fill": {"color": COLORS["amber"]},
                "border": {"none": True},
            }
        )
        chart2.set_title({"name": "Cuota vs. ventas por asesor"})
        chart2.set_x_axis({"num_format": '$#,##0,"K"', "major_gridlines": {"visible": True, "line": {"color": "#E2E8F0"}}})
        chart2.set_legend({"position": "bottom"})
        chart2.set_chartarea({"border": {"none": True}, "fill": {"color": "#FFFFFF"}})
        chart2.set_plotarea({"border": {"none": True}, "fill": {"color": "#FFFFFF"}})
        chart2.set_style(10)
        ws.insert_chart("H14", chart2, {"x_scale": 1.20, "y_scale": 1.20})

    ws.merge_range("A36:N36", "LECTURA GERENCIAL", fmt_section)
    observations: list[str] = []
    if not perf.empty:
        top = perf.nlargest(1, "sales_pct").iloc[0]
        lowest = perf.nsmallest(1, "sales_pct").iloc[0]
        low_activation = perf.nsmallest(1, "activation_pct").iloc[0]
        observations.extend(
            [
                f"Mayor cumplimiento: {top['advisor']} con {top['sales_pct']:.1%} de cuota.",
                f"Menor cumplimiento: {lowest['advisor']} con {lowest['sales_pct']:.1%} de cuota.",
                f"Menor activación: {low_activation['advisor']} con {low_activation['activation_pct']:.1%}.",
            ]
        )
    if not data.quality.empty:
        observations.append(f"Alertas de calidad pendientes: {(data.quality['status'] == 'PENDIENTE').sum()}.")
    ws.merge_range("A37:N40", "\n".join(f"• {v}" for v in observations) if observations else "Sin observaciones automáticas.", fmt_note)
    ws.set_column("P:S", None, None, {"hidden": True})
    ws.freeze_panes(4, 0)

    # ---------------- Advisor performance ----------------
    ws2 = workbook.add_worksheet("Rendimiento Asesores")
    ws2.set_tab_color(COLORS["teal"])
    ws2.hide_gridlines(2)
    ws2.freeze_panes(5, 3)
    ws2.set_landscape()
    ws2.fit_to_pages(1, 0)
    ws2.merge_range("A1:S2", "RENDIMIENTO DETALLADO POR ASESOR", fmt_title)
    ws2.merge_range("A3:S3", data.filters_label, fmt_subtitle)
    perf_out = perf.copy()
    if not perf_out.empty:
        perf_out["activacion_pct"] = perf_out["activation_pct"]
        perf_out["cumplimiento_pct"] = perf_out["sales_pct"]
        perf_out["clientes_nuevos_pct"] = perf_out["new_pct"]
        perf_out["lineas_pct"] = perf_out["brand_pct"]
        perf_out["brecha_ventas"] = perf_out["sales_gap"]
        perf_out["diagnostico"] = [priority_message(a, s) for a, s in zip(perf_out["activation_pct"], perf_out["sales_pct"])]
        perf_out = perf_out[
            [
                "advisor_code", "advisor", "supervisor", "state", "zone", "portfolio", "activated",
                "activacion_pct", "new_goal", "new_achieved", "clientes_nuevos_pct", "sales_goal",
                "sales_actual", "brecha_ventas", "cumplimiento_pct", "brand_goal_count",
                "brand_achieved_count", "lineas_pct", "status", "diagnostico", "observations", "source",
            ]
        ]
        perf_out.columns = [
            "Código", "Asesor", "Supervisor", "Estado", "Zona", "Cartera", "Activados", "Activación %",
            "Meta nuevos", "Nuevos logrados", "Nuevos %", "Cuota USD", "Ventas USD", "Brecha USD",
            "Cumplimiento %", "Meta líneas", "Líneas logradas", "Líneas %", "Semáforo", "Diagnóstico",
            "Observación gerencial", "Fuente",
        ]
    _write_dataframe(
        workbook,
        ws2,
        perf_out,
        4,
        0,
        "tbl_rendimiento_asesores",
        column_formats={
            "Cartera": "integer", "Activados": "integer", "Activación %": "percent", "Meta nuevos": "integer",
            "Nuevos logrados": "integer", "Nuevos %": "percent", "Cuota USD": "money", "Ventas USD": "money",
            "Brecha USD": "money", "Cumplimiento %": "percent", "Meta líneas": "integer", "Líneas logradas": "integer",
            "Líneas %": "percent", "Diagnóstico": "wrap", "Observación gerencial": "wrap",
        },
    )
    if not perf_out.empty:
        last = 4 + len(perf_out)
        sales_pct_col = perf_out.columns.get_loc("Cumplimiento %")
        activation_col = perf_out.columns.get_loc("Activación %")
        status_col = perf_out.columns.get_loc("Semáforo")
        ws2.conditional_format(5, sales_pct_col, last, sales_pct_col, {"type": "3_color_scale", "min_color": "#FECACA", "mid_color": "#FEF3C7", "max_color": "#DCFCE7"})
        ws2.conditional_format(5, activation_col, last, activation_col, {"type": "data_bar", "bar_color": COLORS["teal"]})
        for value, bg, fg in [
            ("ALTO DESEMPEÑO", "#DCFCE7", "#166534"),
            ("SEGUIMIENTO", "#FEF3C7", "#92400E"),
            ("RECUPERACIÓN", "#FFEDD5", "#9A3412"),
            ("CRÍTICO", "#FEE2E2", "#991B1B"),
        ]:
            ws2.conditional_format(5, status_col, last, status_col, {"type": "text", "criteria": "containing", "value": value, "format": workbook.add_format({"bg_color": bg, "font_color": fg, "bold": True})})

    # ---------------- Brands ----------------
    ws3 = workbook.add_worksheet("Marcas y Departamentos")
    ws3.set_tab_color(COLORS["blue"])
    ws3.hide_gridlines(2)
    ws3.freeze_panes(5, 3)
    ws3.set_landscape()
    ws3.merge_range("A1:N2", "INTELIGENCIA DE MARCAS Y DEPARTAMENTOS", fmt_title)
    ws3.merge_range("A3:N3", data.filters_label, fmt_subtitle)
    brands_out = data.brands.copy()
    if not brands_out.empty:
        brands_out = brands_out[
            ["period", "advisor_code", "advisor", "state", "zone", "dimension", "brand", "goal", "actual", "units", "achievement_pct", "gap", "source"]
        ]
        brands_out.columns = ["Periodo", "Código asesor", "Asesor", "Estado", "Zona", "Dimensión", "Marca / línea", "Meta USD", "Logro USD", "Unidades", "Cumplimiento %", "Brecha USD", "Fuente"]
    _write_dataframe(
        workbook,
        ws3,
        brands_out,
        4,
        0,
        "tbl_marcas_departamentos",
        column_formats={"Meta USD": "money", "Logro USD": "money", "Unidades": "number", "Cumplimiento %": "percent", "Brecha USD": "money"},
    )
    if not brands_out.empty:
        last = 4 + len(brands_out)
        pct_col = brands_out.columns.get_loc("Cumplimiento %")
        ws3.conditional_format(5, pct_col, last, pct_col, {"type": "3_color_scale", "min_color": "#FECACA", "mid_color": "#FEF3C7", "max_color": "#DCFCE7"})

    # ---------------- Clients ----------------
    ws4 = workbook.add_worksheet("Clientes")
    ws4.set_tab_color(COLORS["purple"])
    ws4.hide_gridlines(2)
    ws4.freeze_panes(5, 3)
    ws4.set_landscape()
    ws4.merge_range("A1:T2", "MAESTRO Y ESTADO DE CLIENTES", fmt_title)
    ws4.merge_range("A3:T3", data.filters_label, fmt_subtitle)
    clients_out = data.clients.copy()
    if not clients_out.empty:
        selected = [
            "client_code", "rif", "client", "channel", "state", "city", "zone", "advisor_code", "advisor",
            "supervisor", "status", "is_new", "route_week", "route_day", "phone", "email", "address", "source", "notes",
        ]
        clients_out = clients_out[[c for c in selected if c in clients_out.columns]]
        clients_out.columns = [
            "Código cliente", "RIF", "Cliente", "Canal", "Estado", "Ciudad", "Zona", "Código asesor", "Asesor",
            "Supervisor", "Estatus", "Es nuevo", "Semana ruta", "Día ruta", "Teléfono", "Correo", "Dirección", "Fuente", "Notas",
        ][: len(clients_out.columns)]
    _write_dataframe(workbook, ws4, clients_out, 4, 0, "tbl_clientes", column_formats={"Es nuevo": "integer", "Semana ruta": "integer", "Dirección": "wrap", "Notas": "wrap"})

    # ---------------- Quality ----------------
    ws5 = workbook.add_worksheet("Calidad de Datos")
    ws5.set_tab_color(COLORS["red"])
    ws5.hide_gridlines(2)
    ws5.freeze_panes(5, 1)
    ws5.set_landscape()
    ws5.merge_range("A1:L2", "CONTROL DE CALIDAD Y CONCILIACIÓN", fmt_title)
    ws5.merge_range("A3:L3", "Estas alertas deben revisarse antes de declarar el cierre como definitivo.", fmt_subtitle)
    quality_out = data.quality.copy()
    if not quality_out.empty:
        cols = ["issue_id", "period", "scope", "severity", "title", "detail", "expected", "observed", "source_a", "source_b", "status", "created_at"]
        quality_out = quality_out[[c for c in cols if c in quality_out.columns]]
        quality_out.columns = ["ID", "Periodo", "Alcance", "Severidad", "Alerta", "Detalle", "Esperado", "Observado", "Fuente A", "Fuente B", "Estatus", "Fecha"][: len(quality_out.columns)]
    _write_dataframe(workbook, ws5, quality_out, 4, 0, "tbl_calidad_datos", column_formats={"Detalle": "wrap", "Alerta": "wrap", "Esperado": "wrap", "Observado": "wrap"})
    if not quality_out.empty and "Severidad" in quality_out.columns:
        sev_col = quality_out.columns.get_loc("Severidad")
        last = 4 + len(quality_out)
        ws5.conditional_format(5, sev_col, last, sev_col, {"type": "text", "criteria": "containing", "value": "ALTA", "format": workbook.add_format({"bg_color": "#FEE2E2", "font_color": "#991B1B", "bold": True})})
        ws5.conditional_format(5, sev_col, last, sev_col, {"type": "text", "criteria": "containing", "value": "MEDIA", "format": workbook.add_format({"bg_color": "#FEF3C7", "font_color": "#92400E", "bold": True})})

    # ---------------- Daily / CXC / Inventory ----------------
    for sheet_name, title, tab_color, frame, table_name, formats in [
        ("Ventas Diarias", "VENTAS DIARIAS USD · SIN CONVERSIONES", COLORS["amber_2"], data.daily_sales, "tbl_ventas_diarias", {"sales": "money", "units": "number", "transactions": "integer", "clients": "integer"}),
        ("CXC", "CUENTAS POR COBRAR", COLORS["yellow"], data.cxc, "tbl_cxc", {"balance": "money"}),
        ("Inventario", "INVENTARIO DISPONIBLE", COLORS["green"], data.inventory, "tbl_inventario", {"stock": "number", "committed": "number", "available": "number", "cost": "money"}),
    ]:
        sheet = workbook.add_worksheet(sheet_name)
        sheet.set_tab_color(tab_color)
        sheet.hide_gridlines(2)
        sheet.freeze_panes(5, 2)
        sheet.set_landscape()
        sheet.merge_range("A1:L2", title, fmt_title)
        sheet.merge_range("A3:L3", data.filters_label, fmt_subtitle)
        _write_dataframe(workbook, sheet, frame, 4, 0, table_name, column_formats=formats)

    # ---------------- Filters / methodology ----------------
    ws9 = workbook.add_worksheet("Filtros y Metodología")
    ws9.set_tab_color(COLORS["muted"])
    ws9.hide_gridlines(2)
    ws9.set_column("A:A", 27)
    ws9.set_column("B:B", 90)
    ws9.merge_range("A1:B2", "FILTROS, DEFINICIONES Y TRAZABILIDAD", fmt_title)
    rows = [
        ("Periodo", period_label(data.period)),
        ("Supervisor", data.supervisor_code or "Todos"),
        ("Asesores", ", ".join(data.advisor_codes) if data.advisor_codes else "Todos"),
        ("Estados", ", ".join(data.states) if data.states else "Todos"),
        ("Zonas", ", ".join(data.zones) if data.zones else "Todas"),
        ("Fuente KPI consolidado", str(data.summary["summary_source"])),
        ("Venta oficial", money(data.summary["sales"])),
        ("Suma de asesores", money(data.summary["matrix_sales"])),
        ("Cliente activado", "Cliente de cartera con al menos una compra válida dentro del periodo."),
        ("Cumplimiento de cuota", "Ventas netas / cuota asignada."),
        ("Activación", "Clientes activados / cartera asignada."),
        ("Semáforo", "Clasificación configurable combinando cumplimiento de ventas y activación."),
        ("Versión", f"{APP_NAME} v{APP_VERSION}"),
        ("Fecha de generación", f"{datetime.now():%d/%m/%Y %H:%M:%S}"),
    ]
    ws9.write_row(3, 0, ["Parámetro", "Valor / definición"], workbook.add_format({"bold": True, "font_color": "#FFFFFF", "bg_color": COLORS["panel"]}))
    for i, (a, b) in enumerate(rows, start=4):
        ws9.write(i, 0, a, workbook.add_format({"bold": True, "bg_color": "#F1F5F9", "font_color": "#0F172A", "border": 1, "border_color": "#E2E8F0"}))
        ws9.write(i, 1, b, workbook.add_format({"font_color": "#0F172A", "text_wrap": True, "border": 1, "border_color": "#E2E8F0"}))
        ws9.set_row(i, 28 if len(str(b)) > 70 else 20)

    workbook.close()
    output.seek(0)
    return output.getvalue()


# -------------------------------- PDF ----------------------------------


def _register_pdf_font() -> str:
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation2/LiberationSans-Regular.ttf",
    ]
    for candidate in candidates:
        if Path(candidate).exists():
            try:
                pdfmetrics.registerFont(TTFont("NexusSans", candidate))
                return "NexusSans"
            except Exception:
                continue
    return "Helvetica"


def _chart_image(fig: plt.Figure, width_mm: float = 245, height_mm: float = 90) -> Image:
    buffer = io.BytesIO()
    fig.tight_layout()
    fig.savefig(buffer, format="png", dpi=180, bbox_inches="tight", facecolor="white")
    plt.close(fig)
    buffer.seek(0)
    return Image(buffer, width=width_mm * mm, height=height_mm * mm)


def _fmt_usd_axis(x: float, _: Any) -> str:
    if abs(x) >= 1_000_000:
        return f"${x / 1_000_000:.1f}M"
    if abs(x) >= 1_000:
        return f"${x / 1_000:.0f}K"
    return f"${x:,.0f}"


def build_pdf_report(data: ReportData) -> bytes:
    output = io.BytesIO()
    page_size = landscape(A4)
    font_name = _register_pdf_font()
    doc = SimpleDocTemplate(
        output,
        pagesize=page_size,
        rightMargin=12 * mm,
        leftMargin=12 * mm,
        topMargin=15 * mm,
        bottomMargin=13 * mm,
        title=f"Reporte Comercial - {period_label(data.period)}",
        author=APP_NAME,
    )
    styles = getSampleStyleSheet()
    styles.add(
        ParagraphStyle(
            name="NexusTitle",
            parent=styles["Title"],
            fontName=font_name,
            fontSize=24,
            leading=28,
            textColor=colors.HexColor(COLORS["navy"]),
            alignment=TA_LEFT,
            spaceAfter=5 * mm,
        )
    )
    styles.add(
        ParagraphStyle(
            name="NexusSub",
            parent=styles["Normal"],
            fontName=font_name,
            fontSize=9,
            leading=12,
            textColor=colors.HexColor("#475569"),
        )
    )
    styles.add(
        ParagraphStyle(
            name="NexusSection",
            parent=styles["Heading2"],
            fontName=font_name,
            fontSize=15,
            leading=18,
            textColor=colors.HexColor(COLORS["navy"]),
            spaceBefore=4 * mm,
            spaceAfter=3 * mm,
        )
    )
    styles.add(
        ParagraphStyle(
            name="NexusBody",
            parent=styles["BodyText"],
            fontName=font_name,
            fontSize=8.5,
            leading=11,
            textColor=colors.HexColor("#0F172A"),
        )
    )
    styles.add(
        ParagraphStyle(
            name="NexusSmall",
            parent=styles["BodyText"],
            fontName=font_name,
            fontSize=7.2,
            leading=8.8,
            textColor=colors.HexColor("#334155"),
        )
    )

    generated = datetime.now()

    def header_footer(canvas, doc_obj):  # noqa: ANN001
        canvas.saveState()
        width, height = page_size
        canvas.setFillColor(colors.HexColor(COLORS["navy"]))
        canvas.rect(0, height - 9 * mm, width, 9 * mm, fill=1, stroke=0)
        canvas.setFillColor(colors.white)
        canvas.setFont(font_name, 7.5)
        canvas.drawString(12 * mm, height - 6 * mm, APP_NAME)
        canvas.drawRightString(width - 12 * mm, height - 6 * mm, period_label(data.period))
        canvas.setFillColor(colors.HexColor("#64748B"))
        canvas.setFont(font_name, 7)
        canvas.drawString(12 * mm, 6 * mm, "Confidencial - Uso interno")
        canvas.drawRightString(width - 12 * mm, 6 * mm, f"Página {doc_obj.page}")
        canvas.restoreState()

    story: list[Any] = []
    story.append(Spacer(1, 3 * mm))
    story.append(Paragraph("Reporte Ejecutivo de Inteligencia Comercial", styles["NexusTitle"]))
    story.append(Paragraph(data.filters_label, styles["NexusSub"]))
    story.append(Paragraph(f"Generado el {generated:%d/%m/%Y a las %H:%M} - {APP_NAME} v{APP_VERSION}", styles["NexusSub"]))
    story.append(Spacer(1, 5 * mm))

    kpi_headers = ["Ventas", "Cuota", "Cumplimiento", "Cartera", "Activados", "Activación", "Asesores"]
    kpi_values = [
        money(data.summary["sales"]),
        money(data.summary["quota"]),
        percent(data.summary["sales_pct"]),
        f"{int(data.summary['portfolio']):,}",
        f"{int(data.summary['activated']):,}",
        percent(data.summary["activation_pct"]),
        f"{int(data.summary['advisors']):,}",
    ]
    kpi_table = Table([kpi_headers, kpi_values], colWidths=[38 * mm] * 7, rowHeights=[8 * mm, 15 * mm])
    kpi_table.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor(COLORS["panel"])),
                ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
                ("FONTNAME", (0, 0), (-1, -1), font_name),
                ("FONTSIZE", (0, 0), (-1, 0), 7),
                ("FONTSIZE", (0, 1), (-1, 1), 12),
                ("TEXTCOLOR", (0, 1), (-1, 1), colors.HexColor(COLORS["navy"])),
                ("ALIGN", (0, 0), (-1, -1), "CENTER"),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
                ("GRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#CBD5E1")),
                ("BACKGROUND", (0, 1), (-1, 1), colors.HexColor("#F8FAFC")),
            ]
        )
    )
    story.append(kpi_table)
    story.append(Spacer(1, 4 * mm))

    diff = data.summary["sales"] - data.summary["matrix_sales"]
    conc_text = (
        f"<b>Conciliación:</b> el KPI usa {data.summary['summary_source']}. "
        f"Venta mostrada {money(data.summary['sales'])}; suma de asesores {money(data.summary['matrix_sales'])}; "
        f"diferencia {money(diff)}. Las diferencias se detallan en la sección de calidad."
    )
    conc = Table([[Paragraph(conc_text, styles["NexusBody"])]], colWidths=[266 * mm])
    conc.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#FEF3C7") if abs(diff) > 0.01 else colors.HexColor("#ECFDF5")),
                ("BOX", (0, 0), (-1, -1), 0.8, colors.HexColor("#F59E0B") if abs(diff) > 0.01 else colors.HexColor("#10B981")),
                ("LEFTPADDING", (0, 0), (-1, -1), 8),
                ("RIGHTPADDING", (0, 0), (-1, -1), 8),
                ("TOPPADDING", (0, 0), (-1, -1), 7),
                ("BOTTOMPADDING", (0, 0), (-1, -1), 7),
            ]
        )
    )
    story.append(conc)
    story.append(Spacer(1, 5 * mm))

    # Charts on first page.
    if not data.monthly.empty:
        monthly = data.monthly.copy()
        monthly["label"] = monthly["period"].map(period_label)
        fig, ax = plt.subplots(figsize=(10.8, 3.5))
        x = np.arange(len(monthly))
        width = 0.36
        ax.bar(x - width / 2, monthly["quota"], width, label="Cuota")
        ax.bar(x + width / 2, monthly["sales"], width, label="Ventas")
        ax.set_xticks(x)
        ax.set_xticklabels(monthly["label"], rotation=0)
        ax.yaxis.set_major_formatter(FuncFormatter(_fmt_usd_axis))
        ax.grid(axis="y", alpha=0.2)
        ax.legend(frameon=False, ncol=2, loc="upper left")
        ax.set_title("Evolución de ventas vs. cuota")
        story.append(_chart_image(fig, width_mm=126, height_mm=67))

    if not data.performance.empty:
        perf = data.performance.nlargest(13, "sales_actual").sort_values("sales_actual")
        fig2, ax2 = plt.subplots(figsize=(10.8, 4.4))
        y = np.arange(len(perf))
        ax2.barh(y, perf["sales_goal"], label="Cuota", alpha=0.45)
        ax2.barh(y, perf["sales_actual"], label="Ventas", alpha=0.9)
        ax2.set_yticks(y)
        ax2.set_yticklabels(perf["advisor"], fontsize=7)
        ax2.xaxis.set_major_formatter(FuncFormatter(_fmt_usd_axis))
        ax2.grid(axis="x", alpha=0.2)
        ax2.legend(frameon=False, ncol=2, loc="lower right")
        ax2.set_title("Cuota vs. venta por asesor")
        story.append(_chart_image(fig2, width_mm=132, height_mm=82))

    story.append(PageBreak())
    story.append(Paragraph("Rendimiento por asesor", styles["NexusSection"]))
    perf = data.performance.copy()
    if perf.empty:
        story.append(Paragraph("No hay rendimiento de asesores para los filtros seleccionados.", styles["NexusBody"]))
    else:
        table_rows: list[list[Any]] = [["Código", "Asesor", "Zona", "Cartera", "Act.", "Act. %", "Cuota", "Ventas", "Cumpl.", "Semáforo"]]
        for _, row in perf.sort_values("sales_pct", ascending=False).iterrows():
            table_rows.append(
                [
                    str(row["advisor_code"]),
                    Paragraph(str(row["advisor"]), styles["NexusSmall"]),
                    Paragraph(str(row["zone"]), styles["NexusSmall"]),
                    f"{int(row['portfolio']):,}",
                    f"{int(row['activated']):,}",
                    f"{row['activation_pct']:.1%}",
                    f"${row['sales_goal']:,.0f}",
                    f"${row['sales_actual']:,.0f}",
                    f"{row['sales_pct']:.1%}",
                    str(row["status"]),
                ]
            )
        perf_table = Table(table_rows, repeatRows=1, colWidths=[14 * mm, 36 * mm, 42 * mm, 17 * mm, 15 * mm, 18 * mm, 24 * mm, 24 * mm, 19 * mm, 33 * mm])
        style_cmds = [
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor(COLORS["panel"])),
            ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
            ("FONTNAME", (0, 0), (-1, -1), font_name),
            ("FONTSIZE", (0, 0), (-1, -1), 6.4),
            ("ALIGN", (3, 1), (8, -1), "RIGHT"),
            ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#CBD5E1")),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F8FAFC")]),
            ("TOPPADDING", (0, 0), (-1, -1), 4),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 4),
        ]
        for idx, row in enumerate(perf.sort_values("sales_pct", ascending=False).itertuples(), start=1):
            status = getattr(row, "status")
            bg = {
                "ALTO DESEMPEÑO": "#DCFCE7",
                "SEGUIMIENTO": "#FEF3C7",
                "RECUPERACIÓN": "#FFEDD5",
                "CRÍTICO": "#FEE2E2",
            }.get(status, "#F1F5F9")
            style_cmds.append(("BACKGROUND", (9, idx), (9, idx), colors.HexColor(bg)))
        perf_table.setStyle(TableStyle(style_cmds))
        story.append(perf_table)

        story.append(Spacer(1, 5 * mm))
        story.append(Paragraph("Diagnósticos prioritarios", styles["NexusSection"]))
        notes = []
        for _, row in perf.sort_values(["sales_pct", "activation_pct"]).head(6).iterrows():
            text = f"<b>{row['advisor']}:</b> {priority_message(float(row['activation_pct']), float(row['sales_pct']))}"
            notes.append([Paragraph(text, styles["NexusBody"])])
        note_table = Table(notes, colWidths=[266 * mm])
        note_table.setStyle(TableStyle([("ROWBACKGROUNDS", (0, 0), (-1, -1), [colors.HexColor("#F8FAFC"), colors.white]), ("BOX", (0, 0), (-1, -1), 0.35, colors.HexColor("#E2E8F0")), ("INNERGRID", (0, 0), (-1, -1), 0.25, colors.HexColor("#E2E8F0")), ("LEFTPADDING", (0, 0), (-1, -1), 7), ("TOPPADDING", (0, 0), (-1, -1), 5), ("BOTTOMPADDING", (0, 0), (-1, -1), 5)]))
        story.append(note_table)

    story.append(PageBreak())
    story.append(Paragraph("Marcas, departamentos y portafolio", styles["NexusSection"]))
    brands = data.brands.copy()
    if brands.empty:
        story.append(Paragraph("No hay información de marcas para este filtro.", styles["NexusBody"]))
    else:
        agg = brands.groupby(["dimension", "brand"], as_index=False).agg(meta=("goal", "sum"), logro=("actual", "sum"), unidades=("units", "sum"))
        agg["peso"] = agg[["meta", "logro"]].fillna(0).max(axis=1)
        top = agg.nlargest(20, "peso").sort_values("logro")
        fig3, ax3 = plt.subplots(figsize=(11.3, 5.1))
        y = np.arange(len(top))
        ax3.barh(y, top["meta"].fillna(0), label="Meta", alpha=0.4)
        ax3.barh(y, top["logro"].fillna(0), label="Logro", alpha=0.9)
        ax3.set_yticks(y)
        ax3.set_yticklabels(top["brand"], fontsize=7)
        ax3.xaxis.set_major_formatter(FuncFormatter(_fmt_usd_axis))
        ax3.grid(axis="x", alpha=0.2)
        ax3.legend(frameon=False)
        ax3.set_title("Principales líneas / marcas")
        story.append(_chart_image(fig3, width_mm=180, height_mm=100))

        table_rows = [["Dimensión", "Marca / línea", "Meta", "Logro", "Unidades", "Cumplimiento"]]
        top_table = agg.nlargest(22, "peso")
        for _, row in top_table.iterrows():
            ratio = (row["logro"] / row["meta"]) if pd.notna(row["meta"]) and row["meta"] else None
            table_rows.append(
                [
                    Paragraph(str(row["dimension"]), styles["NexusSmall"]),
                    Paragraph(str(row["brand"]), styles["NexusSmall"]),
                    money(row["meta"] or 0),
                    money(row["logro"] or 0),
                    f"{row['unidades']:,.0f}" if pd.notna(row["unidades"]) else "-",
                    f"{ratio:.1%}" if ratio is not None else "-",
                ]
            )
        brand_table = Table(table_rows, repeatRows=1, colWidths=[42 * mm, 70 * mm, 30 * mm, 30 * mm, 25 * mm, 28 * mm])
        brand_table.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, 0), colors.HexColor(COLORS["panel"])), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white), ("FONTNAME", (0, 0), (-1, -1), font_name), ("FONTSIZE", (0, 0), (-1, -1), 6.5), ("ALIGN", (2, 1), (-1, -1), "RIGHT"), ("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#CBD5E1")), ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F8FAFC")]), ("TOPPADDING", (0, 0), (-1, -1), 3.5), ("BOTTOMPADDING", (0, 0), (-1, -1), 3.5)]))
        story.append(brand_table)

    story.append(PageBreak())
    story.append(Paragraph("Clientes y segmentación comercial", styles["NexusSection"]))
    clients = data.clients.copy()
    if clients.empty:
        story.append(Paragraph("No hay clientes para los filtros seleccionados.", styles["NexusBody"]))
    else:
        channel_counts = clients["channel"].fillna("Por clasificar").value_counts().head(12)
        fig4, ax4 = plt.subplots(figsize=(10.8, 4.0))
        ax4.barh(np.arange(len(channel_counts)), channel_counts.values)
        ax4.set_yticks(np.arange(len(channel_counts)))
        ax4.set_yticklabels(channel_counts.index, fontsize=7)
        ax4.set_xlabel("Clientes")
        ax4.grid(axis="x", alpha=0.2)
        ax4.set_title("Distribución de clientes por canal")
        story.append(_chart_image(fig4, width_mm=150, height_mm=80))
        status_counts = clients["status"].fillna("Sin estado").value_counts()
        summary_rows = [["Estatus", "Clientes", "%"]]
        total = len(clients)
        for status, count in status_counts.items():
            summary_rows.append([status, f"{count:,}", f"{count / total:.1%}"])
        status_table = Table(summary_rows, colWidths=[65 * mm, 30 * mm, 30 * mm])
        status_table.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, 0), colors.HexColor(COLORS["panel"])), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white), ("FONTNAME", (0, 0), (-1, -1), font_name), ("FONTSIZE", (0, 0), (-1, -1), 7), ("ALIGN", (1, 1), (-1, -1), "RIGHT"), ("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#CBD5E1")), ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F8FAFC")])]))
        story.append(status_table)
        story.append(Spacer(1, 5 * mm))
        story.append(Paragraph(f"El maestro contiene {len(clients):,} clientes para el filtro. La venta cruzada se habilita con mayor precisión cuando se carguen ventas diarias por cliente y producto.", styles["NexusBody"]))

    story.append(PageBreak())
    story.append(Paragraph("Control de calidad y próximos pasos", styles["NexusSection"]))
    quality = data.quality.copy()
    if quality.empty:
        story.append(Paragraph("No hay alertas registradas para este periodo.", styles["NexusBody"]))
    else:
        rows = [["Severidad", "Alcance", "Alerta", "Esperado", "Observado", "Estatus"]]
        for _, row in quality.iterrows():
            rows.append(
                [
                    str(row["severity"]),
                    Paragraph(str(row["scope"]), styles["NexusSmall"]),
                    Paragraph(f"<b>{row['title']}</b><br/>{row['detail']}", styles["NexusSmall"]),
                    Paragraph(str(row["expected"]), styles["NexusSmall"]),
                    Paragraph(str(row["observed"]), styles["NexusSmall"]),
                    str(row["status"]),
                ]
            )
        q_table = Table(rows, repeatRows=1, colWidths=[22 * mm, 48 * mm, 92 * mm, 34 * mm, 34 * mm, 28 * mm])
        q_table.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, 0), colors.HexColor(COLORS["panel"])), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white), ("FONTNAME", (0, 0), (-1, -1), font_name), ("FONTSIZE", (0, 0), (-1, -1), 6.2), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#CBD5E1")), ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#FFF7ED")]), ("TOPPADDING", (0, 0), (-1, -1), 4), ("BOTTOMPADDING", (0, 0), (-1, -1), 4)]))
        story.append(q_table)

    story.append(Spacer(1, 5 * mm))
    story.append(Paragraph("Definiciones usadas", styles["NexusSection"]))
    definitions = [
        ["Cliente activado", "Cliente de la cartera con una compra válida en el periodo."],
        ["Cumplimiento", "Ventas netas divididas entre la cuota asignada."],
        ["Activación", "Clientes activados divididos entre cartera asignada."],
        ["Semáforo", "Clasificación configurable que combina cumplimiento y activación."],
        ["Venta cruzada", "Oportunidad calculada a partir de canal, historial de marcas, inventario y CXC; requiere ventas detalladas."],
    ]
    def_table = Table([[Paragraph(f"<b>{a}</b>", styles["NexusBody"]), Paragraph(b, styles["NexusBody"])] for a, b in definitions], colWidths=[48 * mm, 218 * mm])
    def_table.setStyle(TableStyle([("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#CBD5E1")), ("ROWBACKGROUNDS", (0, 0), (-1, -1), [colors.HexColor("#F8FAFC"), colors.white]), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("LEFTPADDING", (0, 0), (-1, -1), 6), ("TOPPADDING", (0, 0), (-1, -1), 4), ("BOTTOMPADDING", (0, 0), (-1, -1), 4)]))
    story.append(def_table)

    doc.build(story, onFirstPage=header_footer, onLaterPages=header_footer)
    output.seek(0)
    return output.getvalue()


# ---------------------------- CSV / JSON -------------------------------


def build_csv_zip(data: ReportData) -> bytes:
    output = io.BytesIO()
    tables = {
        "rendimiento_asesores": data.performance,
        "marcas_departamentos": data.brands,
        "clientes": data.clients,
        "calidad_datos": data.quality,
        "historia_mensual": data.monthly,
        "ventas_diarias": data.daily_sales,
        "cxc": data.cxc,
        "inventario": data.inventory,
    }
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for name, frame in tables.items():
            zf.writestr(f"{name}.csv", frame.to_csv(index=False, encoding="utf-8-sig"))
        zf.writestr(
            "resumen.json",
            json.dumps({"periodo": data.period, "filtros": data.filters_label, "resumen": data.summary}, ensure_ascii=False, indent=2),
        )
    output.seek(0)
    return output.getvalue()


def build_json_report(data: ReportData) -> bytes:
    payload = {
        "metadata": {
            "app": APP_NAME,
            "version": APP_VERSION,
            "generated_at": datetime.now().isoformat(timespec="seconds"),
            "period": data.period,
            "filters": data.filters_label,
        },
        "summary": data.summary,
        "performance": data.performance.replace({np.nan: None}).to_dict(orient="records"),
        "brands": data.brands.replace({np.nan: None}).to_dict(orient="records"),
        "clients": data.clients.replace({np.nan: None}).to_dict(orient="records"),
        "quality": data.quality.replace({np.nan: None}).to_dict(orient="records"),
        "monthly": data.monthly.replace({np.nan: None}).to_dict(orient="records"),
        "daily_sales": data.daily_sales.replace({np.nan: None}).to_dict(orient="records"),
        "cxc": data.cxc.replace({np.nan: None}).to_dict(orient="records"),
        "inventory": data.inventory.replace({np.nan: None}).to_dict(orient="records"),
    }
    return json.dumps(payload, ensure_ascii=False, indent=2, default=str).encode("utf-8")


def report_filename(prefix: str, data: ReportData, extension: str) -> str:
    scope = "todos" if not data.advisor_codes else f"{len(data.advisor_codes)}_asesores"
    return f"{safe_filename(prefix)}_{data.period}_{scope}.{extension.lstrip('.')}"


reports = types.SimpleNamespace(
    ReportData=ReportData, collect_report_data=collect_report_data, build_excel_report=build_excel_report,
    build_pdf_report=build_pdf_report, build_csv_zip=build_csv_zip, build_json_report=build_json_report,
    report_filename=report_filename,
)


