def hero(title: str, subtitle: str, eyebrow: str, badges: list[str] | None = None) -> None:
    badge_html = "".join(f'<span class="nexus-badge">{b}</span>' for b in (badges or []))
    st.markdown(
        f"""
        <div class="nexus-hero">
            <div class="nexus-eyebrow">{eyebrow}</div>
            <div class="nexus-title">{title}</div>
            <div class="nexus-subtitle">{subtitle}</div>
            <div>{badge_html}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )


def callout(text: str, severity: str = "info") -> None:
    css = {"high": "nexus-alert-high", "medium": "nexus-alert-medium", "success": "nexus-success"}.get(severity, "")
    st.markdown(f'<div class="nexus-callout {css}">{text}</div>', unsafe_allow_html=True)


def status_html(status: str) -> str:
    cls = {
        "ALTO DESEMPEÑO": "pill-green",
        "SEGUIMIENTO": "pill-yellow",
        "RECUPERACIÓN": "pill-orange",
        "CRÍTICO": "pill-red",
    }.get(status, "pill-yellow")
    return f'<span class="status-pill {cls}">{status}</span>'


def card(label: str, value: str, foot: str = "") -> None:
    st.markdown(
        f'<div class="nexus-card"><div class="nexus-card-title">{label}</div><div class="nexus-card-value">{value}</div><div class="nexus-card-foot">{foot}</div></div>',
        unsafe_allow_html=True,
    )


def plot(fig: go.Figure, key: str | None = None) -> None:
    st.plotly_chart(fig, width="stretch", config={"displaylogo": False, "responsive": True}, key=key)


def _option_map(df: pd.DataFrame, code_col: str, label_col: str) -> tuple[list[str], dict[str, str]]:
    if df.empty:
        return [], {}
    labels = {str(row[code_col]): str(row[label_col]) for _, row in df.iterrows()}
    return list(labels), labels


def _summary_values(period: str, supervisor_code: str | None) -> tuple[dict[str, Any], pd.DataFrame, pd.DataFrame]:
    perf = queries.advisor_performance(period, supervisor_code=supervisor_code, db_path=DB_PATH)
    official = queries.monthly_summary(period, supervisor_code=supervisor_code, official_only=True, db_path=DB_PATH)
    if not official.empty:
        sales = float(official["sales"].sum())
        quota = float(official["quota"].sum())
        portfolio = int(official["portfolio"].sum())
        activated = int(official["activated"].sum())
        source = "Consolidado oficial"
    else:
        sales = float(perf["sales_actual"].sum()) if not perf.empty else 0.0
        quota = float(perf["sales_goal"].sum()) if not perf.empty else 0.0
        portfolio = int(perf["portfolio"].sum()) if not perf.empty else 0
        activated = int(perf["activated"].sum()) if not perf.empty else 0
        source = "Suma de asesores"
    matrix_sales = float(perf["sales_actual"].sum()) if not perf.empty else 0.0
    return (
        {
            "sales": sales,
            "quota": quota,
            "sales_pct": sales / quota if quota else 0.0,
            "portfolio": portfolio,
            "activated": activated,
            "activation_pct": activated / portfolio if portfolio else 0.0,
            "matrix_sales": matrix_sales,
            "difference": sales - matrix_sales,
            "source": source,
        },
        perf,
        official,
    )


def sidebar() -> tuple[str, str, str | None]:
    with st.sidebar:
        st.markdown(
            f"""
            <div style="padding:.6rem .15rem 1rem;">
                <div style="font-size:.72rem;color:#FFB703;font-weight:850;letter-spacing:.14em;">MAKROPETROL</div>
                <div style="font-size:1.25rem;color:#F8FAFC;font-weight:850;line-height:1.15;">NEXUS COMERCIAL</div>
                <div style="font-size:.72rem;color:#94A3B8;margin-top:.3rem;">v{APP_VERSION} · Piloto escalable nacional</div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        periods = queries.available_periods(DB_PATH)
        if not periods:
            periods = [datetime.now().strftime("%Y-%m")]
        period = st.selectbox("Periodo de análisis", periods, format_func=period_label, key="global_period")

        sups = queries.supervisors(DB_PATH)
        sup_codes, sup_labels = _option_map(sups, "supervisor_code", "name")
        supervisor_choices = ["TODOS"] + sup_codes
        supervisor = st.selectbox(
            "Supervisor",
            supervisor_choices,
            format_func=lambda x: "Todos los supervisores" if x == "TODOS" else sup_labels.get(x, x),
            key="global_supervisor",
        )
        page = st.radio("Navegación", NAV_ITEMS, label_visibility="collapsed", key="global_page")
        st.markdown('<div class="nexus-divider"></div>', unsafe_allow_html=True)
        st.caption("Los nombres, zonas, metas y reglas son dinámicos. Al cargar nuevos catálogos, los filtros y gráficos se adaptan sin editar el código.")
        st.caption("Base actual: piloto Johana · agosto 2026")
    return page, period, None if supervisor == "TODOS" else supervisor


def render_app() -> None:
    page, period, supervisor = sidebar()
    page_func: dict[str, Callable[[str, str | None], None]] = {
        "Centro de Comando": page_command_center,
        "Supervisores": page_supervisors,
        "Asesor 360°": page_advisor_360,
        "Marcas y Departamentos": page_brands,
        "Clientes y Venta Cruzada": page_clients,
        "Rutas y Visitas": page_routes,
        "Carga de Datos": page_upload,
        "Reportes Ejecutivos": page_reports,
        "Administración": page_admin,
    }
    page_func[page](period, supervisor)


# ---------------------------------------------------------------------
# Page 1: Command Center
# ---------------------------------------------------------------------


def page_command_center(period: str, supervisor: str | None) -> None:
    summary, perf, _ = _summary_values(period, supervisor)
    history = queries.monthly_history(supervisor_code=supervisor, db_path=DB_PATH)
    quality = queries.data_quality(period=period, status="PENDIENTE", db_path=DB_PATH)
    daily = queries.daily_sales(period, supervisor_code=supervisor, db_path=DB_PATH)

    hero(
        "Centro de Comando Gerencial",
        "Diagnóstico ejecutivo de ventas, cuota, activación, territorios y riesgos. El tablero usa el consolidado oficial cuando existe y mantiene visible la conciliación contra la suma de asesores.",
        "Visión nacional / gerencial",
        [period_label(period), summary["source"], f"{len(perf)} asesores", f"{len(quality)} alertas pendientes"],
    )

    cols = st.columns(6)
    metrics = [
        ("Ventas", money(summary["sales"]), f"{percent(summary['sales_pct'])} de cuota"),
        ("Cuota", money(summary["quota"]), f"Brecha {money(summary['sales'] - summary['quota'])}"),
        ("Cartera", integer(summary["portfolio"]), "clientes asignados"),
        ("Activados", integer(summary["activated"]), f"{percent(summary['activation_pct'])} de activación"),
        ("Venta asesores", money(summary["matrix_sales"]), "suma matriz individual"),
        ("Diferencia", money(summary["difference"]), "oficial vs. asesores"),
    ]
    for col, (label, value, foot) in zip(cols, metrics):
        with col:
            card(label, value, foot)

    if abs(summary["difference"]) > 0.01:
        callout(
            f"<b>Conciliación pendiente:</b> el consolidado reporta {money(summary['sales'])} y la matriz individual suma {money(summary['matrix_sales'])}. "
            f"La diferencia de {money(summary['difference'])} se mantiene visible para evitar presentar un cierre sin revisión.",
            "high",
        )
    else:
        callout("El consolidado y la suma de asesores están conciliados para el filtro seleccionado.", "success")

    c1, c2, c3 = st.columns([1.05, 1.05, 1.9])
    with c1:
        plot(charts.gauge(summary["sales_pct"], "Cumplimiento de cuota"), "home_sales_gauge")
    with c2:
        plot(charts.gauge(summary["activation_pct"], "Activación de cartera", target=0.60), "home_activation_gauge")
    with c3:
        plot(charts.monthly_combo(history), "home_monthly")

    if period == datetime.now().strftime("%Y-%m"):
        settings = database.get_settings(DB_PATH)
        include_saturday = bool(int(settings.get("work_saturdays", "0") or 0))
        projected = run_rate(summary["sales"], period, include_saturday=include_saturday)
        elapsed, total = business_days(period, include_saturday=include_saturday)
        required = max(0.0, (summary["quota"] - summary["sales"]) / max(total - elapsed, 1))
        callout(
            f"<b>Run Rate:</b> con {elapsed} de {total} días hábiles, la proyección es {money(projected)}. "
            f"La venta diaria requerida para alcanzar la cuota es {money(required)}.",
            "info",
        )
    else:
        callout("El periodo está cerrado o no corresponde al mes actual; la proyección Run Rate se reemplaza por resultados finales.")

    tab1, tab2, tab3 = st.tabs(["Desempeño del equipo", "Territorios", "Matriz de control"])
    with tab1:
        a, b = st.columns([1.25, 1])
        with a:
            plot(charts.advisor_ranking(perf), "home_rank")
        with b:
            plot(charts.status_donut(perf), "home_status")
        plot(charts.advisor_scatter(perf), "home_scatter")
    with tab2:
        plot(charts.territory_treemap(perf), "home_treemap")
        if not perf.empty:
            state_view = perf.groupby("state", dropna=False, as_index=False).agg(
                ventas=("sales_actual", "sum"), cuota=("sales_goal", "sum"), cartera=("portfolio", "sum"), activados=("activated", "sum")
            )
            state_view["cumplimiento"] = state_view["ventas"].div(state_view["cuota"].replace(0, pd.NA)).fillna(0)
            state_view["activacion"] = state_view["activados"].div(state_view["cartera"].replace(0, pd.NA)).fillna(0)
            st.dataframe(
                state_view,
                hide_index=True,
                width="stretch",
                column_config={
                    "ventas": st.column_config.NumberColumn("Ventas", format="$%,.2f"),
                    "cuota": st.column_config.NumberColumn("Cuota", format="$%,.2f"),
                    "cumplimiento": st.column_config.ProgressColumn("Cumplimiento", min_value=0, max_value=max(1.5, float(state_view["cumplimiento"].max() or 1)), format="%.1f%%"),
                    "activacion": st.column_config.ProgressColumn("Activación", min_value=0, max_value=1, format="%.1f%%"),
                },
            )
    with tab3:
        plot(charts.performance_heatmap(perf), "home_heatmap")
        if not daily.empty:
            plot(charts.daily_sales_line(daily, summary["quota"]), "home_daily")
        else:
            callout("La curva diaria se activará cuando se cargue el reporte de ventas por fecha y documento. Los datos mensuales actuales no incluyen esa granularidad.")

    st.markdown("### Diagnóstico automático")
    if perf.empty:
        st.info("No hay asesores para este periodo.")
    else:
        top = perf.nlargest(1, "sales_pct").iloc[0]
        low = perf.nsmallest(1, "sales_pct").iloc[0]
        low_act = perf.nsmallest(1, "activation_pct").iloc[0]
        d1, d2, d3 = st.columns(3)
        with d1:
            callout(f"<b>Líder de cuota:</b> {top['advisor']} · {top['sales_pct']:.1%} · {money(top['sales_actual'])}.", "success")
        with d2:
            callout(f"<b>Mayor brecha:</b> {low['advisor']} · {low['sales_pct']:.1%} · faltan {money(max(0, -low['sales_gap']))}.", "high")
        with d3:
            callout(f"<b>Menor activación:</b> {low_act['advisor']} · {low_act['activation_pct']:.1%} de su cartera.", "medium")

    with st.expander(f"Control de calidad ({len(quality)} pendientes)", expanded=bool(len(quality))):
        if quality.empty:
            st.success("No existen alertas pendientes para este periodo.")
        else:
            st.dataframe(
                quality[["severity", "scope", "title", "detail", "expected", "observed", "status"]],
                hide_index=True,
                width="stretch",
                column_config={
                    "severity": st.column_config.TextColumn("Severidad"),
                    "scope": "Alcance",
                    "title": "Alerta",
                    "detail": st.column_config.TextColumn("Detalle", width="large"),
                    "expected": "Esperado",
                    "observed": "Observado",
                    "status": "Estatus",
                },
            )


# ---------------------------------------------------------------------
# Page 2: Supervisors
# ---------------------------------------------------------------------


def page_supervisors(period: str, supervisor: str | None) -> None:
    sups = queries.supervisors(DB_PATH)
    hero(
        "Monitor de Supervisores y Equipos",
        "Vista media para comparar estructuras, filtrar territorios y detectar asesores que requieren intervención. Cuando se añadan más supervisores, aparecerán automáticamente en este módulo.",
        "Jerarquía dinámica",
        [period_label(period), f"{len(sups)} supervisor(es) cargados"],
    )

    sup_codes, sup_labels = _option_map(sups, "supervisor_code", "name")
    default_idx = sup_codes.index(supervisor) if supervisor in sup_codes else 0
    selected = st.selectbox("Supervisor a analizar", sup_codes, index=default_idx if sup_codes else 0, format_func=lambda x: sup_labels.get(x, x)) if sup_codes else None
    if not selected:
        st.warning("No hay supervisores registrados.")
        return

    base = queries.advisor_performance(period, supervisor_code=selected, db_path=DB_PATH)
    if base.empty:
        st.info("No existen metas/rendimiento para el supervisor y periodo seleccionados.")
        return

    f1, f2, f3 = st.columns(3)
    states = sorted(base["state"].dropna().astype(str).unique().tolist())
    zones = sorted(base["zone"].dropna().astype(str).unique().tolist())
    with f1:
        sel_states = st.multiselect("Estados", states, key="sup_states")
    with f2:
        sel_zones = st.multiselect("Zonas", zones, key="sup_zones")
    with f3:
        sel_status = st.multiselect("Semáforo", ["ALTO DESEMPEÑO", "SEGUIMIENTO", "RECUPERACIÓN", "CRÍTICO"], key="sup_status")

    perf = queries.advisor_performance(period, supervisor_code=selected, states=sel_states or None, zones=sel_zones or None, db_path=DB_PATH)
    if sel_status:
        perf = perf[perf["status"].isin(sel_status)]

    sales = float(perf["sales_actual"].sum())
    quota = float(perf["sales_goal"].sum())
    portfolio = int(perf["portfolio"].sum())
    activated = int(perf["activated"].sum())
    m1, m2, m3, m4, m5 = st.columns(5)
    m1.metric("Ventas del equipo", money(sales), f"{sales / quota:.1%}" if quota else "Sin cuota")
    m2.metric("Cuota", money(quota))
    m3.metric("Cartera", integer(portfolio))
    m4.metric("Activados", integer(activated), f"{activated / portfolio:.1%}" if portfolio else "0%")
    m5.metric("Asesores visibles", integer(len(perf)))

    a, b = st.columns([1.25, 1])
    with a:
        plot(charts.goal_actual_bar(perf, metric="sales"), "sup_sales")
    with b:
        plot(charts.status_donut(perf), "sup_status_donut")
    plot(charts.performance_heatmap(perf), "sup_heatmap")

    t1, t2, t3 = st.tabs(["Activación", "Clientes nuevos", "Líneas / marcas"])
    with t1:
        plot(charts.goal_actual_bar(perf, metric="activation"), "sup_activation")
    with t2:
        plot(charts.goal_actual_bar(perf, metric="new"), "sup_new")
    with t3:
        plot(charts.goal_actual_bar(perf, metric="brands"), "sup_brands")

    table = perf.copy()
    table["Diagnóstico"] = [priority_message(a, s) for a, s in zip(table["activation_pct"], table["sales_pct"])]
    table = table.rename(
        columns={
            "advisor_code": "Código",
            "advisor": "Asesor",
            "state": "Estado",
            "zone": "Zona",
            "portfolio": "Cartera",
            "activated": "Activados",
            "activation_pct": "Activación",
            "sales_goal": "Cuota",
            "sales_actual": "Ventas",
            "sales_pct": "Cumplimiento",
            "sales_gap": "Brecha",
            "new_achieved": "Nuevos",
            "status": "Semáforo",
            "observations": "Observación",
        }
    )
    table = _percent_display(table, ["Activación", "Cumplimiento"])
    st.dataframe(
        table[["Código", "Asesor", "Estado", "Zona", "Cartera", "Activados", "Activación", "Cuota", "Ventas", "Cumplimiento", "Brecha", "Nuevos", "Semáforo", "Diagnóstico", "Observación"]],
        hide_index=True,
        width="stretch",
        column_config={
            "Activación": st.column_config.ProgressColumn("Activación", min_value=0, max_value=_percent_limit(table["Activación"], 100.0), format="%.1f%%"),
            "Cumplimiento": st.column_config.ProgressColumn("Cumplimiento", min_value=0, max_value=_percent_limit(table["Cumplimiento"], 210.0), format="%.1f%%"),
            "Cuota": st.column_config.NumberColumn("Cuota", format="$%,.2f"),
            "Ventas": st.column_config.NumberColumn("Ventas", format="$%,.2f"),
            "Brecha": st.column_config.NumberColumn("Brecha", format="$%,.2f"),
            "Diagnóstico": st.column_config.TextColumn("Diagnóstico", width="large"),
            "Observación": st.column_config.TextColumn("Observación", width="large"),
        },
    )


# ---------------------------------------------------------------------
# Page 3: Advisor 360
# ---------------------------------------------------------------------


def page_advisor_360(period: str, supervisor: str | None) -> None:
    catalog = queries.advisor_catalog(DB_PATH, supervisor_code=supervisor)
    hero(
        "Asesor 360°",
        "Ficha individual con cuota, activación, captación, portafolio, clientes y observaciones gerenciales. La misma pantalla funcionará para cualquier vendedor que se agregue al maestro.",
        "Radiografía comercial",
        [period_label(period), f"{len(catalog[catalog['advisor_code'] != 'SIN-ASIGNAR']) if not catalog.empty else 0} asesores disponibles"],
    )
    catalog = catalog[catalog["advisor_code"] != "SIN-ASIGNAR"].copy()
    if catalog.empty:
        st.info("No hay asesores registrados.")
        return
    codes, labels = _option_map(catalog, "advisor_code", "name")
    selected = st.selectbox("Seleccionar asesor", codes, format_func=lambda x: f"{x} · {labels.get(x, x)}", key="advisor360_select")
    perf = queries.advisor_performance(period, advisor_codes=[selected], db_path=DB_PATH)
    if perf.empty:
        st.warning("Este asesor no tiene un registro de metas para el periodo seleccionado.")
        return
    row = perf.iloc[0]
    st.markdown(f"### {row['advisor']} &nbsp; {status_html(row['status'])}", unsafe_allow_html=True)
    st.caption(f"Código {row['advisor_code']} · {row['supervisor']} · {row['state']} · {row['zone']}")

    c = st.columns(7)
    values = [
        ("Ventas", money(row["sales_actual"]), f"Cuota {money(row['sales_goal'])}"),
        ("Cumplimiento", percent(row["sales_pct"]), f"Brecha {money(row['sales_gap'])}"),
        ("Cartera", integer(row["portfolio"]), "clientes asignados"),
        ("Activados", integer(row["activated"]), percent(row["activation_pct"])),
        ("Nuevos", integer(row["new_achieved"]), f"meta {integer(row['new_goal'])}"),
        ("Líneas", integer(row["brand_achieved_count"]), f"meta {integer(row['brand_goal_count'])}"),
        ("Zona", str(row["zone"]), str(row["state"])),
    ]
    for col, (label, value, foot) in zip(c, values):
        with col:
            card(label, value, foot)

    callout(f"<b>Lectura:</b> {priority_message(float(row['activation_pct']), float(row['sales_pct']))}")
    if str(row.get("observations") or "").strip():
        callout(f"<b>Observación de gerencia:</b> {row['observations']}", "medium")

    a, b = st.columns([1, 1.55])
    with a:
        plot(
            charts.radar(
                {
                    "Ventas": float(row["sales_pct"]),
                    "Activación": float(row["activation_pct"]),
                    "Captación": float(row["new_pct"]),
                    "Líneas": float(row["brand_pct"]),
                },
                "Índice multidimensional",
            ),
            "advisor_radar",
        )
    with b:
        bdf = queries.brand_performance(period, advisor_codes=[selected], db_path=DB_PATH)
        dims = sorted(bdf["dimension"].dropna().unique().tolist()) if not bdf.empty else []
        dimension = st.selectbox("Vista de portafolio", dims, key="advisor_dimension") if dims else None
        view = bdf[bdf["dimension"] == dimension] if dimension else bdf
        if dimension in {"MARCA DETALLE", "DEPARTAMENTO DETALLE"}:
            plot(charts.brand_units_amount(view), "advisor_brand_detail")
        else:
            plot(charts.brand_goal_actual(view), "advisor_brand_goal")

    tab1, tab2, tab3 = st.tabs(["Clientes", "Portafolio completo", "Conciliación"])
    with tab1:
        client_df = queries.clients(advisor_codes=[selected], db_path=DB_PATH)
        if client_df.empty:
            st.info("No se han cargado clientes asociados a este asesor.")
        else:
            x, y, z = st.columns(3)
            with x:
                plot(charts.client_status_donut(client_df), "advisor_client_status")
            with y:
                plot(charts.channel_donut(client_df), "advisor_client_channels")
            with z:
                plot(charts.route_zone_bar(client_df), "advisor_client_zones")
            status_filter = st.multiselect("Filtrar estatus de clientes", sorted(client_df["status"].dropna().unique()), key="advisor_client_status_filter")
            visible = client_df[client_df["status"].isin(status_filter)] if status_filter else client_df
            st.dataframe(
                visible[["client_code", "client", "channel", "status", "is_new", "route_week", "route_day", "source", "notes"]],
                hide_index=True,
                width="stretch",
                column_config={
                    "client_code": "Código",
                    "client": "Cliente",
                    "channel": "Canal",
                    "status": "Estatus",
                    "is_new": st.column_config.CheckboxColumn("Nuevo"),
                    "route_week": "Semana",
                    "route_day": "Día",
                    "source": "Fuente",
                    "notes": st.column_config.TextColumn("Notas", width="large"),
                },
            )
    with tab2:
        bdf = queries.brand_performance(period, advisor_codes=[selected], db_path=DB_PATH)
        if bdf.empty:
            st.info("No hay metas o ventas por marca para este asesor.")
        else:
            st.dataframe(
                _percent_display(bdf[["dimension", "brand", "goal", "actual", "units", "achievement_pct", "gap", "source"]], ["achievement_pct"]),
                hide_index=True,
                width="stretch",
                column_config={
                    "dimension": "Dimensión",
                    "brand": "Marca / línea",
                    "goal": st.column_config.NumberColumn("Meta", format="$%,.2f"),
                    "actual": st.column_config.NumberColumn("Logro", format="$%,.2f"),
                    "units": st.column_config.NumberColumn("Unidades", format="%,.0f"),
                    "achievement_pct": st.column_config.ProgressColumn("Cumplimiento", min_value=0, max_value=_percent_limit(bdf["achievement_pct"] * 100, 200.0), format="%.1f%%"),
                    "gap": st.column_config.NumberColumn("Brecha", format="$%,.2f"),
                    "source": "Fuente",
                },
            )
    with tab3:
        q = queries.data_quality(period=period, db_path=DB_PATH)
        q = q[q["scope"].astype(str).str.contains(str(selected), case=False, na=False) | q["scope"].astype(str).str.contains(str(row["advisor"]), case=False, na=False)]
        if q.empty:
            st.success("No hay alertas de conciliación registradas para este asesor.")
        else:
            for _, issue in q.iterrows():
                callout(
                    f"<b>{issue['title']}</b><br>{issue['detail']}<br><span class='nexus-mini'>Esperado: {issue['expected']} · Observado: {issue['observed']} · {issue['source_a']} vs. {issue['source_b']}</span>",
                    "high" if issue["severity"] == "ALTA" else "medium",
                )


# ---------------------------------------------------------------------
# Page 4: Brands
# ---------------------------------------------------------------------


def page_brands(period: str, supervisor: str | None) -> None:
    hero(
        "Inteligencia de Marcas y Departamentos",
        "Análisis del peso comercial de cada línea, meta vs. logro, unidades y distribución por asesor. El sistema mantiene dimensiones separadas para no mezclar cuotas de marca con ventas detalladas del cierre.",
        "Portafolio y rotación",
        [period_label(period), "Marcas", "Departamentos", "Unidades y USD"],
    )
    base = queries.brand_performance(period, supervisor_code=supervisor, db_path=DB_PATH)
    if base.empty:
        st.info("No se ha cargado información por marca/departamento para este periodo.")
        return

    catalog = queries.advisor_catalog(DB_PATH, supervisor_code=supervisor)
    code_to_name = dict(zip(catalog["advisor_code"], catalog["name"])) if not catalog.empty else {}
    f1, f2, f3 = st.columns([1, 1.2, 1])
    dims = sorted(base["dimension"].dropna().astype(str).unique().tolist())
    with f1:
        dimension = st.selectbox("Dimensión", dims, key="brands_dimension_v2")
        st.caption("Se analiza una dimensión a la vez: marcas y departamentos pueden representar las mismas ventas.")
    with f2:
        selected_advisors = st.multiselect("Asesores", sorted(base["advisor_code"].unique()), format_func=lambda x: code_to_name.get(x, x), key="brands_advisors")
    with f3:
        top_n = st.slider("Elementos visibles", 5, 35, 20, key="brands_top_n")

    view = queries.brand_performance(period, supervisor_code=supervisor, advisor_codes=selected_advisors or None, dimension=dimension, db_path=DB_PATH)
    total_goal = float(view["goal"].fillna(0).sum())
    total_actual = float(view["actual"].fillna(0).sum())
    total_units = float(view["units"].fillna(0).sum())
    unique = int(view["brand"].nunique())
    top_brand = "-"
    if not view.empty and view["actual"].notna().any():
        top_brand = str(view.groupby("brand")["actual"].sum().idxmax())

    c1, c2, c3, c4, c5 = st.columns(5)
    c1.metric("Meta agregada", money(total_goal))
    c2.metric("Logro agregado", money(total_actual), f"{total_actual / total_goal:.1%}" if total_goal else "Sin meta comparable")
    c3.metric("Unidades", f"{total_units:,.0f}")
    c4.metric("Marcas / líneas", unique)
    c5.metric("Mayor monto", top_brand)

    a, b = st.columns([1.1, 1])
    with a:
        plot(charts.brand_goal_actual(view, top_n=top_n), "brand_goal_actual")
    with b:
        plot(charts.brand_units_amount(view, top_n=top_n), "brand_units")
    plot(charts.brand_heatmap(view, top_n=min(top_n, 20)), "brand_heat")

    if not view.empty:
        treemap_df = view.copy()
        treemap_df["actual_plot"] = treemap_df["actual"].fillna(0)
        if treemap_df["actual_plot"].sum() <= 0:
            treemap_df["actual_plot"] = treemap_df["goal"].fillna(0)
        treemap_df = treemap_df[treemap_df["actual_plot"] > 0]
        if not treemap_df.empty:
            fig = px.treemap(
                treemap_df,
                path=[px.Constant("Portafolio"), "dimension", "brand", "advisor"],
                values="actual_plot",
                color="actual_plot",
                color_continuous_scale=[COLORS["navy_2"], COLORS["blue"], COLORS["amber"]],
                hover_data={"goal": ":$,.2f", "actual": ":$,.2f", "units": ":,.0f"},
            )
            fig.update_layout(height=510, margin=dict(l=15, r=15, t=55, b=15), title="Mapa de peso por dimensión, marca y asesor", paper_bgcolor="rgba(0,0,0,0)", font_color=COLORS["white"])
            plot(fig, "brand_treemap")

    st.dataframe(
        _percent_display(view[["advisor_code", "advisor", "state", "zone", "dimension", "brand", "goal", "actual", "units", "achievement_pct", "gap", "source"]], ["achievement_pct"]),
        hide_index=True,
        width="stretch",
        column_config={
            "advisor_code": "Código",
            "advisor": "Asesor",
            "state": "Estado",
            "zone": "Zona",
            "dimension": "Dimensión",
            "brand": "Marca / línea",
            "goal": st.column_config.NumberColumn("Meta", format="$%,.2f"),
            "actual": st.column_config.NumberColumn("Logro", format="$%,.2f"),
            "units": st.column_config.NumberColumn("Unidades", format="%,.0f"),
            "achievement_pct": st.column_config.ProgressColumn("Cumplimiento", min_value=0, max_value=_percent_limit(view["achievement_pct"] * 100, 200.0), format="%.1f%%"),
            "gap": st.column_config.NumberColumn("Brecha", format="$%,.2f"),
            "source": "Fuente",
        },
    )


