# Page 5: Clients
# ---------------------------------------------------------------------


def page_clients(period: str, supervisor: str | None) -> None:
    hero(
        "Clientes y Venta Cruzada",
        "Buscador 360° de cartera, canales, zonas, asesor asignado y estado de activación. La recomendación de venta cruzada se volverá exacta al cargar las líneas de factura por cliente, producto y marca.",
        "Cartera inteligente",
        [period_label(period), "Canales comerciales", "Activación", "Cross-selling preparado"],
    )
    base = queries.clients(supervisor_code=supervisor, db_path=DB_PATH)
    if base.empty:
        st.info("No hay clientes cargados en el maestro.")
        return

    f1, f2, f3, f4 = st.columns([1.4, 1, 1, 1])
    with f1:
        search = st.text_input("Buscar cliente, RIF o código", placeholder="Ej. AUTO ELECTRIC GUAICAIPURO", key="client_search")
    with f2:
        statuses = st.multiselect("Estatus", sorted(base["status"].dropna().unique()), key="client_statuses")
    with f3:
        channels = st.multiselect("Canales", sorted(base["channel"].dropna().unique()), key="client_channels")
    with f4:
        zones = st.multiselect("Zonas", sorted(base["zone"].dropna().unique()), key="client_zones")

    visible = queries.clients(
        supervisor_code=supervisor,
        statuses=statuses or None,
        channels=channels or None,
        zones=zones or None,
        search=search or None,
        db_path=DB_PATH,
    )
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("Clientes visibles", f"{len(visible):,}")
    c2.metric("Activados", f"{(visible['status'] == 'ACTIVADO').sum():,}" if not visible.empty else "0")
    c3.metric("No activados", f"{(visible['status'] == 'NO ACTIVADO').sum():,}" if not visible.empty else "0")
    c4.metric("Clientes nuevos", f"{safe_int(visible['is_new'].sum()) if not visible.empty else 0:,}")

    a, b, c = st.columns(3)
    with a:
        plot(charts.client_status_donut(visible), "clients_status")
    with b:
        plot(charts.channel_donut(visible), "clients_channel")
    with c:
        plot(charts.route_zone_bar(visible), "clients_zone")

    tab1, tab2 = st.tabs(["Maestro de clientes", "Cliente 360°"])
    with tab1:
        st.dataframe(
            visible[["client_code", "rif", "client", "channel", "state", "city", "zone", "advisor", "supervisor", "status", "is_new", "route_week", "route_day", "phone", "email", "source", "notes"]],
            hide_index=True,
            width="stretch",
            column_config={
                "client_code": "Código",
                "rif": "RIF",
                "client": "Cliente",
                "channel": "Canal",
                "state": "Estado",
                "city": "Ciudad",
                "zone": "Zona",
                "advisor": "Asesor",
                "supervisor": "Supervisor",
                "status": "Estatus",
                "is_new": st.column_config.CheckboxColumn("Nuevo"),
                "route_week": "Semana",
                "route_day": "Día",
                "phone": "Teléfono",
                "email": "Correo",
                "source": "Fuente",
                "notes": st.column_config.TextColumn("Notas", width="large"),
            },
        )
        st.download_button(
            "Descargar clientes filtrados (CSV)",
            visible.to_csv(index=False).encode("utf-8-sig"),
            file_name=f"clientes_filtrados_{period}.csv",
            mime="text/csv",
            width="stretch",
        )
    with tab2:
        if visible.empty:
            st.info("No hay resultados para seleccionar.")
        else:
            ids = visible["client_code"].astype(str).tolist()
            name_map = dict(zip(visible["client_code"].astype(str), visible["client"].astype(str)))
            selected = st.selectbox("Cliente", ids, format_func=lambda x: f"{name_map.get(x, x)} · {x}", key="client360_select")
            row = visible[visible["client_code"].astype(str) == selected].iloc[0]
            st.markdown(f"### {row['client']}")
            fcols = st.columns(5)
            fcols[0].metric("Código", row["client_code"])
            fcols[1].metric("Canal", row["channel"] or "Por clasificar")
            fcols[2].metric("Estatus", row["status"])
            fcols[3].metric("Asesor", row["advisor"])
            fcols[4].metric("Zona", row["zone"] or "Por definir")
            detail = [
                ("RIF", row.get("rif", "")),
                ("Estado / ciudad", f"{row.get('state', '')} · {row.get('city', '')}"),
                ("Ruta", f"Semana {row.get('route_week') or '-'} · {row.get('route_day') or '-'}"),
                ("Teléfono", row.get("phone", "")),
                ("Correo", row.get("email", "")),
                ("Fuente", row.get("source", "")),
                ("Notas", row.get("notes", "")),
                ("Dirección", row.get("address", "")),
            ]
            st.dataframe(pd.DataFrame(detail, columns=["Campo", "Valor"]), hide_index=True, width="stretch")
            history = queries.client_brand_history(selected, db_path=DB_PATH)
            if history.empty:
                callout(
                    "<b>Venta cruzada en espera de granularidad:</b> este cliente está correctamente indexado, pero los archivos actuales no contienen su historial por producto/marca. "
                    "Al cargar VENTAS_DIARIAS con código de cliente y producto, aparecerán marcas consumidas, categorías faltantes, última compra y prioridad de oportunidad.",
                    "medium",
                )
            else:
                st.markdown("#### Historial de marcas")
                st.dataframe(history, hide_index=True, width="stretch")
                bought = set(history["brand"].dropna().astype(str).str.upper())
                all_brands = queries.brand_performance(period, supervisor_code=supervisor, db_path=DB_PATH)
                available = set(all_brands["brand"].dropna().astype(str).str.upper())
                missing = sorted(available - bought)[:12]
                callout(f"<b>Marcas sin compra registrada:</b> {', '.join(missing) if missing else 'No detectadas'}.", "success")


# ---------------------------------------------------------------------
# Page 6: Routes / visits
# ---------------------------------------------------------------------


def page_routes(period: str, supervisor: str | None) -> None:
    hero(
        "Rutas, Visitas y Gestión de Campo",
        "Módulo operativo para que cada asesor registre desde el celular a quién atendió, qué resultado obtuvo, por qué no vendió, cuánto cobró y cuál es la próxima acción.",
        "Seguimiento diario",
        ["Formulario móvil", "Ruta planificada", "Visita vs. venta"],
    )
    catalog = queries.advisor_catalog(DB_PATH, supervisor_code=supervisor)
    catalog = catalog[catalog["advisor_code"] != "SIN-ASIGNAR"]
    if catalog.empty:
        st.warning("Primero debe registrar asesores.")
        return
    code_to_name = dict(zip(catalog["advisor_code"], catalog["name"]))
    tab1, tab2, tab3 = st.tabs(["Registrar visita", "Mi ruta / planificación", "Monitor diario"])

    with tab1:
        st.markdown("#### Nueva gestión de campo")
        advisor_code = st.selectbox("Asesor", catalog["advisor_code"].tolist(), format_func=lambda x: f"{x} · {code_to_name.get(x, x)}", key="visit_advisor")
        client_df = queries.clients(advisor_codes=[advisor_code], db_path=DB_PATH)
        if client_df.empty:
            client_df = queries.clients(supervisor_code=supervisor, db_path=DB_PATH)
            callout("El asesor aún no tiene cartera asociada; se muestran clientes de la estructura para facilitar el piloto.", "medium")
        client_map = dict(zip(client_df["client_code"].astype(str), client_df["client"].astype(str)))
        with st.form("visit_form", clear_on_submit=True):
            c1, c2 = st.columns(2)
            visit_date = c1.date_input("Fecha", value=date.today())
            client_code = c2.selectbox("Cliente", client_df["client_code"].astype(str).tolist(), format_func=lambda x: client_map.get(x, x)) if not client_df.empty else None
            result = st.selectbox(
                "Resultado",
                ["Venta realizada", "Pedido pendiente", "Cotización", "Cobranza", "No hubo venta", "Cliente cerrado", "Visita reprogramada"],
            )
            reason = st.selectbox(
                "Motivo / incidencia",
                ["", "Sin necesidad", "Problema de precio", "Sin inventario", "Bloqueado por CXC", "No estaba el encargado", "Competencia", "Fuera de ruta", "Otro"],
            )
            c3, c4 = st.columns(2)
            amount_reported = c3.number_input("Monto de pedido/venta reportado (USD)", min_value=0.0, step=10.0, format="%.2f")
            amount_collected = c4.number_input("Cobranza realizada (USD)", min_value=0.0, step=10.0, format="%.2f")
            next_action = st.text_input("Próxima acción", placeholder="Ej. enviar cotización de filtros")
            next_visit = st.date_input("Próxima visita", value=None)
            notes = st.text_area("Observaciones")
            submitted = st.form_submit_button("Guardar gestión", width="stretch")
        if submitted:
            if not client_code:
                st.error("Debe seleccionar un cliente.")
            else:
                database.insert_visit(
                    {
                        "visit_date": visit_date.isoformat(),
                        "advisor_code": advisor_code,
                        "client_code": client_code,
                        "result": result,
                        "reason": reason,
                        "amount_reported": amount_reported,
                        "amount_collected": amount_collected,
                        "next_action": next_action,
                        "next_visit_date": next_visit.isoformat() if next_visit else None,
                        "notes": notes,
                        "latitude": None,
                        "longitude": None,
                        "source": "FORMULARIO_APP",
                    },
                    db_path=DB_PATH,
                )
                st.success("Gestión guardada. El monitor diario se actualizó.")
                st.rerun()

    with tab2:
        advisor_code = st.selectbox("Asesor de ruta", catalog["advisor_code"].tolist(), format_func=lambda x: f"{x} · {code_to_name.get(x, x)}", key="route_advisor")
        route = queries.clients(advisor_codes=[advisor_code], db_path=DB_PATH)
        if route.empty:
            st.info("No hay clientes asignados a este asesor.")
        else:
            r1, r2 = st.columns(2)
            with r1:
                weeks = sorted([int(v) for v in route["route_week"].dropna().unique()])
                selected_weeks = st.multiselect("Semana de ruta", weeks, key="route_weeks")
            with r2:
                days = sorted(route["route_day"].dropna().astype(str).loc[lambda x: x != ""].unique())
                selected_days = st.multiselect("Día", days, key="route_days")
            if selected_weeks:
                route = route[route["route_week"].isin(selected_weeks)]
            if selected_days:
                route = route[route["route_day"].isin(selected_days)]
            plot(charts.channel_donut(route), "route_channels")
            st.dataframe(
                route[["route_week", "route_day", "client_code", "client", "channel", "zone", "status", "phone", "notes"]],
                hide_index=True,
                width="stretch",
                column_config={"route_week": "Semana", "route_day": "Día", "client_code": "Código", "client": "Cliente", "channel": "Canal", "zone": "Zona", "status": "Estatus", "phone": "Teléfono", "notes": st.column_config.TextColumn("Notas", width="large")},
            )

    with tab3:
        start = st.date_input("Desde", value=date.today().replace(day=1), key="visit_start")
        end = st.date_input("Hasta", value=date.today(), key="visit_end")
        vdf = queries.visits(start.isoformat(), end.isoformat(), supervisor_code=supervisor, db_path=DB_PATH)
        if vdf.empty:
            st.info("Aún no hay visitas registradas en este rango.")
        else:
            x1, x2, x3, x4 = st.columns(4)
            x1.metric("Visitas", f"{len(vdf):,}")
            x2.metric("Clientes únicos", f"{vdf['client_code'].nunique():,}")
            x3.metric("Monto reportado", money(vdf["amount_reported"].sum()))
            x4.metric("Cobranza", money(vdf["amount_collected"].sum()))
            a, b = st.columns(2)
            with a:
                plot(charts.visits_results(vdf), "visits_result")
            with b:
                by_advisor = vdf.groupby("advisor", as_index=False).agg(visitas=("visit_id", "count"), clientes=("client_code", "nunique"), monto=("amount_reported", "sum"))
                fig = px.bar(by_advisor.sort_values("visitas"), x="visitas", y="advisor", orientation="h", hover_data={"clientes": True, "monto": ":$,.2f"}, title="Gestiones por asesor")
                fig.update_layout(height=400, paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)", font_color=COLORS["white"])
                plot(fig, "visits_advisor")
            st.dataframe(vdf, hide_index=True, width="stretch")


