def _render_bundle(bundle: importers.ImportBundle, idx: int) -> None: # pyright: ignore[reportInvalidTypeForm] # type: ignore
    st.markdown(f"#### {bundle.filename}")
    st.caption(f"Tipo detectado: {bundle.detected_type} · SHA-256: {bundle.file_hash[:12]}…")
    if bundle.errors:
        for err in bundle.errors:
            st.error(err)
        return
    if bundle.warnings:
        for warning in bundle.warnings:
            st.warning(warning)
    st.dataframe(bundle.summary(), hide_index=True, width="stretch")
    tabs = st.tabs(list(bundle.frames.keys())) if bundle.frames else []
    for tab, (table, frame) in zip(tabs, bundle.frames.items()):
        with tab:
            st.dataframe(frame.head(100), hide_index=True, width="stretch")
            if len(frame) > 100:
                st.caption(f"Vista previa de 100 de {len(frame):,} filas.")
    if database.import_exists(bundle.file_hash, db_path=DB_PATH):
        st.info("Este archivo ya está registrado en el historial de importaciones; no se volverá a duplicar.")
    else:
        if st.button("Confirmar importación", key=f"commit_bundle_{idx}", width="stretch"):
            try:
                result = importers.commit_bundle(bundle, db_path=DB_PATH, user_name="Gerencia")
                st.success("Importación completada: " + ", ".join(f"{k}={v}" for k, v in result.items()))
                st.rerun()
            except Exception as exc:  # noqa: BLE001
                st.error(f"No fue posible confirmar la carga: {exc}")


