def page_reports(period: str, supervisor: str | None) -> None:
    hero("Entrega a supervisión", "Prepare el alcance una vez y genere cada formato cuando lo necesite.",
         "Reportes comerciales", [period_label(period), "Filtros verificables", "Cuatro formatos"])
    perf = queries.advisor_performance(period, supervisor_code=supervisor, db_path=DB_PATH)
    advisor_map = dict(zip(perf["advisor_code"], perf["advisor"])) if not perf.empty else {}
    f1, f2, f3 = st.columns(3)
    advisor_codes = f1.multiselect("Asesores", list(advisor_map), format_func=lambda x: advisor_map.get(x, x), key="report_advisors")
    states = f2.multiselect("Estados", sorted(perf["state"].dropna().unique()) if not perf.empty else [], key="report_states")
    zones = f3.multiselect("Zonas", sorted(perf["zone"].dropna().unique()) if not perf.empty else [], key="report_zones")
    i1, i2, i3, i4 = st.columns(4)
    include_clients = i1.checkbox("Incluir clientes", value=True, key="report_inc_clients")
    include_brands = i2.checkbox("Incluir marcas", value=True, key="report_inc_brands")
    include_cxc = i3.checkbox("Incluir CXC", value=True, key="report_inc_cxc")
    include_inventory = i4.checkbox("Inventario de empresa", value=True, key="report_inc_inventory")
    signature = _report_signature(period, supervisor, advisor_codes, states, zones,
        include_clients, include_brands, include_cxc, include_inventory, DB_PATH)
    saved = st.session_state.get("report_package_v2")
    if saved and saved.get("signature") != signature:
        st.session_state.pop("report_package_v2", None)
        saved = None
        st.info("Cambió el alcance o los datos guardados. Prepare de nuevo el reporte para descargar la versión actual.")
    prepare = st.button("Preparar datos del reporte", type="primary", width="stretch", key="prepare_reports")
    if prepare:
        with st.spinner("Preparando los datos del alcance seleccionado..."):
            data = reports.collect_report_data(period, supervisor_code=supervisor,
                advisor_codes=advisor_codes, states=states, zones=zones,
                include_clients=include_clients, include_brands=include_brands,
                include_cxc=include_cxc, include_inventory=include_inventory, db_path=DB_PATH)
            # Capture after collection; future writes invalidate all generated formats.
            saved = {"signature": _report_signature(period, supervisor, advisor_codes, states, zones,
                include_clients, include_brands, include_cxc, include_inventory, DB_PATH),
                "data": data, "formats": {}}
            st.session_state["report_package_v2"] = saved
        st.success("Datos preparados. Elija el formato que necesita.")
    if saved:
        data = saved["data"]
        a, b, c, d = st.columns(4)
        a.metric("Ventas del reporte", money(data.summary["sales"]))
        b.metric("Cuota", money(data.summary["quota"]))
        c.metric("Asesores", str(data.summary["advisors"]))
        d.metric("Clientes incluidos", f"{len(data.clients):,}")
        st.caption(data.filters_label)
        if data.daily_sales.attrs.get("excluded_currency_rows"):
            st.warning("Las ventas diarias muestran únicamente USD. Hay registros en otras monedas; se conservan en la base y no se convierten automáticamente.")
    else:
        st.info("Seleccione el alcance y prepare los datos. Todos los formatos estarán disponibles sin generar archivos que no necesite.")
    formats = [
        ("xlsx", "Excel ejecutivo", reports.build_excel_report, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"),
        ("pdf", "PDF gerencial", reports.build_pdf_report, "application/pdf"),
        ("zip", "CSV en ZIP", reports.build_csv_zip, "application/zip"),
        ("json", "JSON", reports.build_json_report, "application/json"),
    ]
    for column, (extension, label, builder, mime) in zip(st.columns(4), formats):
        with column:
            with st.container(border=True):
                st.markdown(f"**{label}**")
                if st.button(f"Generar {label}", disabled=not bool(saved), key=f"report_build_{extension}", width="stretch"):
                    try:
                        with st.spinner(f"Generando {label}..."):
                            saved["formats"][extension] = builder(saved["data"])
                    except Exception as exc:
                        st.error(f"No se pudo generar {label}: {exc}")
                if saved and extension in saved["formats"]:
                    st.download_button(f"Descargar {label}", saved["formats"][extension],
                        file_name=reports.report_filename("NEXUS_Comercial", saved["data"], extension),
                        mime=mime, key=f"report_download_{extension}", width="stretch")
    with st.expander("Qué recibe mi supervisora"):
        st.write("Excel: resumen, desempeño por asesor, marcas por dimensión, clientes, alertas y fuentes; "
                 "PDF: lectura gerencial y gráficas; CSV/JSON: datos para otros sistemas. "
                 "El resumen identifica la fuente oficial y la suma de asesores por separado.")
        st.caption("Inventario se adjunta como contexto de empresa. Las dimensiones de marca/departamento pueden solaparse y no deben sumarse como ventas adicionales.")


