def main() -> None:
    st.set_page_config(
        page_title=APP_NAME,
        page_icon="📊",
        layout="wide",
        initial_sidebar_state="expanded",
        menu_items={
            "Get help": None,
            "Report a bug": None,
            "About": f"{APP_NAME} - {APP_SUBTITLE}",
        },
    )
    if st.session_state.get("_commercial_initialized") != str(DB_PATH):
        init_database(seed=True)
        st.session_state["_commercial_initialized"] = str(DB_PATH)
    apply_theme()
    render_app()





