def plot(fig: go.Figure, key: str | None = None) -> None:
    # Work on a copy: changing UI colors must not mutate a report or cached figure.
    fig = go.Figure(fig)
    fig.update_layout(template="plotly_white", paper_bgcolor="#ffffff", plot_bgcolor="#ffffff",
        font=dict(color="#2e496a", family="Segoe UI, Arial, sans-serif", size=12),
        title_font=dict(color="#233d5b", size=16),
        hoverlabel=dict(bgcolor="#17365b", font_color="#ffffff"),
        legend=dict(font=dict(color="#617995", size=11), bgcolor="rgba(255,255,255,0)"),
        modebar=dict(bgcolor="rgba(255,255,255,.8)", color="#8ca0b9", activecolor="#2459dd"))
    fig.update_xaxes(tickfont=dict(color="#72859d", size=11), title_font=dict(color="#617995"),
                     linecolor="#e2e9f2", zerolinecolor="#e2e9f2", gridcolor="#edf1f7")
    fig.update_yaxes(tickfont=dict(color="#72859d", size=11), title_font=dict(color="#617995"),
                     linecolor="#e2e9f2", zerolinecolor="#e2e9f2", gridcolor="#edf1f7")
    if fig.layout.annotations:
        for annotation in fig.layout.annotations:
            annotation.font.color = "#617995"
    tone = {"#FFB703":"#2459dd", "#38BDF8":"#71a5ed", "#26C6A5":"#128d91",
            "#22C55E":"#15946d", "#F59E0B":"#d7a333", "#FB8500":"#d98237", "#EF4444":"#d9576c",
            "rgba(56,189,248,0.45)":"#d2e1fb", "#A78BFA":"#8b80cf"}
    def _tone(value):
        return tone.get(value, value) if isinstance(value, str) else value
    for trace in fig.data:
        if trace.type == "indicator":
            trace.number.font.color = "#233d5b"
            trace.title.font.color = "#607995"
            trace.gauge.bgcolor = "#f2f5f9"
            trace.gauge.bar.color = "#2459dd"
            trace.gauge.axis.tickcolor = "#8395ad"
            trace.gauge.axis.tickfont.color = "#72859d"
            trace.gauge.threshold.line.color = "#233d5b"
        if hasattr(trace, "marker") and hasattr(trace.marker, "color"):
            current = trace.marker.color
            if isinstance(current, str):
                trace.marker.color = _tone(current)
            elif isinstance(current, (list, tuple, np.ndarray)) and len(current) and isinstance(current[0], str):
                trace.marker.color = [_tone(v) for v in current]
        if trace.type == "pie" and trace.marker.colors:
            trace.marker.colors = [_tone(v) for v in trace.marker.colors]
            trace.textfont.color = "#385676"
            trace.textfont.size = 11
        if hasattr(trace, "line") and hasattr(trace.line, "color"):
            trace.line.color = _tone(trace.line.color)
    if fig.layout.polar:
        fig.update_polars(bgcolor="#f8faff", radialaxis=dict(color="#72859d", gridcolor="#dfe7f2"),
                          angularaxis=dict(color="#617995", gridcolor="#dfe7f2"))
    st.plotly_chart(fig, width="stretch",
        config={"displaylogo":False, "responsive":True, "scrollZoom":False,
                "toImageButtonOptions":{"format":"png", "scale":2}}, key=key)


