def sidebar() -> tuple[str, str, str | None]:
    with st.sidebar:
        st.markdown('<div class="nx-brand"><div class="nx-brand-mark">N</div><div>'
                    '<div class="nx-brand-title">nexus<span style="color:#2459dd">.</span></div>'
                    '<div class="nx-brand-sub">Makropetrol · Comercial</div></div></div>', unsafe_allow_html=True)
        periods = queries.available_periods(DB_PATH) or [datetime.now().strftime("%Y-%m")]
        if st.session_state.get("global_period") not in periods:
            st.session_state["global_period"] = periods[0]
        period = st.selectbox("Período de análisis", periods, format_func=period_label, key="global_period")
        sups = queries.supervisors(DB_PATH)
        codes, labels = _option_map(sups, "supervisor_code", "name")
        choices = ["TODOS"] + codes
        if st.session_state.get("global_supervisor") not in choices:
            st.session_state["global_supervisor"] = "TODOS"
        supervisor = st.selectbox("Equipo de supervisión", choices,
            format_func=lambda x: "Todos los equipos" if x == "TODOS" else labels.get(x, x), key="global_supervisor")
        st.markdown('<div class="nx-sidebar-label">Tu espacio de trabajo</div>', unsafe_allow_html=True)
        if st.session_state.get("global_page") not in NAV_ITEMS:
            st.session_state["global_page"] = "Centro de Comando"
        page = st.radio("Secciones", NAV_ITEMS, format_func=lambda p: _UI_NAV_LABELS[p],
                        label_visibility="collapsed", key="global_page")
        st.toggle("Modo presentación", key="ui_presentation_mode",
                  help="En Panorama comercial muestra la lectura ejecutiva y conserva las alertas. Desactívalo para explorar todas las gráficas del panorama.")
        st.markdown(f'<div class="nx-sidebar-foot">NEXUS COMERCIAL · {_ui_escape(APP_VERSION)}<br>'
                    'Ventas, clientes y metas.<br>Aplicación independiente del motor de inventario.</div>', unsafe_allow_html=True)
    return page, period, None if supervisor == "TODOS" else supervisor


def render_app() -> None:
    page, period, supervisor = sidebar()
    page_func = {
        "Centro de Comando": page_command_center, "Supervisores": page_supervisors,
        "Asesor 360°": page_advisor_360, "Marcas y Departamentos": page_brands,
        "Clientes y Venta Cruzada": page_clients, "Rutas y Visitas": page_routes,
        "Carga de Datos": page_upload, "Reportes Ejecutivos": page_reports,
        "Administración": page_admin,
        "Guía y presentación": page_guide,
    }
    page_func[page](period, supervisor)
    st.markdown(f'<div class="nx-footer"><span>NEXUS COMERCIAL · {_ui_escape(_UI_NAV_LABELS[page])}</span>'
                f'<span>{_ui_escape(period_label(period))} · Los resultados dependen de las fuentes cargadas</span></div>', unsafe_allow_html=True)


def _ui_home_quality(quality: pd.DataFrame) -> None:
    with st.expander(f"Revisar calidad de los datos · {len(quality)} pendientes", expanded=False):
        if quality.empty:
            st.success("No hay alertas pendientes registradas para este período.")
        else:
            columns = [c for c in ["severity","scope","title","detail","expected","observed","status"] if c in quality]
            st.dataframe(quality[columns], hide_index=True, width="stretch",
                column_config={"severity":"Severidad", "scope":"Alcance", "title":"Alerta",
                               "detail":st.column_config.TextColumn("Detalle", width="large"),
                               "expected":"Esperado", "observed":"Observado", "status":"Estado"})


def page_command_center(period: str, supervisor: str | None) -> None:
    summary, perf, official = _summary_values(period, supervisor)
    quality = queries.data_quality(period=period, status="PENDIENTE", db_path=DB_PATH)
    history = queries.monthly_history(supervisor_code=supervisor, db_path=DB_PATH)
