            if st.form_submit_button('Guardar seguimiento'):
                if not action.strip() or not owner.strip():st.error('Indica la acción y el responsable.')
                else:
                    import sqlite3
                    if due:
                        try:datetime.strptime(due,'%Y-%m-%d')
                        except ValueError:st.error('Fecha inválida. Usa AAAA-MM-DD.');return
                    payload=dict(advisor_code=code,advisor=r['advisor'],action=action,owner=owner,due=due,status=status)
                    with sqlite3.connect(str(DB_PATH)) as con:con.execute('INSERT INTO cv4_actions VALUES(?,?,?) ON CONFLICT(period,advisor_code) DO UPDATE SET payload=excluded.payload',(period,code,_cv4_json(payload)))
                    st.success('Seguimiento guardado; se incluye en los reportes del asesor.')


