@st.cache_data(show_spinner=False,max_entries=24)
def _cv4_parse_upload(raw,filename,kind,period):
    from pathlib import PurePath
    import zipfile,io
    ext=PurePath(filename).suffix.lower()
    if ext=='.zip':
        out=[];total=0
        with zipfile.ZipFile(io.BytesIO(raw)) as z:
            members=[m for m in z.infolist() if not m.is_dir() and not m.filename.startswith('__MACOSX/')]
            if len(members)>100:raise ValueError('Máximo 100 archivos por lote.')
            for m in members:
                if PurePath(m.filename).suffix.lower() not in {'.xlsx','.xlsm','.pdf'}:continue
                if m.file_size>30_000_000:raise ValueError('Un archivo supera 30 MB.')
                total+=m.file_size
                if total>150_000_000:raise ValueError('El lote expandido supera 150 MB.')
                out.extend(_cv4_parse_upload(z.read(m),PurePath(m.filename).name,kind,period))
        if not out:raise ValueError('El ZIP no contiene Excel XLSX ni PDF compatibles.')
        return out
    if ext=='.pdf':
        item=parse_advisor_followup_pdf_v4(raw,filename)
        if item.get('valid_for_import') is False:raise ValueError('El PDF no concilia: '+ '; '.join(str(i.get('message')) for i in item.get('issues',[]) if i.get('severity')=='error'))
        return [item]
    item=parse_commercial_workbook_v4(raw,filename,kind=kind,period_override=period or None)
    if not any(item.get(k) for k in ['advisor_rows','brand_rows','summary_rows']):raise ValueError('No se reconoció una matriz de cuotas o cierre en este Excel.')
    return [item]


def _cv4_review_sources():
    sources=commercial_sources_v4(DB_PATH,False)
    if not sources:st.info('Aún no hay archivos.');return
    keys=[x['_sha'] for x in sources];by={x['_sha']:x for x in sources}
    sha=st.selectbox('Archivo que deseas revisar',keys,format_func=lambda k:by[k]['metadata']['filename']+(' · referencia' if by[k]['_reference'] else '')+(' · desactivado' if not by[k]['_enabled'] else ''),key='cv4_source_review')
    item=by[sha];m=item['metadata'];res=dict(item.get('_resolution',{}))
    st.caption('La revisión afecta a esta fuente. No cambia el archivo original ni las asignaciones de otros meses.')
    original_rows=item.get('advisor_rows',[])
    if original_rows:
        cols=[c for c in ['advisor_code','advisor_name','supervisor_raw','period','period_confirmed','sales_target','sales_actual','source_sheet'] if c in pd.DataFrame(original_rows)]
        st.dataframe(pd.DataFrame(original_rows)[cols],hide_index=True,width='stretch')
    elif item.get('summary'):st.json(item['summary'],expanded=True)
    sheets=m.get('sheets',[])
    if sheets:
        edit_rows=[]
        for s in sheets:
            if s.get('classification') in {'empty','unknown'}:continue
            name=s['name'];printed=s.get('period') or m.get('period_suggested') or ''
            edit_rows.append({'Hoja':name,'Período leído':printed,'Período confirmado':res.get('sheet_periods',{}).get(name,''),'Supervisor confirmado':res.get('sheet_supervisors',{}).get(name,''),'Código asesor confirmado (hoja de marcas)':res.get('sheet_advisors',{}).get(name,'')})
        with st.form('cv4_sheet_review_'+sha):
            st.caption('Completa «Período confirmado» solo cuando hayas comprobado la fecha. Una hoja rotulada JULIO no se mueve automáticamente a SEPTIEMBRE. El supervisor por hoja permite resolver Barquisimeto sin reasignar todo el libro.')
            edits=st.data_editor(pd.DataFrame(edit_rows),disabled=['Hoja','Período leído'],hide_index=True,width='stretch',key='cv4_sheets_'+sha)
            enabled=st.checkbox('Usar esta fuente en los informes',item['_enabled'])
            if st.form_submit_button('Guardar revisión de hojas'):
                res['sheet_periods']={str(r['Hoja']):str(r['Período confirmado']).strip() for _,r in edits.iterrows() if pd.notna(r['Período confirmado']) and str(r['Período confirmado']).strip()}
                res['sheet_supervisors']={str(r['Hoja']):str(r['Supervisor confirmado']).strip() for _,r in edits.iterrows() if pd.notna(r['Supervisor confirmado']) and str(r['Supervisor confirmado']).strip()}
                res['sheet_advisors']={str(r['Hoja']):str(r['Código asesor confirmado (hoja de marcas)']).strip() for _,r in edits.iterrows() if pd.notna(r['Código asesor confirmado (hoja de marcas)']) and str(r['Código asesor confirmado (hoja de marcas)']).strip()}
                try:save_commercial_resolution_v4(sha,res,DB_PATH,enabled);st.success('Revisión guardada.');st.rerun()
                except ValueError as e:st.error(str(e))
        with st.expander('Corregir la identidad confirmada de un asesor en esta fuente'):
            with st.form('cv4_identity_excel_'+sha):
                code=st.text_input('Código del asesor tal como figura en la fuente')
                corrected=st.text_input('Nombre correcto verificado')
                if st.form_submit_button('Guardar nombre confirmado'):
                    known={str(r.get('advisor_code') or '') for r in original_rows}
                    if code.strip() not in known or not corrected.strip():st.error('Indica un código presente en esta fuente y el nombre verificado.')
                    else:
                        res.setdefault('advisor_names',{})[code.strip()]=corrected.strip()
                        save_commercial_resolution_v4(sha,res,DB_PATH,item['_enabled']);st.success('Identidad confirmada en esta fuente.');st.rerun()
    else:
        with st.form('cv4_pdf_identity_'+sha):
            name=st.text_input('Nombre del asesor (si ya está confirmado)',res.get('advisor_name',''))
            sup=st.text_input('Supervisor del período',res.get('supervisor',''))
            enabled=st.checkbox('Usar esta fuente en los informes',item['_enabled'])
            if st.form_submit_button('Guardar identificación'):
                res.update(advisor_name=name.strip(),supervisor=sup.strip())
                save_commercial_resolution_v4(sha,res,DB_PATH,enabled);st.success('Identificación guardada.');st.rerun()
    if item.get('issues'):
        with st.expander('Observaciones del archivo original'):st.dataframe(pd.DataFrame(item['issues']).astype(str),hide_index=True,width='stretch')


def page_upload(period,supervisor):
    _cv4_header('Tus reportes, en su lugar','Carga cuotas, cierres y seguimientos. Primero se revisan; después quedan disponibles para los informes.')
    route=st.radio('Qué necesitas hacer',['Cierres, metas y seguimiento','Revisar fuentes y asignaciones','Otras cargas existentes'],horizontal=True,key='cv4_upload_route')
    if route=='Otras cargas existentes':return _cv4_old_pages['page_upload'](period,supervisor)
    if route=='Revisar fuentes y asignaciones':return _cv4_review_sources()
    st.info('Los 12 Excel y el PDF 137 que compartiste ya vienen incorporados como referencia fechada. No necesitas volver a cargarlos.')
    with st.form('cv4_upload_form'):
        files=st.file_uploader('Suelta varios Excel, PDF o los ZIP recibidos',type=['xlsx','xlsm','pdf','zip'],accept_multiple_files=True)
        a,b=st.columns(2)
        typ=a.selectbox('Contenido',['Detectar','Metas / cuotas','Resultados / cierre'])
        override=b.text_input('Período de respaldo si falta el año · AAAA-MM',value=period,help='No reemplaza silenciosamente un mes distinto impreso en una hoja.')
        analyze=st.form_submit_button('Leer y revisar archivos',type='primary')
    if analyze:
        if not files:st.warning('Selecciona al menos un archivo.');return
        parsed=[];errors=[]
        with st.spinner('Leyendo matrices y conciliando el seguimiento…'):
            for f in files:
                try:parsed.extend(_cv4_parse_upload(f.getvalue(),f.name,{'Detectar':None,'Metas / cuotas':'metas','Resultados / cierre':'cierre'}[typ],override.strip()))
                except Exception as e:errors.append(f.name+': '+str(e))
        st.session_state['cv4_pending_upload']=parsed;st.session_state['cv4_upload_errors']=errors
    parsed=st.session_state.get('cv4_pending_upload',[])
    for err in st.session_state.get('cv4_upload_errors',[]):st.error(err)
    if parsed:
        records=[]
        for x in parsed:
            m=x['metadata'];records.append({'Archivo':m['filename'],'Tipo':m.get('kind') or 'Seguimiento PDF','Período':m.get('period_suggested') or str(m.get('period_start',''))[:7],'Asesores':len(x.get('advisor_rows',[])) or (1 if 'vendor_code' in m else 0),'Marcas':len(x.get('brand_rows',[])),'Observaciones':len(x.get('issues',[]))})
        st.dataframe(pd.DataFrame(records),hide_index=True,width='stretch')
        st.caption('Las fechas dudosas quedan pendientes de revisión. Los archivos repetidos se reconocen por contenido y no duplican importes.')
        if st.button('Guardar archivos leídos',type='primary'):
            count=save_commercial_sources_v4(parsed,DB_PATH)
            st.session_state.pop('cv4_pending_upload',None)
            st.success(f'{count} archivos nuevos guardados. Elige su período y abre Reportes Ejecutivos; revisa las asignaciones pendientes antes de entregar.')
    with st.expander('Archivos incorporados'):
        st.dataframe(pd.DataFrame([{'Archivo':x['metadata']['filename'],'Referencia':x['_reference'],'Período':x['metadata'].get('period_suggested') or str(x['metadata'].get('period_start',''))[:7]} for x in _cv4_sources()]),hide_index=True,width='stretch')


def page_reports(period,supervisor):
    _cv4_header('Un informe listo para conversar','Prepara el seguimiento del equipo o de un asesor, con resultados, gráficos y acciones.')
    route=st.radio('Informe',['Seguimiento de asesores · PDF y Excel','Otros reportes existentes'],horizontal=True,key='cv4_report_route')
    if route=='Otros reportes existentes' or not _cv4_scope_exists(period):
        st.caption('Estas plantillas usan las cargas y fuentes transaccionales anteriores. Los nuevos cierres, cuotas y PDF se descargan en Seguimiento de asesores.')
        return _cv4_old_pages['page_reports'](period,supervisor)
    d=_cv4_data(period,supervisor)
    if not d['advisors']:return _cv4_table([])
    lookup={r['advisor_code']:r for r in d['advisors']}
    selected=st.multiselect('Asesores incluidos',list(lookup),default=list(lookup),format_func=lambda c:c+' · '+lookup[c]['advisor'],key='cv4_report_advisors_'+period+'_'+str(supervisor))
    if not selected:st.info('Selecciona al menos un asesor para preparar el informe.');return
    include_clients=st.checkbox('Incluir anexo de clientes en el PDF',False)
    ctx=commercial_report_context_v4(d,supervisor_label=_cv4_label_supervisor(supervisor,d['advisors']),advisor_codes=selected,actions=_cv4_actions(period))
    st.caption('El PDF incluye resumen y gráficos; el Excel conserva el detalle y las fórmulas de cumplimiento. Las comisiones son estimaciones solo si existe una regla registrada.')
    _cv4_table([lookup[x] for x in selected])
    if ctx.get('issues'):
        with st.expander('Revisiones que acompañarán al informe'):st.dataframe(pd.DataFrame({'Observación':ctx['issues']}),hide_index=True,width='stretch')
    import hashlib
    signature=hashlib.sha256((_cv4_json(ctx)+str(include_clients)).encode()).hexdigest()
    if st.button('Preparar PDF y Excel',type='primary'):
        with st.spinner('Diseñando el informe con los datos seleccionados…'):
            try:
                st.session_state['cv4_export_ready']={'signature':signature,'pdf':build_followup_pdf_v4(ctx,include_clients),'xlsx':build_followup_excel_v4(ctx)}
            except Exception as e:st.error('No se pudo generar el informe: '+str(e))
    ready=st.session_state.get('cv4_export_ready',{})
    if ready.get('signature')==signature:
        a,b=st.columns(2);stem='NEXUS_seguimiento_'+period+'_'+('equipo' if len(selected)>1 else selected[0])
        a.download_button('Descargar informe PDF',ready['pdf'],stem+'.pdf','application/pdf',width='stretch')
        b.download_button('Descargar planilla Excel',ready['xlsx'],stem+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',width='stretch')
        st.success('Informe preparado. Se genera de nuevo únicamente si cambias los datos o la selección.')


def page_admin(period,supervisor):
    route=st.radio('Configuración',['Equipo vigente','Comisiones','Administración existente'],horizontal=True,key='cv4_admin_route')
    if route=='Administración existente':return _cv4_old_pages['page_admin'](period,supervisor)
    if route=='Equipo vigente':
        _cv4_header('Cinco supervisores, una estructura vigente','El histórico conserva sus responsables. Registra aquí la nómina actual cuando esté confirmada.')
        st.info('Agosto menciona seis supervisores y Televentas. Los archivos de septiembre mencionan Jorge, Johana, José, Jonathan y Daniel; Barquisimeto tiene el gerente vacío. Se necesita confirmar la estructura vigente.')
        current=_cv4_preference('active_supervisors',[])
        with st.form('cv4_roster'):
            names=st.text_area('Nombres completos vigentes · uno por línea','\n'.join(current))
            reference=st.text_input('Referencia de la confirmación (responsable / fecha)',_cv4_preference('roster_reference',''))
            if st.form_submit_button('Guardar los cinco supervisores'):
                chosen=list(dict.fromkeys(s.strip() for s in names.splitlines() if s.strip()))
                if len(chosen)!=5 or not reference.strip():st.error('Registra cinco nombres distintos y la referencia de confirmación.')
                else:_cv4_set_preference('active_supervisors',chosen);_cv4_set_preference('roster_reference',reference.strip());st.success('Estructura vigente guardada. En Carga de Datos puedes confirmar el supervisor de cada hoja.')
        st.caption('La nómina vigente no cambia quién supervisaba a cada asesor en los reportes históricos.')
    else:
        _cv4_header('Comisiones con una regla explícita','Registra una política autorizada para el período. Los archivos recibidos no incluyen tasas ni condiciones de liquidación.')
        d=_cv4_data(period);labels={r['supervisor_code']:r['supervisor'] for r in d['advisors']}
        target=st.selectbox('Aplicar al equipo',['TODOS']+sorted(labels),format_func=lambda c:'Todos los equipos del período' if c=='TODOS' else labels[c],key='cv4_rule_sup')
        rule=commercial_rules_v4(period,DB_PATH).get(target,{})
        with st.form('cv4_commission'):
            ref=st.text_input('Nombre / referencia de la política',rule.get('document_reference',''))
            basis=st.selectbox('Base',['Ventas netas informadas','Cobros informados'],index=1 if rule.get('basis')=='collections' else 0)
            a,b=st.columns(2);rate=a.number_input('Comisión sobre la base · %',0.0,100.0,float(rule.get('rate',0))*100,step=.1)
            bonus=b.number_input('Bono adicional si venta alcanza 100% de la meta · %',0.0,100.0,float(rule.get('bonus_rate',0))*100,step=.1)
            confirmed=st.checkbox('Confirmo que esta base y estas tasas corresponden a la política autorizada del período',False)
            st.caption('Este modelo admite una tasa y un bono por cumplimiento de venta. Escalas, devoluciones especiales, impuestos y bonos por otros indicadores requieren definir su regla antes de liquidar.')
            if st.form_submit_button('Guardar política para '+period):
                try:
                    save_commercial_rule_v4(period,target,dict(document_reference=ref.strip(),basis='collections' if basis=='Cobros informados' else 'sales_actual',rate=rate/100,bonus_rate=bonus/100,confirmed=confirmed),DB_PATH)
                    st.success('Política registrada. Las estimaciones aparecen en Asesor 360° y en los reportes.')
                except ValueError as e:st.error(str(e))
        _cv4_table(_cv4_data(period,supervisor)['advisors'],['advisor_code','advisor','supervisor','commission_estimate','commission_note'])


def page_guide(period,supervisor):
    _cv4_header('Aprende el recorrido en cinco pasos','Puedes preparar una presentación corta siguiendo esta misma secuencia.')
    steps=[('1 · Carga','En Carga de Datos → Cierres, metas y seguimiento, sube los Excel de cuotas/cierre o el PDF de seguimiento. Los archivos que compartiste ya vienen como referencia.'),('2 · Revisión','En Revisar fuentes y asignaciones confirma hojas con fechas dudosas o supervisores sin nombre. Una cuota no se convierte en una venta realizada.'),('3 · Seguimiento','Elige el período y equipo en el menú lateral. Abre Supervisores o Asesor 360° para revisar ventas, cuota, activación, nuevos y marcas. N/D significa que falta información.'),('4 · Informe','En Reportes Ejecutivos elige los asesores y pulsa Preparar PDF y Excel. Descarga el resumen con gráficos y el detalle. Revisa las observaciones antes de entregarlo.'),('5 · Acción','En Asesor 360° → Plan de acción registra la tarea, responsable y fecha. La siguiente conversación con el supervisor puede partir de ese compromiso.')]
    if 'cv4_guide_step' not in st.session_state:st.session_state['cv4_guide_step']=0
    index=st.session_state['cv4_guide_step'];st.progress((index+1)/len(steps));st.subheader(steps[index][0]);st.write(steps[index][1])
    a,b=st.columns(2)
    if a.button('Anterior',disabled=index==0):st.session_state['cv4_guide_step']=index-1;st.rerun()
    if b.button('Siguiente',disabled=index==len(steps)-1):st.session_state['cv4_guide_step']=index+1;st.rerun()
    with st.expander('Cómo explicar los indicadores'):
        st.markdown('**Cumplimiento de venta:** venta del período ÷ meta del mismo período. **Activación:** clientes activados ÷ cartera válida. **Nuevos:** clientes incorporados; pueden estar incluidos en los activados. **Marcas:** conteo informado por el supervisor, separado del detalle de cuota por marca. **Comisión:** estimación sujeta a la política registrada. **Avance parcial:** corte antes de cerrar el mes.')
        st.write('En el PDF 137, el 0,70% impreso no es cumplimiento de meta. El reporte informa 6.221,27 USD de venta y 14 activados sobre 52 clientes; no informa una cuota ni una regla de comisión.')
    with st.expander('Guía completa de las herramientas anteriores'):_cv4_old_pages['page_guide'](period,supervisor)


