# NEXUS 5: importación de cortes digitales SmartTools, uno o varios asesores.
def nx5_parse_followup_pdf(raw: bytes, filename='seguimiento_vendedores.pdf'):
    import calendar
    import hashlib
    import io
    import re
    import unicodedata
    from datetime import datetime
    from decimal import Decimal
    import pdfplumber

    def normal(value):
        return ''.join(c for c in unicodedata.normalize('NFKD', str(value or '')) if not unicodedata.combining(c)).upper()

    def number(value):
        text = str(value).strip().replace(' ', '').replace('$', '').replace('%', '')
        if ',' in text:
            text = text.replace('.', '').replace(',', '.')
        elif re.fullmatch(r'[+-]?\d{1,3}(?:\.\d{3})+', text):
            text = text.replace('.', '')
        result = Decimal(text)
        if not result.is_finite():
            raise ValueError('El reporte contiene un número no finito.')
        return float(result)

    def dnum(value):
        return Decimal(str(value or 0))

    def issue(target, severity, code, message, **detail):
        row = {'severity': severity, 'code': code, 'message': message, **detail}
        if not any(r['code'] == code and r['message'] == message for r in target):
            target.append(row)

    def group_lines(words):
        output = []
        for word in sorted(words, key=lambda w: (w['top'], w['x0'])):
            match = next((line for line in reversed(output[-4:]) if abs(line['top'] - word['top']) <= 1.5), None)
            if match is None:
                match = {'top': word['top'], 'bottom': word['bottom'], 'words': []}
                output.append(match)
            match['words'].append(word)
            match['bottom'] = max(match['bottom'], word['bottom'])
        for line in output:
            line['words'].sort(key=lambda w: w['x0'])
            line['text'] = ' '.join(w['text'] for w in line['words'])
        return sorted(output, key=lambda line: line['top'])

    def kind_of(text):
        text = normal(text)
        if re.match(r'^CLIENTES\s+NO\s+ACTIVADOS', text): return 'clients_inactive'
        if re.match(r'^CLIENTES\s+ACTIVADOS', text): return 'clients_activated'
        if re.match(r'^CLIENTES\s+NUEVOS', text): return 'clients_new'
        if re.match(r'^VENTA\s+POR\s+DEPARTAMENTO', text): return 'departments'
        if re.match(r'^VENTA\s+POR\s+MARCA', text): return 'brands'
        if re.match(r'^VENTA\s+POR\s+CATEGORIA', text): return 'categories'
        return None

    if not isinstance(raw, (bytes, bytearray)) or not bytes(raw).startswith(b'%PDF'):
        raise ValueError('Selecciona un PDF digital de Seguimiento Equipo de Ventas.')
    raw = bytes(raw)
    document = {'metadata': {}, 'advisors': [], 'issues': []}
    labels = {'clients_activated': 'Clientes activados', 'clients_inactive': 'Clientes no activados', 'clients_new': 'Clientes nuevos', 'departments': 'departamentos', 'brands': 'marcas', 'categories': 'categorías'}
    numeric = r'([+-]?[\d.,]+)'
    summary_re = re.compile(r'^(.*?)\s+(\d+)\s+(\d+)\s*\(\s*' + numeric + r'\s*%\s*\)\s+(\d+)\s+(\d+)\s+(\d+)\s+' + numeric + r'\s+' + numeric + r'\s+' + numeric + r'\s*$')
    current = None
    section = None
    columns_current = {}

    def process_client_segment(page, lines, active_kind):
        nonlocal columns_current
        ncols = 2 if active_kind == 'clients_inactive' else 4
        # SmartTools numbers are right-aligned. Anchor their right edges, so 1/10/100
        # and continuation pages are read without mistaking address numbers for IDs.
        scale = float(page.width) / 612.0
        anchors = ([47.6844, 332.6844] if ncols == 2 else [43.1844, 186.0544, 328.9344, 471.8044])
        anchors = [a * scale for a in anchors]
        boundaries = [0.0] + [a - 11 * scale for a in anchors[1:]] + [page.width]
        for col in range(ncols):
            for line in lines:
                words = [w for w in line['words'] if boundaries[col] <= w['x0'] < boundaries[col + 1]]
                if not words:
                    continue
                text = ' '.join(w['text'] for w in words).strip()
                if not text:
                    continue
                first = words[0]
                merged = re.fullmatch(r'(\d{1,4})([^\d\s].*)', first['text'])
                is_starter = bool(re.fullmatch(r'\d{1,4}', first['text']) and abs(first['x1'] - anchors[col]) < 3.5 * scale)
                merged_starter = bool(merged and abs(first['x0'] + len(merged.group(1)) * 2.7244 * scale - (anchors[col] + (3 * scale if active_kind == 'clients_new' else 0))) < 3 * scale)
                if is_starter or merged_starter:
                    ordinal = int(merged.group(1) if merged_starter else first['text'])
                    name_text = ' '.join(([merged.group(2)] if merged_starter else []) + [w['text'] for w in words[1:]]).strip()
                    if not name_text:
                        continue
                    record = {'name': name_text, 'raw': name_text, 'source_number': ordinal, 'source_page': page.page_number,
                              'phone': None, 'address': None, 'identity_status': 'name_only'}
                    current[active_kind].append(record)
                    columns_current[col] = record
                elif col in columns_current:
                    record = columns_current[col]
                    record['raw'] += ' ' + text
                    record['name'] = record['raw']
                else:
                    issue(current['issues'], 'warning', 'client_continuation_unattached',
                          f'Texto de cliente sin inicio reconocido en página {page.page_number}; revisar PDF original.', source_page=page.page_number)

    def process_breakdown_segment(page, lines, active_kind):
        for line in lines:
            text = normal(line['text'])
            if 'TOTAL UNIDADES VENDIDAS' in text:
                m = re.search(r'TOTAL\s+UNIDADES\s+VENDIDAS\s*:?\s*([+-]?[\d.,]+)\s+([+-]?[\d.,]+)\s*$', text)
                if m:
                    total = {'units': number(m.group(1)), 'amount': number(m.group(2)), 'source_page': page.page_number}
                    old = current['printed_totals'].get(active_kind)
                    if old and (old['units'] != total['units'] or old['amount'] != total['amount']):
                        issue(current['issues'], 'warning', active_kind + '_repeated_total',
                              f'Hay dos totales impresos diferentes de {labels[active_kind]}; revisar página {page.page_number}.', source_page=page.page_number)
                    current['printed_totals'][active_kind] = total
                continue
            for col in range(2):
                left, right = page.width * col / 2, page.width * (col + 1) / 2
                words = [w for w in line['words'] if left <= w['x0'] < right]
                cell = ' '.join(w['text'] for w in words).strip()
                if not cell:
                    continue
                if re.search(r'\b(?:MONTO|UNDS|UNIDADES|DEPARTAMENTO|CATEGORIA|MARCA)\b', normal(cell)):
                    continue
                m = re.fullmatch(r'(?:(.*?)\s+)?([+-]?[\d.,]+)\s+([+-]?[\d.,]+)', cell)
                if not m:
                    issue(current['issues'], 'warning', active_kind + '_unparsed_row',
                          f'Fila de {labels[active_kind]} sin estructura numérica reconocible en página {page.page_number}: {cell[:100]}', source_page=page.page_number)
                    continue
                label = (m.group(1) or '').strip()
                code = None
                name = label or None
                if active_kind == 'departments':
                    split = re.fullmatch(r'(\S+)\s*-\s*(.+)', label)
                    if split:
                        code, name = split.groups()
                elif active_kind == 'categories':
                    code, name = label or None, None
                current[active_kind].append({'code': code, 'name': name, 'units': number(m.group(2)),
                                            'amount': number(m.group(3)), 'source_page': page.page_number, 'raw': cell})

    with pdfplumber.open(io.BytesIO(raw)) as doc:
        if not doc.pages:
            raise ValueError('El PDF está vacío.')
        metadata = {'filename': str(filename), 'sha256': hashlib.sha256(raw).hexdigest(), 'page_count': len(doc.pages),
                    'source_type': 'smarttools_sales_followup', 'currency': 'USD', 'period': None,
                    'start_date': None, 'end_date': None, 'generated_date': None, 'is_partial_period': False}
        document['metadata'] = metadata
        recognized_title = False
        periods = set()
        for page in doc.pages:
            words = page.extract_words()
            lines = group_lines(words)
            page_text = '\n'.join(line['text'] for line in lines)
            if 'SEGUIMIENTO EQUIPO DE VENTAS' in normal(page_text):
                recognized_title = True
            date_match = re.search(r'Fecha:\s*(\d{1,2}/\d{1,2}/\d{4})', page_text, re.I)
            if date_match and not metadata['generated_date']:
                metadata['generated_date'] = datetime.strptime(date_match.group(1), '%d/%m/%Y').date().isoformat()
            period_match = re.search(r'Desde:\s*(\d{1,2}/\d{1,2}/\d{4})\s+Hasta:\s*(\d{1,2}/\d{1,2}/\d{4})', page_text, re.I)
            if period_match:
                start, end = [datetime.strptime(x, '%d/%m/%Y').date() for x in period_match.groups()]
                periods.add((start.isoformat(), end.isoformat()))
                if start > end:
                    raise ValueError('El período Desde/Hasta está invertido.')
                if start.month != end.month or start.year != end.year:
                    raise ValueError('El seguimiento debe corresponder a un único mes para evitar mezclar sus cuotas. Exporta un mes por reporte.')
                metadata.update(period=start.strftime('%Y-%m'), start_date=start.isoformat(), end_date=end.isoformat(),
                                is_partial_period=start.day != 1 or end.day != calendar.monthrange(end.year, end.month)[1])
            body_top = next((line['bottom'] + 1 for line in lines if 'Ordenado por:' in line['text']), page.height * .15)
            body = [line for line in lines if line['top'] > body_top]
            # A fresh seller page repeats the summary column labels before its row;
            # they are not continuation data belonging to the previous seller.
            first_summary = next((line for line in body if summary_re.fullmatch(line['text'])), None)
            if first_summary is not None:
                first_section = next((line for line in body if kind_of(line['text'])), None)
                if first_section is None or first_summary['top'] < first_section['top']:
                    body = [line for line in body if line['top'] >= first_summary['top']]
            segment = []
            for line in body:
                summary = summary_re.fullmatch(line['text'])
                new_kind = kind_of(line['text'])
                if summary or new_kind:
                    if current and section and segment:
                        if section.startswith('clients_'):
                            process_client_segment(page, segment, section)
                        else:
                            process_breakdown_segment(page, segment, section)
                    segment = []
                    if summary:
                        prefix, portfolio, activated, rate, trans, fac, nc, sales, share, collected = summary.groups()
                        prefix = re.sub(r'^-\s*', '', prefix).strip()
                        parts = re.split(r'\s+-\s+', prefix, maxsplit=1)
                        code = parts[0].strip()
                        if not code:
                            raise ValueError(f'Falta el código del vendedor en página {page.page_number}.')
                        current = {'advisor_code': code, 'advisor_alias': parts[1].strip() if len(parts) > 1 else None,
                                   'label': prefix, 'portfolio': int(portfolio), 'activated_reported': int(activated),
                                   'activation_pct_reported': number(rate), 'transactions': int(trans), 'invoices': int(fac),
                                   'credit_notes': int(nc), 'sales_reported': number(sales), 'sales_share_reported': number(share),
                                   'collections': number(collected), 'source_page': page.page_number,
                                   'clients_activated': [], 'clients_inactive': [], 'clients_new': [],
                                   'departments': [], 'brands': [], 'categories': [], 'printed_totals': {}, 'section_counts': {}, 'issues': []}
                        document['advisors'].append(current)
                        section = None
                        columns_current = {}
                    elif current:
                        section = new_kind
                        columns_current = {}
                        if section.startswith('clients_'):
                            count_match = re.search(r'\((\d+)\)', line['text'])
                            if count_match:
                                current['section_counts'][section] = int(count_match.group(1))
                else:
                    segment.append(line)
            if current and section and segment:
                if section.startswith('clients_'):
                    process_client_segment(page, segment, section)
                else:
                    process_breakdown_segment(page, segment, section)
            page.flush_cache()
        if not recognized_title:
            raise ValueError('El PDF no es «Seguimiento Equipo de Ventas» de SmartTools.')
        if not metadata['period']:
            raise ValueError('No se encontraron las fechas Desde/Hasta del reporte.')
        if len(periods) > 1:
            raise ValueError('Las páginas contienen cortes de fechas diferentes. Carga cada reporte por separado.')
        if not document['advisors']:
            raise ValueError('No se encontró ninguna cabecera de vendedor legible. Carga el PDF digital original.')

    codes = set()
    for advisor in document['advisors']:
        code = advisor['advisor_code']
        if code in codes:
            raise ValueError(f'El código {code} tiene más de una cabecera. Revisa el PDF antes de importar para no duplicar ventas.')
        codes.add(code)
        if advisor['invoices'] + advisor['credit_notes'] != advisor['transactions']:
            issue(advisor['issues'], 'warning', 'transaction_count', 'FAC + NC no coincide con el total de transacciones.')
        if advisor['activated_reported'] > advisor['portfolio']:
            issue(advisor['issues'], 'warning', 'activation_exceeds_portfolio', 'El reporte muestra más clientes activados que clientes en cartera.')
        if not advisor['portfolio'] and advisor['activated_reported']:
            issue(advisor['issues'], 'warning', 'activation_without_portfolio', 'Hay activados con cartera cero; el porcentaje impreso no permite evaluar el avance.')
        for key in ('clients_activated', 'clients_inactive', 'clients_new'):
            rows = advisor[key]
            rows.sort(key=lambda r: (r['source_number'], r['source_page']))
            for record in rows:
                raw_text = record['raw']
                phone_match = re.search(r'\s+TLF\.?\s*([+\d() -]+)(.*)$', raw_text)
                if phone_match:
                    record['name'] = raw_text[:phone_match.start()].strip()
                    record['phone'] = phone_match.group(1).strip() or None
                    record['address'] = phone_match.group(2).strip() or None
                else:
                    record['name'] = raw_text.strip()
            reported = advisor['section_counts'].get(key)
            if reported is not None and len(rows) != reported:
                issue(advisor['issues'], 'warning', key + '_count_mismatch',
                      f'{labels[key]}: el encabezado imprime {reported}, pero se leyeron {len(rows)} filas. Se conservan todas para revisión.',
                      reported=reported, extracted=len(rows))
            ordinals = [r['source_number'] for r in rows]
            if len(ordinals) != len(set(ordinals)):
                issue(advisor['issues'], 'warning', key + '_duplicate_ordinal', 'La lista repite números de fila; verificar el documento original.')
        for kind in ('departments', 'brands', 'categories'):
            total = advisor['printed_totals'].get(kind)
            rows = advisor[kind]
            if not total:
                if rows:
                    issue(advisor['issues'], 'warning', kind + '_total_missing', f'El desglose de {labels[kind]} no tiene total impreso reconocido.')
                continue
            diff = dnum(advisor['sales_reported']) - dnum(total['amount'])
            if diff != 0:
                issue(advisor['issues'], 'warning', kind + '_header_difference',
                      f'Ventas de cabecera USD {advisor["sales_reported"]:,.2f}; total de {labels[kind]} USD {total["amount"]:,.2f}; diferencia USD {float(diff):,.2f}.',
                      summary_amount=advisor['sales_reported'], breakdown_amount=total['amount'], difference=float(diff), source_page=total['source_page'])
            detail_amount = sum((dnum(r['amount']) for r in rows), Decimal(0))
            detail_units = sum((dnum(r['units']) for r in rows), Decimal(0))
            if abs(detail_amount - dnum(total['amount'])) > Decimal('.01'):
                issue(advisor['issues'], 'warning', kind + '_detail_amount_difference',
                      f'Los renglones de {labels[kind]} suman USD {float(detail_amount):,.2f}; el total impreso es USD {total["amount"]:,.2f}.',
                      detail_amount=float(detail_amount), printed_amount=total['amount'], difference=float(detail_amount - dnum(total['amount'])))
            if abs(detail_units - dnum(total['units'])) > Decimal('.0001'):
                issue(advisor['issues'], 'warning', kind + '_detail_units_difference',
                      f'Las unidades de {labels[kind]} no coinciden con su total impreso.', detail_units=float(detail_units), printed_units=total['units'])
        advisor['sales_breakdown'] = next((advisor['printed_totals'][k]['amount'] for k in ('departments', 'brands', 'categories') if k in advisor['printed_totals']), None)
        advisor['sales_difference'] = round(advisor['sales_reported'] - advisor['sales_breakdown'], 2) if advisor['sales_breakdown'] is not None else None
        advisor['new_reported'] = advisor['section_counts'].get('clients_new')
        advisor['new_count_available'] = 'clients_new' in advisor['section_counts']
        advisor['inactive_reported'] = advisor['section_counts'].get('clients_inactive')
    issue(document['issues'], 'info', 'client_classification_source',
          'Nuevos y activados son clasificaciones del programa que pueden solaparse. No se suman. Este reporte no acredita primera compra, recuperación tras 30 días ni compra superior a USD 100 por cliente.')
    issue(document['issues'], 'info', 'external_targets',
          'Las cuotas, los nombres completos y la asignación a supervisores se configuran por asesor y período; el % VENTAS impreso es participación, no cumplimiento.')
    if document['metadata']['is_partial_period']:
        issue(document['issues'], 'info', 'partial_period', 'El reporte cubre un corte parcial del mes. Sus resultados deben mostrarse como avance, no cierre completo.')
    return document


# Seguimiento comercial v5: cortes, equipo y metas separados de las fuentes originales.
from contextlib import contextmanager as _nx5_contextmanager


@_nx5_contextmanager
def nx5_connection(db_path=None):
    con=sqlite3.connect(str(db_path or DB_PATH),timeout=30)
    try:
        con.execute('PRAGMA busy_timeout=30000')
        yield con
        con.commit()
    except BaseException:
        con.rollback()
        raise
    finally:
        con.close()


def nx5_now():
    from datetime import datetime, timezone, timedelta
    return datetime.now(timezone(timedelta(hours=-4))).isoformat(timespec='seconds')


def nx5_json(value):
    return json.dumps(value, ensure_ascii=False, allow_nan=False, default=str)


def nx5_init(db_path=None):
    path = str(db_path or DB_PATH)
    with nx5_connection(path) as con:
        con.executescript('''
        CREATE TABLE IF NOT EXISTS nx5_sources(sha TEXT PRIMARY KEY, period TEXT NOT NULL,
          filename TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS nx5_active(period TEXT NOT NULL, advisor_code TEXT NOT NULL,
          sha TEXT NOT NULL, PRIMARY KEY(period,advisor_code));
        CREATE TABLE IF NOT EXISTS nx5_roster(period TEXT NOT NULL, advisor_code TEXT NOT NULL,
          payload TEXT NOT NULL, PRIMARY KEY(period,advisor_code));
        CREATE TABLE IF NOT EXISTS nx5_goals(period TEXT NOT NULL, advisor_code TEXT NOT NULL,
          payload TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(period,advisor_code));
        CREATE TABLE IF NOT EXISTS nx5_line_goals(period TEXT NOT NULL,advisor_code TEXT NOT NULL,
          dimension TEXT NOT NULL,line_key TEXT NOT NULL,payload TEXT NOT NULL,
          PRIMARY KEY(period,advisor_code,dimension,line_key));
        CREATE TABLE IF NOT EXISTS nx5_actions(period TEXT NOT NULL,advisor_code TEXT NOT NULL,
          payload TEXT NOT NULL,PRIMARY KEY(period,advisor_code));
        CREATE TABLE IF NOT EXISTS nx5_preferences(key TEXT PRIMARY KEY,payload TEXT NOT NULL);
        ''')


def nx5_pref(key, default=None, db_path=None):
    with nx5_connection(str(db_path or DB_PATH)) as con:
        r = con.execute('SELECT payload FROM nx5_preferences WHERE key=?',(key,)).fetchone()
    return json.loads(r[0]) if r else default


def nx5_set_pref(key, value, db_path=None):
    with nx5_connection(str(db_path or DB_PATH)) as con:
        con.execute('INSERT INTO nx5_preferences VALUES(?,?) ON CONFLICT(key) DO UPDATE SET payload=excluded.payload',(key,nx5_json(value)))


def nx5_number(value):
    if value is None or isinstance(value, bool): return None
    if isinstance(value, str):
        value=value.strip().replace('$','').replace('%','').replace(' ','')
        if not value: return None
        if ',' in value: value=value.replace('.','').replace(',','.')
    try:
        val=float(value)
        return val if math.isfinite(val) else None
    except (TypeError,ValueError): return None


def nx5_clean_text(value):
    if value is None: return ''
    if isinstance(value, float) and math.isnan(value): return ''
    return str(value).strip()


def nx5_code(value):
    s=nx5_clean_text(value)
    if re.fullmatch(r'\d+\.0',s):s=s[:-2]
    return s.upper()


def nx5_key(value):
    return re.sub(r'[^A-Z0-9]','',normalize_text(str(value or '')).upper())


def nx5_issue(message,code='review',page=None,advisor_code=None,severity='warning'):
    return dict(message=message,code=code,source_page=page,advisor_code=advisor_code,severity=severity)


def nx5_save_report(payload, replace_equal=False, db_path=None):
    """Idempotente por contenido; un corte nuevo reemplaza al anterior por asesor/mes."""
    path=str(db_path or DB_PATH);meta=payload.get('metadata',{});period=meta.get('period','')
    if not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])',period):raise ValueError('El reporte necesita un período mensual válido.')
    start=meta.get('start_date','');end=meta.get('end_date','')
    if not start or not end or start[:7]!=period or end[:7]!=period or start>end:
        raise ValueError('Carga un corte de un solo mes con fechas desde/hasta válidas.')
    if start[-2:]!='01':
        raise ValueError('Para comparar la meta mensual, el corte debe comenzar el día 1. Descarga el reporte desde el primer día del mes.')
    sha=meta.get('sha256');rows=payload.get('advisors',[])
    if not sha or not rows:raise ValueError('No hay vendedores identificados para guardar.')
    codes=[str(r.get('advisor_code','')) for r in rows]
    if len(codes)!=len(set(codes)) or any(not c for c in codes):raise ValueError('Hay códigos de asesor vacíos o repetidos; no se guardó el corte.')
    result=dict(inserted=False,activated=0,older=0,conflicts=0,unchanged=0)
    with nx5_connection(path) as con:
        result['inserted']=bool(con.execute('INSERT OR IGNORE INTO nx5_sources VALUES(?,?,?,?,?)',
            (sha,period,meta.get('filename','Seguimiento'),nx5_json(payload),nx5_now())).rowcount)
        current=con.execute('SELECT a.advisor_code,a.sha,s.payload FROM nx5_active a JOIN nx5_sources s ON a.sha=s.sha WHERE a.period=?',(period,)).fetchall()
        existing={code:(oldsha,json.loads(raw)['metadata'].get('end_date','')) for code,oldsha,raw in current}
        for row in rows:
            code=str(row['advisor_code']);old=existing.get(code)
            if old and old[0]==sha: result['unchanged']+=1;continue
            if old and old[1]>end: result['older']+=1;continue
            if old and old[1]==end and not replace_equal:result['conflicts']+=1;continue
            con.execute('INSERT INTO nx5_active VALUES(?,?,?) ON CONFLICT(period,advisor_code) DO UPDATE SET sha=excluded.sha',(period,code,sha))
            result['activated']+=1
    return result


def nx5_restore_source(sha, db_path=None):
    """Restauración explícita de los asesores presentes; otros no se borran."""
    path=str(db_path or DB_PATH)
    with nx5_connection(path) as con:
        r=con.execute('SELECT payload FROM nx5_sources WHERE sha=?',(sha,)).fetchone()
        if not r:raise ValueError('El archivo ya no está disponible.')
        p=json.loads(r[0]);period=p['metadata']['period']
        for a in p['advisors']:
            con.execute('INSERT INTO nx5_active VALUES(?,?,?) ON CONFLICT(period,advisor_code) DO UPDATE SET sha=excluded.sha',(period,a['advisor_code'],sha))


def nx5_save_roster(period, rows, db_path=None):
    codes=[nx5_code(r.get('advisor_code')) for r in rows]
    if any(not c for c in codes) or len(codes)!=len(set(codes)):raise ValueError('Cada fila necesita un código distinto.')
    with nx5_connection(str(db_path or DB_PATH)) as con:
        for row,code in zip(rows,codes):
            r=dict(advisor_code=code,name=nx5_clean_text(row.get('name')),supervisor=nx5_clean_text(row.get('supervisor')),active=bool(row.get('active',True)),advisor_alias=nx5_clean_text(row.get('advisor_alias')))
            con.execute('INSERT INTO nx5_roster VALUES(?,?,?) ON CONFLICT(period,advisor_code) DO UPDATE SET payload=excluded.payload',(period,code,nx5_json(r)))


def nx5_save_goals(period, rows, db_path=None):
    fields=['sales_goal','activation_goal','new_goal','collections_goal']
    prepared=[];seen=set()
    for row in rows:
        code=nx5_code(row.get('advisor_code'))
        if not code or code in seen:raise ValueError('Las metas tienen códigos vacíos o repetidos.')
        seen.add(code);r={}
        for field in fields:
            raw=row.get(field);val=nx5_number(raw)
            if nx5_clean_text(raw) and val is None and not (isinstance(raw,float) and math.isnan(raw)):
                raise ValueError(f'{code}: valor no numérico en {field}.')
            if val is not None and val<0:raise ValueError(f'{code}: una meta no puede ser negativa.')
            if field in {'activation_goal','new_goal'} and val is not None and val!=int(val):raise ValueError('Las metas de clientes deben ser números enteros.')
            r[field]=val if val and val>0 else None
        if 'allocation_pct' in row:r['allocation_pct']=nx5_number(row.get('allocation_pct'))
        prepared.append((code,r))
    with nx5_connection(str(db_path or DB_PATH)) as con:
        for code,r in prepared:
            if 'allocation_pct' not in r:
                old=con.execute('SELECT payload FROM nx5_goals WHERE period=? AND advisor_code=?',(period,code)).fetchone()
                r['allocation_pct']=json.loads(old[0]).get('allocation_pct') if old else None
            con.execute('INSERT INTO nx5_goals VALUES(?,?,?,?) ON CONFLICT(period,advisor_code) DO UPDATE SET payload=excluded.payload,updated_at=excluded.updated_at',(period,code,nx5_json(r),nx5_now()))
    return len(prepared)


def nx5_save_line_goals(period,rows, db_path=None):
    allowed={'brands','departments','categories'};prepared=[];seen=set()
    for row in rows:
        code=nx5_code(row.get('advisor_code'));dim=row.get('dimension','brands');name=nx5_clean_text(row.get('name'));linecode=nx5_clean_text(row.get('code'))
        key=nx5_key(linecode or name);goal=nx5_number(row.get('goal'))
        if not code or dim not in allowed or not key:raise ValueError('Cada meta de línea requiere asesor, dimensión y nombre/código.')
        if goal is not None and goal<0:raise ValueError('La meta de una línea no puede ser negativa.')
        if (code,dim,key) in seen:raise ValueError('Hay metas repetidas para una misma línea y asesor.')
        seen.add((code,dim,key));prepared.append((code,dim,key,dict(advisor_code=code,dimension=dim,name=name,code=linecode,goal=goal if goal and goal>0 else None)))
    with nx5_connection(str(db_path or DB_PATH)) as con:
        for code,dim,key,row in prepared:
            con.execute('INSERT INTO nx5_line_goals VALUES(?,?,?,?,?) ON CONFLICT(period,advisor_code,dimension,line_key) DO UPDATE SET payload=excluded.payload',(period,code,dim,key,nx5_json(row)))


def nx5_legacy_context(period,db_path=None):
    path=db_path or DB_PATH;rows=[];issues=[]
    try:
        old=commercial_dataset_v4(commercial_sources_v4(path),period)
        for r in old['advisors']:
            rows.append(dict(advisor_code=r['advisor_code'],label=r.get('advisor') or r['advisor_code'],name=r.get('advisor'),supervisor=r.get('supervisor'),active=True,
                portfolio=r.get('portfolio'),activated_reported=r.get('activated'),activation_pct_reported=(r.get('activation_pct') or 0)*100,
                sales_reported=r.get('sales_actual'),collections=r.get('collections'),sales_goal=r.get('sales_goal'),new_goal=r.get('new_goal'),new_reported=r.get('new_achieved'),
                inactive_reported=r.get('inactive'),start_date=period+'-01',end_date=r.get('cutoff'),source_page=None,source_filename=r.get('source'),
                clients_activated=[],clients_inactive=[],clients_new=[],brands=[],departments=[],categories=[],printed_totals={},issues=[],legacy=True))
        issues=[nx5_issue(s,'legacy_review') for s in old.get('issues',[])]
    except (sqlite3.Error,KeyError,ValueError):pass
    if not rows:
        try:
            with nx5_connection(str(path)) as con:
                con.row_factory=sqlite3.Row
                old=con.execute('SELECT p.*,a.name,s.name AS supervisor FROM advisor_performance p JOIN advisors a ON p.advisor_code=a.advisor_code LEFT JOIN supervisors s ON a.supervisor_code=s.supervisor_code WHERE p.period=?',(period,)).fetchall()
            for r in old:
                r=dict(r);rows.append(dict(advisor_code=r['advisor_code'],label=r['name'],name=r['name'],supervisor=r.get('supervisor'),active=True,portfolio=r.get('portfolio'),activated_reported=r.get('activated'),sales_reported=r.get('sales_actual'),sales_goal=r.get('sales_goal'),new_goal=r.get('new_goal'),new_reported=r.get('new_achieved'),collections=None,start_date=period+'-01',end_date=None,source_page=None,source_filename=r.get('source'),clients_activated=[],clients_inactive=[],clients_new=[],brands=[],departments=[],categories=[],printed_totals={},issues=[],legacy=True))
        except sqlite3.Error:pass
    return rows,issues


def nx5_context(period, db_path=None):
    path=str(db_path or DB_PATH);issues=[];sources=[];rows=[]
    with nx5_connection(path) as con:
        active=con.execute('SELECT advisor_code,sha FROM nx5_active WHERE period=?',(period,)).fetchall()
        payloads={sha:json.loads(raw) for sha,raw in con.execute('SELECT sha,payload FROM nx5_sources WHERE period=?',(period,)).fetchall()}
        roster={c:json.loads(p) for c,p in con.execute('SELECT advisor_code,payload FROM nx5_roster WHERE period=?',(period,))}
        goals={c:json.loads(p) for c,p in con.execute('SELECT advisor_code,payload FROM nx5_goals WHERE period=?',(period,))}
        line_goals=[json.loads(p) for p, in con.execute('SELECT payload FROM nx5_line_goals WHERE period=?',(period,))]
        actions={c:json.loads(p) for c,p in con.execute('SELECT advisor_code,payload FROM nx5_actions WHERE period=?',(period,))}
    for code,sha in active:
        p=payloads.get(sha)
        if not p:continue
        original=next((r for r in p['advisors'] if str(r['advisor_code'])==code),None)
        if original is None:continue
        r=dict(original);m=p['metadata'];r.update(start_date=m.get('start_date'),end_date=m.get('end_date'),source_filename=m.get('filename'),source_sha=sha)
        rows.append(r)
        if not any(s.get('sha256')==sha for s in sources):
            sources.append(m)
            issues.extend(dict(it) if isinstance(it,dict) else nx5_issue(str(it)) for it in p.get('issues',[]))
    if not rows:
        rows,issues=nx5_legacy_context(period,path)
    else:
        legacy_rows,legacy_issues=nx5_legacy_context(period,path)
        inherited=False
        for r in rows:
            keys={nx5_code(r['advisor_code']),nx5_code(r.get('advisor_alias'))}
            alias=nx5_code(r.get('advisor_alias'))
            if alias:keys.add(re.split(r'[-\s]',alias)[0])
            matches=[old for old in legacy_rows if nx5_code(old.get('advisor_code')) in keys]
            if len(matches)>1:
                issues.append(nx5_issue('Más de una identidad histórica coincide por código/alias; confirma el nombre y la cuota en Configuración.','legacy_identity_ambiguous',r.get('source_page'),r['advisor_code']))
            elif len(matches)==1:
                old=matches[0]
                if not str(old.get('name') or '').startswith('Identidad por confirmar'):
                    for k in ['name','supervisor','sales_goal','new_goal','activation_goal','collections_goal']:
                        if old.get(k) is not None:r[k]=old[k]
                    r['legacy_goal_source']='Histórico del mismo período · '+str(old.get('advisor_code'))
                    inherited=True
        if inherited:issues.extend(legacy_issues)
    photo_enabled=nx52_photo_period(period) if 'nx52_photo_period' in globals() else False
    for r in rows:
        code=str(r['advisor_code']);reg=roster.get(code,{})
        photo=nx52_photo_match(r,period,enabled=photo_enabled) if 'nx52_photo_match' in globals() else None
        if photo and photo.get('ambiguous'):
            issues.append(nx5_issue('Código y alias coinciden con personas distintas de la foto; confirma la identidad.','photo_identity_ambiguous',r.get('source_page'),code));photo=None
        r['photo_roster']=bool(photo)
        known_from_source=bool(r.get('name') and r.get('name') not in {r.get('label'),code,'Asesor '+code} and not str(r.get('name')).startswith('Identidad por confirmar'))
        r['name_confirmed']=bool(reg.get('name') or (photo and photo.get('name')) or known_from_source)
        photo_name=photo.get('name','').title() if photo else ''
        vacant=bool(photo and photo.get('vacant') and (not reg.get('name') or nx5_key(reg['name']).startswith('VACANTE')))
        if vacant and not reg.get('name'):photo_name='Vacante · movimientos del código '+photo['numeric_code']
        r['name']=reg.get('name') or photo_name or r.get('name') or r.get('label') or code
        r['supervisor']=reg.get('supervisor') or (photo.get('supervisor') if photo else None) or r.get('supervisor') or 'Por asignar'
        if 'nx52_supervisor_name' in globals():r['supervisor']=nx52_supervisor_name(r['supervisor'])
        r['active']=reg.get('active',not vacant);r['advisor_alias']=reg.get('advisor_alias') or r.get('advisor_alias','')
        if photo:r['roster_source']='Foto recibida el 30/10/2026 · código '+photo['numeric_code']
        if vacant:issues.append(nx5_issue('El código figura VACANTE en la estructura actual. Se conservan los movimientos reportados sin atribuirlos a una nueva persona.','vacant_code_with_history',r.get('source_page'),code,'info'))
        if code in goals:r.update(goals[code])
        r['actions']=actions.get(code,{})
        if 'new_reported' not in r:r['new_reported']=r.get('section_counts',{}).get('clients_new')
        if 'inactive_reported' not in r:r['inactive_reported']=r.get('section_counts',{}).get('clients_inactive')
        if not r.get('legacy') and 'section_counts' in r and 'clients_inactive' not in r['section_counts']:
            r['inactive_reported']=None
        goal=r.get('sales_goal');sale=r.get('sales_reported')
        r['sales_attainment']=sale/goal if sale is not None and goal and goal>0 else None
        r['sales_gap']=max(0,goal-sale) if sale is not None and goal and goal>0 else None
        for issue in r.get('issues',[]):
            it=dict(issue) if isinstance(issue,dict) else nx5_issue(str(issue));it['advisor_code']=code;issues.append(it)
        if not r['name_confirmed'] and (not r.get('legacy')):issues.append(nx5_issue('Nombre completo pendiente de confirmar.','roster_name',r.get('source_page'),code,'info'))
        if r['supervisor']=='Por asignar':issues.append(nx5_issue('Supervisor del período pendiente de asignar.','roster_supervisor',r.get('source_page'),code,'info'))
    cuts=sorted({r.get('end_date') for r in rows if r.get('end_date')})
    photo_count=sum(r.get('photo_roster',False) for r in rows)
    if photo_count:issues.append(nx5_issue(f'Estructura de la foto recibida el 30/10/2026: {photo_count} códigos coinciden. Nombres y asignaciones manuales del período tienen prioridad.','photo_roster_source',severity='info'))
    if len(cuts)>1:issues.append(nx5_issue('Hay asesores con distintas fechas de corte. Revisa la columna Hasta antes de comparar los equipos.','mixed_cutoffs'))
    context=dict(period=period,start_date=min((r['start_date'] for r in rows if r.get('start_date')),default=period+'-01'),end_date=max(cuts,default=''),
        generated_at=nx5_now(),source=dict(filename='; '.join(s.get('filename','') for s in sources) or 'Histórico conservado'),sources=sources,
        advisors=sorted(rows,key=lambda r:str(r['advisor_code'])),issues=issues,brand_goals=line_goals,report_title='Seguimiento del equipo de ventas')
    context=nx55_apply_roster(context,path)
    context=nx54_enrich_context(context,path)
    context['quota_metrics']=[m for m in context.get('quota_metrics',[]) if m.get('metric')!='activation_rate_goal']
    return context


def nx5_filter_context(context, supervisor=None, selected=None, active_only=False):
    out=dict(context)
    rows=[dict(r) for r in context['advisors'] if (not supervisor or r.get('supervisor')==supervisor) and (not selected or r['advisor_code'] in selected) and (not active_only or r.get('active',True))]
    ids={r['advisor_code'] for r in rows};out['advisors']=rows
    out['issues']=[r for r in context['issues'] if r.get('code') not in {'mixed_cutoffs','photo_roster_source'} and (not r.get('advisor_code') or r['advisor_code'] in ids)]
    out['brand_goals']=[r for r in context['brand_goals'] if r.get('advisor_code') in ids]
    out['quota_metrics']=[r for r in context.get('quota_metrics',[]) if r.get('advisor_code') in ids]
    cuts=sorted({r.get('end_date') for r in rows if r.get('end_date')})
    out['start_date']=min((r.get('start_date') for r in rows if r.get('start_date')),default=context['period']+'-01')
    out['end_date']=max(cuts,default='')
    if len(cuts)>1:out['issues'].append(nx5_issue('Hay asesores con distintas fechas de corte. Revisa Hasta por asesor.','mixed_cutoffs'))
    photo_count=sum(r.get('photo_roster',False) for r in rows)
    if photo_count:out['issues'].append(nx5_issue(f'Estructura de la foto recibida el 30/10/2026: {photo_count} códigos de esta selección coinciden. Las correcciones manuales del período tienen prioridad.','photo_roster_source',severity='info'))
    used={r.get('source_sha') for r in rows if r.get('source_sha')}
    out['sources']=[s for s in context.get('sources',[]) if s.get('sha256') in used]
    names=list(dict.fromkeys(r.get('source_filename') for r in rows if r.get('source_filename')))
    out['issues']=[i for i in out['issues'] if not i.get('source_file') or i.get('source_file') in names]
    out['source']={'filename':'; '.join(names) or 'Histórico conservado'}
    delivery=context.get('report_delivery')
    if delivery and 'nx56_apply_report_context' in globals():
        out=nx56_apply_report_context(out,delivery['kind'],delivery['cutoff'],
            delivery.get('final_requested',False),delivery.get('undated_confirmed',False))
    return out


def nx5_periods(db_path=None):
    path=str(db_path or DB_PATH);result={nx5_now()[:7]}
    with nx5_connection(path) as con:
        for table in ['nx5_sources','nx5_goals','advisor_performance','nx55_results_sources']:
            if con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",(table,)).fetchone():result.update(r[0] for r in con.execute('SELECT DISTINCT period FROM '+table).fetchall())
    try:result.update(commercial_periods_v4(commercial_sources_v4(path)))
    except (sqlite3.Error,ValueError):pass
    return sorted(result,reverse=True)


def nx5_sources_table(period,db_path=None):
    with nx5_connection(str(db_path or DB_PATH)) as con:
        sources=con.execute('SELECT sha,filename,payload,created_at FROM nx5_sources WHERE period=? ORDER BY created_at DESC',(period,)).fetchall()
        active=dict(con.execute('SELECT sha,COUNT(*) FROM nx5_active WHERE period=? GROUP BY sha',(period,)).fetchall())
    return [dict(sha=sha,Archivo=name,Desde=json.loads(raw)['metadata'].get('start_date'),Hasta=json.loads(raw)['metadata'].get('end_date'),Asesores=len(json.loads(raw)['advisors']),En_uso=active.get(sha,0),Guardado=created) for sha,name,raw,created in sources]


def nx5_goal_rows(context):
    return [dict(advisor_code=r['advisor_code'],name=r.get('name',''),supervisor=r.get('supervisor',''),
        **{k:r.get(k) for k in ['sales_goal','activation_goal','new_goal','collections_goal']}) for r in context['advisors']]


def nx5_allocate_goals(total,weighted_rows):
    """Reparte centavos sin alterar el total aprobado por diferencias de redondeo."""
    from decimal import Decimal,ROUND_HALF_UP,ROUND_FLOOR
    amount=Decimal(str(total)).quantize(Decimal('.01'),rounding=ROUND_HALF_UP)
    weights=[Decimal(str(nx5_number(r.get('allocation_pct')) or 0)) for r in weighted_rows]
    weight_sum=sum(weights,Decimal(0))
    if amount<=0 or any(w<0 or w>100 for w in weights) or abs(weight_sum-100)>Decimal('.005'):
        raise ValueError('Indica un monto positivo y porcentajes entre 0 y 100 que sumen 100 %.')
    exact=[amount*w/weight_sum for w in weights]
    rounded=[v.quantize(Decimal('.01'),rounding=ROUND_FLOOR) for v in exact]
    cents=int((amount-sum(rounded,Decimal(0)))/Decimal('.01'))
    order=sorted(range(len(exact)),key=lambda i:(exact[i]-rounded[i],-i),reverse=True)
    for idx in order[:cents]:rounded[idx]+=Decimal('.01')
    return [dict(r,sales_goal=float(value),allocation_pct=float(weight)) for r,value,weight in zip(weighted_rows,rounded,weights)]


def nx5_resolve_code(raw,context):
    target=nx5_code(raw)
    direct=[r['advisor_code'] for r in context['advisors'] if nx5_code(r['advisor_code'])==target]
    if len(direct)==1:return direct[0]
    alternatives=[]
    for r in context['advisors']:
        alias=nx5_code(r.get('advisor_alias'))
        label=nx5_code(r.get('label'))
        if target and (target==alias or target==label or (alias and re.split(r'[-\s]',alias)[0]==target)):
            alternatives.append(r['advisor_code'])
    if len(set(alternatives))==1:return alternatives[0]
    raise ValueError('Código '+target+': no coincide de forma única con los asesores del período. Usa el código que aparece en la plantilla.')


def nx5_read_goal_upload(raw,filename,period,context):
    """Acepta tabla de cuotas por período; nunca lee %VENTAS como meta."""
    import io
    if filename.lower().endswith('.csv'):
        try:df=pd.read_csv(io.BytesIO(raw),dtype=object,sep=None,engine='python')
        except UnicodeDecodeError:df=pd.read_csv(io.BytesIO(raw),dtype=object,sep=None,engine='python',encoding='cp1252')
    else:
        sheets=pd.read_excel(io.BytesIO(raw),sheet_name=None,header=None,dtype=object)
        candidate=None
        for name,frame in sheets.items():
            for idx in range(min(35,len(frame))):
                keys={nx5_key(v) for v in frame.iloc[idx].tolist() if pd.notna(v)}
                if keys & {'CODIGO','CODIGOASESOR','ASESOR','ADVISORCODE'} and keys & {'METAVENTAUSD','METAVENTASUSD','METAVENTA','CUOTA','SALESGOAL','METAACTIVADOS','METANUEVOS','METACOBROSUSD','NEWGOAL','ACTIVATIONGOAL','COLLECTIONSGOAL'}:
                    candidate=(frame,idx);break
            if candidate:break
        if candidate is None:raise ValueError('No se reconoció una tabla de cuotas. Descarga la plantilla y pega las metas del jefe allí; los resultados de ventas no se importan como cuotas.')
        frame,idx=candidate;df=frame.iloc[idx+1:].copy();df.columns=[nx5_clean_text(v) for v in frame.iloc[idx]]
    aliases={'CODIGO':'advisor_code','CODIGOASESOR':'advisor_code','ASESOR':'advisor_code','ADVISORCODE':'advisor_code',
        'PERIODO':'period','MES':'period','PERIOD':'period','METAVENTAUSD':'sales_goal','METAVENTASUSD':'sales_goal','METAVENTA':'sales_goal','CUOTA':'sales_goal','SALESGOAL':'sales_goal',
        'METAACTIVADOS':'activation_goal','ACTIVATIONGOAL':'activation_goal','METANUEVOS':'new_goal','NEWGOAL':'new_goal','METACOBROSUSD':'collections_goal','COLLECTIONSGOAL':'collections_goal',
        'NOMBRE':'name','SUPERVISOR':'supervisor'}
    renamed={c:aliases[nx5_key(c)] for c in df.columns if nx5_key(c) in aliases};df=df.rename(columns=renamed)
    if 'advisor_code' not in df or not any(k in df for k in ['sales_goal','activation_goal','new_goal','collections_goal']):raise ValueError('Faltan código de asesor y columnas de meta.')
    if df.columns.duplicated().any():raise ValueError('Hay encabezados duplicados; revisa la plantilla.')
    records=[]
    for source in df.to_dict('records'):
        if not nx5_clean_text(source.get('advisor_code')):continue
        stated=nx5_clean_text(source.get('period'))
        if stated and stated!=period:raise ValueError(f'La cuota indica {stated}, pero seleccionaste {period}. Cambia el período antes de importar.')
        code=nx5_resolve_code(source['advisor_code'],context)
        previous=next((r for r in nx5_goal_rows(context) if r['advisor_code']==code),{'advisor_code':code})
        record=dict(previous)
        for k in ['name','supervisor']:
            if nx5_clean_text(source.get(k)):record[k]=nx5_clean_text(source[k])
        for k in ['sales_goal','activation_goal','new_goal','collections_goal']:
            if k in source:record[k]=source[k]
        records.append(record)
    if not records:raise ValueError('El archivo no contiene filas de cuotas.')
    return records


def nx5_quota_template(context):
    out=io.BytesIO()
    with pd.ExcelWriter(out,engine='xlsxwriter',engine_kwargs={'options':{'strings_to_formulas':False,'strings_to_urls':False}}) as writer:
        rows=[dict(Periodo=context['period'],Codigo=r['advisor_code'],Nombre=r.get('name',''),Supervisor=r.get('supervisor',''),Meta_venta_USD=r.get('sales_goal'),Meta_activados=r.get('activation_goal'),Meta_nuevos=r.get('new_goal'),Meta_cobros_USD=r.get('collections_goal')) for r in context['advisors']]
        pd.DataFrame(rows,columns=['Periodo','Codigo','Nombre','Supervisor','Meta_venta_USD','Meta_activados','Meta_nuevos','Meta_cobros_USD']).to_excel(writer,sheet_name='Cuotas',index=False)
        ws=writer.sheets['Cuotas'];ws.freeze_panes(1,2);ws.autofilter(0,0,max(1,len(rows)),7);ws.set_column(0,1,14);ws.set_column(2,3,26);ws.set_column(4,7,20,writer.book.add_format({'num_format':'0.00','font_color':'#1d4ed8'}))
        fmt=writer.book.add_format({'bold':True,'font_color':'#ffffff','bg_color':'#122b51','text_wrap':True})
        for c,label in enumerate(['Periodo','Codigo','Nombre','Supervisor','Meta_venta_USD','Meta_activados','Meta_nuevos','Meta_cobros_USD']):ws.write(0,c,label,fmt)
        ws.set_row(0,30)
    return out.getvalue()


def nx5_reconciliation(context):
    records=[]
    for r in context['advisors']:
        for dim,label in [('departments','Departamento'),('brands','Marca'),('categories','Categoría')]:
            total=r.get('printed_totals',{}).get(dim)
            if total is None:continue
            amount=total.get('amount') if isinstance(total,dict) else total
            if amount is None:continue
            sale=r.get('sales_reported')
            records.append({'Código':r['advisor_code'],'Asesor':r.get('name') or r.get('label'), 'Dimensión':label,'Venta cabecera USD':sale,'Total desglose USD':amount,
                'Diferencia USD':round(float(sale)-float(amount),2) if sale is not None else None,'Página cabecera':r.get('source_page'),'Página desglose':total.get('source_page') if isinstance(total,dict) else None})
    return records


