# Estructura recibida en la fotografía del 30/10/2026. No reemplaza correcciones del usuario.
def nx52_photo_period(period):
    return bool(period and period >= _NX52_PHOTO_ROSTER['from_period'] and nx5_pref('nx52_photo_enabled',True))


def nx52_numeric_alias(row):
    for value in [row.get('advisor_alias'),row.get('advisor_code')]:
        m=re.match(r'^(\d+)(?:\b|[-\s])',nx5_code(value))
        if m:return m.group(1)
    return None


def nx52_photo_match(row,period,enabled=None):
    if not (nx52_photo_period(period) if enabled is None else enabled):return None
    candidates=set()
    for value in [row.get('advisor_code'),row.get('advisor_alias')]:
        text=nx5_code(value);m=re.match(r'^(\d+)(?:\b|[-\s])',text)
        if m:candidates.add(m.group(1))
    known={r['numeric_code']:r for r in _NX52_PHOTO_ROSTER['rows']}
    matches=[known[c] for c in candidates if c in known]
    if len(matches)==1:return dict(matches[0])
    if len(matches)>1:return {'ambiguous':True,'codes':sorted(r['numeric_code'] for r in matches)}
    return None


def nx52_supervisor_name(value):
    canonical={'JOHANAMARCANO':'Johana Marcano','JOSEASSAL':'José Assal','JONATHANRUIZ':'Jonathan Ruiz','JORGENEMNOM':'Jorge Nemnom','DANIELMARQUEZ':'Daniel Márquez','PORASIGNAR':'Por asignar'}
    return canonical.get(nx5_key(value),nx5_clean_text(value) or 'Por asignar')


def nx52_report_identity(row):
    if str(row.get('advisor_code') or '').startswith('ACT-'):return 'Sin código A2'
    code=str(row.get('advisor_code') or '')
    number=nx52_numeric_alias(row)
    return number+' / A2 '+code if number and number!=code else (number or code)


def nx52_roster_overview(context):
    source=_NX52_PHOTO_ROSTER;rows=context.get('advisors',[])
    missing=[r for r in rows if not r.get('photo_roster') and not r.get('name_confirmed')]
    missing_supervisors=[r for r in rows if r.get('supervisor')=='Por asignar']
    covered=[r for r in rows if r.get('photo_roster')]
    keys={nx52_numeric_alias(r) for r in rows}
    absent=[r for r in source['rows'] if r['numeric_code'] not in keys]
    return dict(covered=covered,missing=missing,missing_supervisors=missing_supervisors,absent=absent)


def nx52_roster_photo_ui(context):
    st.caption('Estructura leída de la foto recibida el 30/10/2026. Se usa desde octubre de 2026; tus correcciones guardadas para un mes tienen prioridad. La foto no declara una fecha de vigencia.')
    if context['period']<_NX52_PHOTO_ROSTER['from_period']:
        st.info('Esta estructura no se aplica a períodos anteriores a octubre de 2026. Se conservan sus responsables históricos.');return
    enabled=st.toggle('Usar la estructura de la foto como base',value=nx5_pref('nx52_photo_enabled',True),key='nx52_photo_enabled_toggle')
    if enabled!=nx5_pref('nx52_photo_enabled',True):
        nx5_set_pref('nx52_photo_enabled',enabled);st.rerun()
    if not enabled:return
    info=nx52_roster_overview(context)
    a,b,c=st.columns(3);a.metric('Códigos vinculados a la foto',len(info['covered']));b.metric('Nombres por confirmar',len(info['missing']));c.metric('Supervisores por confirmar',len(info['missing_supervisors']))
    if info['missing']:
        st.warning('La foto no identifica estos códigos de la fuente: '+', '.join(str(nx52_numeric_alias(r) or r['advisor_code']) for r in info['missing'])+'. Puedes completar sus nombres en la tabla de abajo.')
    if info['missing_supervisors']:
        st.caption('Supervisor pendiente: '+', '.join(str(nx52_numeric_alias(r) or r['advisor_code']) for r in info['missing_supervisors'])+'. No se asignan a un supervisor por cercanía en la foto.')
    if info['absent']:
        st.caption('En la foto aparecen sin resultados en este reporte: '+', '.join(r['numeric_code']+' · '+r['name'].title() for r in info['absent'])+'. Sus resultados se incorporarán cuando vengan en la fuente.')
    st.caption('El código 115 figura VACANTE. Su actividad ya reportada permanece identificada como movimientos del código, sin atribuirla a una persona nueva.')


