    doc=NX51Document(output,pagesize=A4,leftMargin=M,rightMargin=M,topMargin=83,bottomMargin=51,
        title=nx5_export_text(context.get('report_title') or 'Seguimiento comercial completo'),author='Makropetrol',pageCompression=1)
    def frame():return Frame(M,51,U,H-134,id='normal',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)
