        story += [table(data,[U*.235,U*.075,U*.14,U*.125,U*.10,U*.06,U*.085,U*.18],small=True),p('N/D = dato no informado; no equivale a cero. Act. = activados según programa. Nuevos puede solaparse con activados o no activados.','NX51Small')]
