            if obj:line_values.append(obj['value'])
            obj=add('line_sales_goal',get(row,3),ref,advisor,sup,sheet,cell(rn,3),'Logro / '+label,line_name=label,actual=True)
            if obj:line_actuals.append(obj['value'])
